import tower;
import '../library/vector';

// COFF short-import metadata in a deterministic single-symbol archive. This
// contains no owned machine-code implementation: upstream LLD builds the import
// thunk and Windows supplies the function. The archive makes the import lazy.
// PE/COFF specification: archive linker member and import library header.
const CoffArchiveMagicBytes: usize = 8;
const CoffArchiveHeaderBytes: usize = 60;
const CoffShortImportHeaderBytes: usize = 20;
const CoffMachineAmd64: u32 = 34404;
const CoffImportCodeByName: u32 = 4;

fn coff_unsigned(data: u8*, number: u32, count: usize, big: bool): void {
    var i: usize = 0;
    while i < count {
        var at = i;
        if big {
            at = count - i;
            at = at - 1;
        }
        var byte = number & 255;
        data[at] = convert(u8, byte);
        number = number / 256;
        i = i + 1;
    }
}

fn coff_archive_header(data: u8*, name: u8*, name_size: usize, size: usize): void {
    fill(data, 32, CoffArchiveHeaderBytes());
    copy(data, name, name_size);
    // Fixed-width ASCII date, owner, group and mode. Timestamp zero is stable.
    data[16] = 48;
    data[28] = 48;
    data[34] = 48;
    data[40] = 48;
    var digits: u8[20];
    var count: usize = 0;
    loop {
        var digit = size % 10;
        digit = digit + 48;
        digits[count] = convert(u8, digit);
        count = count + 1;
        size = size / 10;
        var done = size == 0;
        if done {
            break;
        }
    }
    var i: usize = 48;
    while count != 0 {
        count = count - 1;
        data[i] = digits[count];
        i = i + 1;
    }
    data[58] = 96;
    data[59] = 10;
}

fn coff_name_length(name: u8*): usize {
    var i: usize = 0;
    while name[i] != 0 {
        i = i + 1;
    }
    return i;
}

fn coff_import_archive(out: vector(u8)*, machine: u32, symbol: u8*, dll: u8*): bool {
    var symbol_size = coff_name_length(symbol) + 1;
    var dll_size = coff_name_length(dll) + 1;
    var valid = symbol_size > 1;
    if valid {
        valid = symbol_size <= 65536;
    }
    if valid {
        valid = dll_size > 1;
    }
    if valid {
        valid = dll_size <= 65536;
    }
    if valid {
        valid = machine <= 65535;
    }
    if valid {} else {
        return false;
    }
    // Big-endian symbol count and member offset, then the NUL-terminated name.
    var linker_size = 8 + symbol_size;
    var padding = linker_size & 1;
    var member = CoffArchiveMagicBytes() + CoffArchiveHeaderBytes();
    member = member + linker_size;
    member = member + padding;
    var data_size = symbol_size + dll_size;
    var object_size = CoffShortImportHeaderBytes() + data_size;
    var total = member + CoffArchiveHeaderBytes();
    total = total + object_size;
    padding = object_size & 1;
    total = total + padding;
    if vector_reserve(u8, out, total) {} else {
        return false;
    }
    out.length = total;
    fill(out.data, 0, total);
    copy(out.data, "!<arch>\n", CoffArchiveMagicBytes());
    var header = &out.data[CoffArchiveMagicBytes()];
    coff_archive_header(header, "/", 1, linker_size);
    var data = header + CoffArchiveHeaderBytes();
    coff_unsigned(data, 1, 4, true);
    coff_unsigned(&data[4], convert(u32, member), 4, true);
    copy(&data[8], symbol, symbol_size);
    var odd = linker_size & 1;
    var padded = odd != 0;
    if padded {
        data[linker_size] = 10;
    }
    header = &out.data[member];
    coff_archive_header(header, "import.obj/", 11, object_size);
    data = header + CoffArchiveHeaderBytes();
    // IMPORT_OBJECT_HEADER: signature, version, machine, timestamp, payload
    // length, hint, and IMPORT_CODE | (IMPORT_NAME << 2). All little endian.
    coff_unsigned(&data[2], 65535, 2, false);
    coff_unsigned(&data[6], machine, 2, false);
    coff_unsigned(&data[12], convert(u32, data_size), 4, false);
    coff_unsigned(&data[18], CoffImportCodeByName(), 2, false);
    data = data + CoffShortImportHeaderBytes();
    copy(data, symbol, symbol_size);
    copy(&data[symbol_size], dll, dll_size);
    padded = padding != 0;
    if padded {
        var last = total - 1;
        out.data[last] = 10;
    }
    return true;
}

import tower;

// The only semantic inputs are existing Foundation entities. LLVM references,
// local slots and entity/value associations below are disposable lowering caches.
extern fn sem_get(node: void*): FoundationNode*;

extern fn semantic_size(type: FoundationType*): usize;

extern fn semantic_alignment(type: FoundationType*): usize;

extern fn semantic_width(type: FoundationType*): u32;

extern fn semantic_signed(type: FoundationType*): bool;

extern fn semantic_aggregate(type: FoundationType*): bool;

extern fn semantic_type_equal(a: FoundationType*, b: FoundationType*): bool;

struct BackendAssociation {
    entity: void*;
    value: void*;
}

struct BackendLoop {
    head: void*;
    after: void*;
}

struct Backend {
    context: void*;
    module: void*;
    builder: void*;
    machine: void*;
    layout: void*;
    pointer_bytes: u32;
    wasm: bool;
    foreign_profile: u32;
    i8: void*;
    i32: void*;
    i64: void*;
    size_type: void*;
    pointer_type: void*;
    functions: vector(void*);
    symbols: vector(u8*);
    source_functions: vector(void*);
    source_root: void*;
    locals: vector(void*);
    globals: vector(BackendAssociation);
    strings: vector(BackendAssociation);
    loops: vector(BackendLoop);
    labels: vector(BackendAssociation);
    current: void*;
    print_fn: void*;
    trap_fn: void*;
    allocate_fn: void*;
    reallocate_fn: void*;
    deallocate_fn: void*;
    source_offset: usize;
    error_offset: usize;
    error: vector(u8);
    raw: u8*;
    optimized: u8*;
    object: void*;
}

fn backend_fail(b: Backend*, text: u8*): void {
    var first = b.error.length == 0;
    if first {
        backend_text(&b.error, text);
        b.error_offset = b.source_offset;
    }
}

fn backend_require(b: Backend*, ok: bool): void {
    var failed = ok == false;
    if failed {
        backend_fail(b, "Unable to allocate backend storage");
    }
}

fn backend_name(n: FoundationNode*): u8* {
    var absent = n.name.data == null;
    if absent {
        return "";
    }
    return n.name.data;
}

fn backend_associate(values: vector(BackendAssociation)*, entity: void*, value: void*): bool {
    var needed = values.length + 1;
    var ok = vector_reserve(BackendAssociation, values, needed);
    if ok {
        values.data[values.length].entity = entity;
        values.data[values.length].value = value;
        values.length = needed;
    }
    return ok;
}

fn backend_find(values: vector(BackendAssociation)*, entity: void*): void* {
    var i: usize = 0;
    loop {
        var done = i == values.length;
        if done {
            return null;
        }
        var found = values.data[i].entity == entity;
        if found {
            return values.data[i].value;
        }
        i = i + 1;
    }
}

export fn backend_error(b: Backend*): u8* {
    var empty = b.error.data == null;
    if empty {
        return "";
    }
    return b.error.data;
}

export fn backend_error_offset(b: Backend*): usize {
    return b.error_offset;
}

export fn backend_pointer_bytes(b: Backend*): u32 {
    return b.pointer_bytes;
}

export fn backend_raw(b: Backend*): u8* {
    return b.raw;
}

export fn backend_optimized(b: Backend*): u8* {
    return b.optimized;
}

export fn backend_bytes(b: Backend*): u8* {
    var present = b.object != null;
    if present {
        return LLVMGetBufferStart(b.object);
    }
    return null;
}

export fn backend_size(b: Backend*): usize {
    var present = b.object != null;
    if present {
        return LLVMGetBufferSize(b.object);
    }
    return 0;
}

export fn backend_close(b: Backend*): void {
    var present = b == null;
    if present {
        return;
    }
    present = b.object != null;
    if present {
        LLVMDisposeMemoryBuffer(b.object);
    }
    present = b.raw != null;
    if present {
        LLVMDisposeMessage(b.raw);
    }
    present = b.optimized != null;
    if present {
        LLVMDisposeMessage(b.optimized);
    }
    present = b.builder != null;
    if present {
        LLVMDisposeBuilder(b.builder);
    }
    present = b.module != null;
    if present {
        LLVMDisposeModule(b.module);
    }
    present = b.layout != null;
    if present {
        LLVMDisposeTargetData(b.layout);
    }
    present = b.machine != null;
    if present {
        LLVMDisposeTargetMachine(b.machine);
    }
    present = b.context != null;
    if present {
        LLVMContextDispose(b.context);
    }
    var i: usize = 0;
    loop {
        var done = i == b.symbols.length;
        if done {
            break;
        }
        free(b.symbols.data[i]);
        i = i + 1;
    }
    vector_dispose(u8*, &b.symbols);
    vector_dispose(void*, &b.functions);
    vector_dispose(void*, &b.source_functions);
    vector_dispose(void*, &b.locals);
    vector_dispose(BackendAssociation, &b.globals);
    vector_dispose(BackendAssociation, &b.strings);
    vector_dispose(BackendLoop, &b.loops);
    vector_dispose(BackendAssociation, &b.labels);
    vector_dispose(u8, &b.error);
    free(b);
}

export fn backend_function_name(b: Backend*, index: usize): u8* {
    // O2 may erase unused LLVM declarations. Keep result names independently
    // of LLVM value lifetimes, while Foundation entities retain source spelling.
    var name = b.symbols.data[index];
    var empty = name == null;
    if empty {
        return "";
    }
    return name;
}

import tower;

// Object inspection is separate from semantics. Bytes here are platform output.
struct BackendLabel {
    address: u64;
    name: vector(u8);
    priority: u32;
}

struct BackendDecoder {
    llvm: void*;
    text: vector(u8);
    data: u8*;
    length: usize;
    offset: usize;
    end: usize;
    failed: bool;
    labels: vector(BackendLabel);
    instruction_labels: bool;
}

fn backend_label_index(d: BackendDecoder*, address: u64): usize {
    var first: usize = 0;
    var last = d.labels.length;
    loop {
        var done = first == last;
        if done {
            return first;
        }
        var distance = last - first;
        distance = distance / 2;
        var middle = first + distance;
        var smaller = d.labels.data[middle].address < address;
        if smaller {
            first = middle + 1;
        }
        else {
            last = middle;
        }
    }
}

fn backend_label_add(d: BackendDecoder*, address: u64, name: u8*, length: usize, priority: u32): void {
    var empty = length == 0;
    if empty {
        return;
    }
    var index = backend_label_index(d, address);
    var found = index < d.labels.length;
    if found {
        found = d.labels.data[index].address == address;
    }
    if found {
        var better = d.labels.data[index].priority > priority;
        if better {
            return;
        }
        d.labels.data[index].name.length = 0;
    } else {
        var needed = d.labels.length + 1;
        var ok = vector_reserve(BackendLabel, &d.labels, needed);
        var failed = ok == false;
        if failed {
            d.failed = true;
            return;
        }
        var remaining = d.labels.length - index;
        var count = remaining * sizeof(BackendLabel);
        var next = index + 1;
        copy(&d.labels.data[next], &d.labels.data[index], count);
        fill(&d.labels.data[index], 0, sizeof(BackendLabel));
        d.labels.data[index].address = address;
        d.labels.length = needed;
    }
    backend_text_append(&d.labels.data[index].name, name, length);
    d.labels.data[index].priority = priority;
}

fn backend_label_name(d: BackendDecoder*, address: u64): u8* {
    var index = backend_label_index(d, address);
    var found = index < d.labels.length;
    if found {
        found = d.labels.data[index].address == address;
    }
    if found {
        return d.labels.data[index].name.data;
    }
    return null;
}

// The C object API omits SectionRef::isText. Read the standardized platform
// section flags, preserving executable sections with arbitrary user names.
fn backend_object_integer(d: BackendDecoder*, offset: u64, width: u64, little: bool): u64 {
    var length = convert(u64, d.length);
    var invalid = offset > length;
    if invalid {
        d.failed = true;
        return 0;
    }
    var remaining = length - offset;
    invalid = width > remaining;
    if invalid {
        d.failed = true;
        return 0;
    }
    var value: u64 = 0;
    var factor: u64 = 1;
    var i: u64 = 0;
    loop {
        var done = i == width;
        if done {
            return value;
        }
        var index = i;
        var big = little == false;
        if big {
            index = width - i;
            index = index - 1;
        }
        index = offset + index;
        var byte = convert(u64, d.data[convert(usize, index)]);
        var part = byte * factor;
        value = value + part;
        factor = factor * 256;
        i = i + 1;
    }
}

fn backend_section_text(d: BackendDecoder*, kind: u32, index: u64): bool {
    var elf = kind >= 6;
    if elf {
        elf = kind <= 9;
    }
    if elf {
        var wide = kind >= 8;
        var parity = kind % 2;
        var little = parity == 0;
        var table: u64 = 0;
        var stride: u64 = 0;
        var width: u64 = 4;
        if wide {
            table = backend_object_integer(d, 40, 8, little);
            stride = backend_object_integer(d, 58, 2, little);
            width = 8;
        } else {
            table = backend_object_integer(d, 32, 4, little);
            stride = backend_object_integer(d, 46, 2, little);
        }
        var offset = index * stride;
        offset = offset + table;
        offset = offset + 8;
        var flags = backend_object_integer(d, offset, width, little);
        flags = flags & 4;
        var text = flags != 0;
        return text;
    }
    var coff = kind == 5;
    if coff {
        var header: u64 = 0;
        var magic = backend_object_integer(d, 0, 2, true);
        var pe = magic == 23117;
        if pe {
            header = backend_object_integer(d, 60, 4, true);
            header = header + 4;
        }
        var optional_offset = header + 16;
        var optional = backend_object_integer(d, optional_offset, 2, true);
        var table = header + 20;
        table = table + optional;
        var big_object = magic == 0;
        if big_object {
            var signature = backend_object_integer(d, 2, 2, true);
            big_object = signature == 65535;
            if big_object {
                table = 56;
            }
        }
        var offset = index * 40;
        offset = offset + table;
        offset = offset + 36;
        var flags = backend_object_integer(d, offset, 4, true);
        flags = flags & 32;
        var text = flags != 0;
        return text;
    }
    var wide = kind >= 12;
    var parity = kind % 2;
    var little = parity == 0;
    var commands = backend_object_integer(d, 16, 4, little);
    var cursor: u64 = 28;
    var segment: u64 = 1;
    var header: u64 = 56;
    var stride: u64 = 68;
    var flags_offset: u64 = 56;
    if wide {
        cursor = 32;
        segment = 25;
        header = 72;
        stride = 80;
        flags_offset = 64;
    }
    var command: u64 = 0;
    loop {
        var done = command == commands;
        if d.failed {
            done = true;
        }
        if done {
            return false;
        }
        var tag = backend_object_integer(d, cursor, 4, little);
        var offset = cursor + 4;
        var bytes = backend_object_integer(d, offset, 4, little);
        var selected = tag == segment;
        if selected {
            offset = cursor + header;
            offset = offset - 8;
            var count = backend_object_integer(d, offset, 4, little);
            selected = index < count;
            if selected {
                offset = index * stride;
                offset = offset + cursor;
                offset = offset + header;
                offset = offset + flags_offset;
                var flags = backend_object_integer(d, offset, 4, little);
                flags = flags & 2147483648;
                var text = flags != 0;
                return text;
            }
            index = index - count;
        }
        cursor = cursor + bytes;
        command = command + 1;
    }
}

fn backend_hex(out: vector(u8)*, value: u64, digits: usize): void {
    var buffer: u8[18];
    var i = digits;
    var alphabet: u8* = "0123456789abcdef";
    loop {
        var done = i == 0;
        if done {
            break;
        }
        var remainder = value % 16;
        var digit = convert(usize, remainder);
        buffer[i] = alphabet[digit];
        value = value / 16;
        i = i - 1;
    }
    backend_text(out, "0x");
    backend_text_append(out, &buffer[1], digits);
}

fn backend_decimal(out: vector(u8)*, value: u64): void {
    var buffer: u8[20];
    var i: usize = 20;
    loop {
        i = i - 1;
        var remainder = value % 10;
        var digit = convert(u8, remainder);
        buffer[i] = digit + 48;
        value = value / 10;
        var done = value == 0;
        if done {
            break;
        }
    }
    var length = 20 - i;
    backend_text_append(out, &buffer[i], length);
}

fn backend_instructions(d: BackendDecoder*, data: u8*, length: usize, base: u64): void {
    var offset: usize = 0;
    loop {
        var done = offset == length;
        var full = d.text.length >= 2097152;
        if full {
            done = true;
        }
        if done {
            return;
        }
        var line: u8[1024];
        var address = base + convert(u64, offset);
        if d.instruction_labels {
            var label = backend_label_name(d, address);
            var named = label != null;
            if named {
                backend_text(&d.text, label);
                backend_text(&d.text, ":\n");
            }
        }
        var remaining = length - offset;
        var count = LLVMDisasmInstruction(d.llvm, &data[offset], convert(u64, remaining), address, &line[0], 1024);
        backend_hex(&d.text, address, 8);
        backend_text(&d.text, "  ");
        var decoded = count != 0;
        if decoded {
            backend_text(&d.text, &line[0]);
        }
        else {
            backend_text(&d.text, ".byte ");
            backend_hex(&d.text, convert(u64, data[offset]), 2);
            count = 1;
        }
        backend_text(&d.text, "\n");
        offset = offset + count;
    }
}

fn backend_wasm_byte(d: BackendDecoder*): u8 {
    var done = d.offset >= d.end;
    if done {
        d.failed = true;
        return 0;
    }
    var value = d.data[d.offset];
    d.offset = d.offset + 1;
    return value;
}

fn backend_wasm_u32(d: BackendDecoder*): usize {
    var value: u64 = 0;
    var factor: u64 = 1;
    var i: usize = 0;
    loop {
        var byte = backend_wasm_byte(d);
        var low = byte & 127;
        var part = convert(u64, low) * factor;
        value = value + part;
        var overflow = value > 4294967295;
        if overflow {
            d.failed = true;
            return 0;
        }
        var last = byte < 128;
        if last {
            return convert(usize, value);
        }
        i = i + 1;
        var too_long = i == 5;
        if too_long {
            d.failed = true;
            return 0;
        }
        factor = factor * 128;
    }
}

fn backend_wasm_skip(d: BackendDecoder*, count: usize): void {
    var remaining = d.end - d.offset;
    var invalid = count > remaining;
    if invalid {
        d.failed = true;
        d.offset = d.end;
        return;
    }
    d.offset = d.offset + count;
}

fn backend_wasm_string(d: BackendDecoder*): void {
    var count = backend_wasm_u32(d);
    backend_wasm_skip(d, count);
}

fn backend_wasm_label(d: BackendDecoder*, index: usize, priority: u32): void {
    var count = backend_wasm_u32(d);
    var begin = d.offset;
    backend_wasm_skip(d, count);
    var valid = d.failed == false;
    if valid {
        backend_label_add(d, convert(u64, index), &d.data[begin], count, priority);
    }
}

fn backend_wasm_labels(d: BackendDecoder*): void {
    d.offset = 8;
    loop {
        var done = d.offset >= d.length;
