// Returns owned text/error views; release with foreign_name_close. The profile
// describes the foreign compiler, never the host running this Tower function.
fn foreign_profile(m: ForeignName*, profile: u32): void {
    var foreign_condition3001 = profile == foreign_windows_arm64ec();
    if foreign_condition3001 {
        foreign_profile(m, foreign_windows_arm64());
        m.profile = foreign_windows_arm64ec();
        return;
    }
    m.profile = profile;
    m.abi = 1;
    m.pointer_bytes = 8;
    m.long_bytes = 8;
    m.arch = 2;
    var foreign_condition1 = profile == foreign_wasi();
    if foreign_condition1 {
        m.pointer_bytes = 4;
        m.long_bytes = 4;
        m.arch = 0;
    }
    var foreign_condition2 = profile == foreign_macos_x64();
    if foreign_condition2 {
        m.object_format = 1;
    }
    var foreign_condition3 = profile == foreign_macos_arm64();
    if foreign_condition3 {
        m.object_format = 1;
        m.arch = 3;
    }
    var foreign_condition4 = profile == foreign_windows_x64();
    if foreign_condition4 {
        m.object_format = 2;
        m.long_bytes = 4;
        m.abi = 2;
    }
    var foreign_condition5 = profile == foreign_windows_x86();
    if foreign_condition5 {
        m.object_format = 2;
        m.long_bytes = 4;
        m.pointer_bytes = 4;
        m.arch = 1;
        m.abi = 2;
    }
    var foreign_condition6 = profile == foreign_mingw_x64();
    if foreign_condition6 {
        m.object_format = 2;
        m.long_bytes = 4;
    }
    var foreign_condition7 = profile == foreign_linux_arm64();
    if foreign_condition7 {
        m.arch = 3;
    }
    var foreign_condition8 = profile == foreign_linux_x86();
    if foreign_condition8 {
        m.pointer_bytes = 4;
        m.long_bytes = 4;
        m.arch = 1;
    }
    var foreign_condition9 = profile == foreign_windows_arm64();
    if foreign_condition9 {
        m.object_format = 2;
        m.long_bytes = 4;
        m.arch = 3;
        m.abi = 2;
    }
    var foreign_condition10 = profile == 0;
    if foreign_condition10 {
        foreign_fail(m, "Unknown foreign ABI profile");
    }
    var foreign_condition11 = profile > foreign_windows_arm64ec();
    if foreign_condition11 {
        foreign_fail(m, "Unknown foreign ABI profile");
    }
}

fn foreign_argument_bytes(m: ForeignName*, type: ForeignType*): usize {
    var foreign_condition12 = type.kind == 3;
