extern fn LLVMOffsetOfElement(layout: void*, type: void*, index: u32): u64;

extern fn LLVMPassBuilderOptionsSetLoopVectorization(options: void*, enabled: i32): void;

extern fn LLVMPassBuilderOptionsSetSLPVectorization(options: void*, enabled: i32): void;

import tower;

// Disposable LLVM->entity associations only. There is no second Tower IR.
struct BackendImport {
    backend: Backend*;
    root: void*;
    function: void*;
    block: void*;
    declarations: void*;
    values: vector(BackendAssociation);
    literals: vector(BackendAssociation);
    blocks: vector(BackendAssociation);
    serial: u64;
}

fn bi_node(c: BackendImport*, kind: u32, scalar: u32): void* {
    var entity = sem_create(c.root);
    var n = sem_attach(entity, kind);
    n.type.scalar = scalar;
    n.type.pointer_bytes = c.backend.pointer_bytes;
    var pointer = scalar == 10;
    if pointer {
        n.type.scalar = 5;
        n.type.pointers = 1;
    }
    return entity;
}

fn bi_scalar(c: BackendImport*, type: void*): u32 {
    var kind = LLVMGetTypeKind(type);
    var empty = kind == 0;
    if empty {
        return 3;
    }
    var pointer = kind == 12;
    if pointer {
        return 10;
    }
    var integer = kind == 8;
    if integer {
        var width = LLVMGetIntTypeWidth(type);
        var boolean = width == 1;
        if boolean {
            return 2;
        }
        var byte = width == 8;
        if byte {
            return 5;
        }
        var small = width <= 32;
        if small {
            return 1;
        }
        var supported = width <= 64;
        if supported {
            return 7;
        }
    }
    backend_fail(c.backend, "LLVM return path requires a supported scalar type");
    return 7;
}

fn bi_name(c: BackendImport*, entity: void*, prefix: u8*): void {
    var n = sem_get(entity);
    loop {
        n.name.length = 0;
        backend_text(&n.name, prefix);
        backend_decimal(&n.name, c.serial);
        c.serial = c.serial + 1;
        var collision = false;
        var i: usize = 0;
        loop {
            var done = i == c.backend.source_functions.length;
            if done {
                break;
            }
            var original = sem_get(c.backend.source_functions.data[i]);
            if backend_equal(backend_name(original), n.name.data) {
                collision = true;
            }
            i = i + 1;
        }
        var unique = collision == false;
        if unique {
            return;
        }
    }
}

fn bi_append(c: BackendImport*, block: void*, entity: void*): void {
    var n = sem_get(block);
    backend_require(c.backend, vector_push(void*, &n.items, entity));
}

fn bi_const(c: BackendImport*, scalar: u32, value: u64): void* {
    var entity = bi_node(c, 5, scalar);
    var n = sem_get(entity);
    n.constant = true;
    n.bits = value;
    return entity;
}

// An LLVM constant needs a typed Foundation binding: a bare literal loses its
// source width in bits/convert and in comparisons during text reconstruction.
// Initialize each distinct literal once in the function's declaration prefix,
// so every branch can reuse it without depending on which branch executes first.
fn bi_literal(c: BackendImport*, key: void*, scalar: u32, bits: u64): void* {
    var local = backend_find(&c.literals, key);
    var missing = local == null;
    if missing {
        local = bi_decl(c, scalar);
        var declaration = sem_get(local);
        declaration.value = bi_const(c, scalar, bits);
        backend_require(c.backend, backend_associate(&c.literals, key, local));
    }
    return bi_ref(c, local);
}

fn bi_ref(c: BackendImport*, binding: void*): void* {
    var b = sem_get(binding);
    var entity = bi_node(c, 5, b.type.scalar);
    var n = sem_get(entity);
    copy(&n.type, &b.type, sizeof(FoundationType));
    n.binding = binding;
    return entity;
}

fn bi_decl(c: BackendImport*, scalar: u32): void* {
    var entity = bi_node(c, 3, scalar);
    bi_name(c, entity, "v");
    bi_append(c, c.declarations, entity);
    return entity;
}

fn bi_assign(c: BackendImport*, target: void*, value: void*): void {
    var entity = bi_node(c, 4, 3);
    var n = sem_get(entity);
    n.target = target;
    n.value = value;
    bi_append(c, c.block, entity);
}

// Materialize every non-operand expression: foundation remains three-address.
fn bi_temp(c: BackendImport*, expression: void*): void* {
    var n = sem_get(expression);
    var local = bi_decl(c, n.type.scalar);
    var d = sem_get(local);
    copy(&d.type, &n.type, sizeof(FoundationType));
    bi_assign(c, bi_ref(c, local), expression);
    return bi_ref(c, local);
}

// Each LLVM instruction already has a destination local for forward references.
// Use it for the final temporary produced while importing this instruction,
// instead of emitting a second declaration, assignment and read of the result.
// Only the freshly created, final assignment qualifies; branch results, shared
// literals and existing bindings retain their ordinary copy.
fn bi_result(c: BackendImport*, destination: void*, value: void*, first_local: usize): void {
    var result = sem_get(value);
    var declarations = sem_get(c.declarations);
    var block = sem_get(c.block);
    var candidate = result.kind == KOperand();
    if result.constant {
        candidate = false;
    }
    var fresh = declarations.items.length > first_local;
    if fresh {} else {
        candidate = false;
    }
    var empty = block.items.length == 0;
    if empty {
        candidate = false;
    }
    if candidate {
        var last_local = declarations.items.length - 1;
        var local = declarations.items.data[last_local];
        var matches = result.binding == local;
        if matches {
            var last_statement = block.items.length - 1;
            var assignment = sem_get(block.items.data[last_statement]);
            matches = assignment.kind == KAssign();
            if matches {
                var target = sem_get(assignment.target);
                matches = target.kind == KOperand();
                if matches {
                    matches = target.binding == local;
                }
                var original = sem_get(destination);
                if matches {
                    matches = semantic_type_equal(&original.type, &result.type);
                }
                if matches {
                    assignment.target = bi_ref(c, destination);
                    declarations.items.length = last_local;
                    return;
                }
            }
        }
    }
    bi_assign(c, bi_ref(c, destination), value);
}

fn bi_cast(c: BackendImport*, value: void*, scalar: u32, reinterpret: bool): void* {
    var entity = bi_node(c, 9, scalar);
    var n = sem_get(entity);
    if reinterpret {
        n.kind = 10;
    }
    n.value = value;
    var v = sem_get(value);
    var boolean = n.type.scalar == 2;
    var source_boolean = v.type.scalar == 2;
    if source_boolean {
        boolean = true;
    }
    var numeric = n.type.pointers == 0;
    if numeric {
        numeric = v.type.pointers == 0;
    }
    if boolean {
        if numeric {
            reinterpret = false;
            n.kind = 9;
        }
    }
    var same = n.type.scalar == v.type.scalar;
    var pointers = n.type.pointers == v.type.pointers;
    if same {
        if pointers {
            return value;
        }
    }
    if reinterpret {} else {
        var width = semantic_width(&n.type);
        var source_width = semantic_width(&v.type);
        var narrowing = width < source_width;
        if narrowing {
            // LLVM trunc is modular. Foundation convert is checked, so mask
            // before the conversion instead of introducing a range trap.
            var unsigned_value = bi_cast(c, value, 7, false);
            var mask = bi_pow2(width) - 1;
            unsigned_value = bi_binary(c, 5, unsigned_value, bi_const(c, 7, mask), 7);
            n.value = unsigned_value;
        }
    }
    return bi_temp(c, entity);
}

fn bi_binary(c: BackendImport*, op: u32, left: void*, right: void*, scalar: u32): void* {
    var input = sem_get(left);
    var boolean = input.type.scalar == 2;
    var arithmetic = op < 8;
    if boolean {
        if arithmetic {
            left = bi_cast(c, left, 5, false);
            right = bi_cast(c, right, 5, false);
            var result = bi_binary(c, op, left, right, 5);
            result = bi_binary(c, 5, result, bi_const(c, 5, 1), 5);
            return bi_cast(c, result, scalar, false);
        }
    }
    var entity = bi_node(c, 6, scalar);
    var n = sem_get(entity);
    n.op = op;
    n.left = left;
    n.right = right;
    return bi_temp(c, entity);
}

fn bi_cast_type(c: BackendImport*, value: void*, type: FoundationType*): void* {
    var entity = bi_node(c, 10, type.scalar);
    var n = sem_get(entity);
    copy(&n.type, type, sizeof(FoundationType));
    n.value = value;
    var input = sem_get(value);
    var boolean = type.scalar == 2;
    var source_boolean = input.type.scalar == 2;
    if source_boolean {
        boolean = true;
    }
    var numeric = type.pointers == 0;
    if numeric {
        numeric = input.type.pointers == 0;
    }
    if boolean {
        if numeric {
            n.kind = 9;
        }
    }
    return bi_temp(c, entity);
}

fn bi_address(c: BackendImport*, object: void*): void* {
    var entity = bi_node(c, 7, 10);
    var n = sem_get(entity);
    var v = sem_get(object);
    copy(&n.type, &v.type, sizeof(FoundationType));
    n.type.pointers = n.type.pointers + 1;
    n.value = object;
    // The address of this fixed storage is already a Foundation operand.
    return bi_cast(c, entity, 10, true);
}

fn bi_storage(c: BackendImport*, bytes: u64, alignment: u32, global: bool): void* {
    var scalar: u32 = 5;
    var unit: u64 = 1;
    var wide = alignment > 4;
    if wide {
        scalar = 7;
        unit = 8;
    }
    else {
        wide = alignment > 1;
        if wide {
            scalar = 1;
            unit = 4;
        }
    }
    var unsupported = alignment > 8;
    if unsupported {
        backend_fail(c.backend, "LLVM allocation alignment exceeds foundation layout");
    }
    var array = bi_node(c, 19, 9);
    var a = sem_get(array);
    a.element.scalar = scalar;
    a.element.pointer_bytes = c.backend.pointer_bytes;
    bytes = bytes + unit;
    bytes = bytes - 1;
    var count = bytes / unit;
    var empty = count == 0;
    if empty {
        count = 1;
    }
    a.length = convert(usize, count);
    a.type.record = array;
    var entity = bi_node(c, 3, 9);
    var n = sem_get(entity);
    n.type.record = array;
    bi_name(c, entity, "storage");
    if global {
        bi_append(c, c.root, entity);
    }
    else {
        bi_append(c, c.declarations, entity);
    }
    return entity;
}

fn bi_typed_pointer(c: BackendImport*, value: void*, scalar: u32): void* {
    var entity = bi_node(c, 10, scalar);
    var n = sem_get(entity);
    n.type.pointers = n.type.pointers + 1;
    n.value = value;
    return bi_temp(c, entity);
}

fn bi_load(c: BackendImport*, address: void*, scalar: u32): void* {
    var pointer = bi_typed_pointer(c, address, scalar);
    var entity = bi_node(c, 8, scalar);
    var n = sem_get(entity);
    n.value = pointer;
    return bi_temp(c, entity);
}

fn bi_store(c: BackendImport*, address: void*, value: void*): void {
    var v = sem_get(value);
    var scalar = v.type.scalar;
    var pointer = v.type.pointers != 0;
    if pointer {
        scalar = 10;
    }
    var typed = bi_typed_pointer(c, address, scalar);
    var target = bi_node(c, 8, scalar);
    var n = sem_get(target);
    n.value = typed;
    bi_assign(c, target, value);
}

fn bi_offset(c: BackendImport*, pointer: void*, bytes: void*): void* {
    var integer = bi_cast(c, pointer, 8, true);
    bytes = bi_cast(c, bytes, 8, false);
    integer = bi_binary(c, 0, integer, bytes, 8);
    return bi_cast(c, integer, 10, true);
}

fn bi_if(c: BackendImport*, condition: void*): void* {
    var entity = bi_node(c, 13, 3);
    var n = sem_get(entity);
    n.value = condition;
    n.body = bi_node(c, 12, 3);
    n.otherwise = bi_node(c, 12, 3);
    bi_append(c, c.block, entity);
    return entity;
}

import tower;

fn bi_edge(c: BackendImport*, from: void*, to: void*): void {
    var copies: vector(BackendAssociation);
    vector_init(BackendAssociation, &copies);
    var instruction = LLVMGetFirstInstruction(to);
    loop {
        var done = instruction == null;
        if done {
            break;
        }
        done = LLVMGetInstructionOpcode(instruction) != 44;
        if done {
            break;
        }
        var count = LLVMCountIncoming(instruction);
        var i: u32 = 0;
        loop {
            done = i == count;
            if done {
                break;
            }
            var matches = LLVMGetIncomingBlock(instruction, i) == from;
            if matches {
                var value = bi_value(c, LLVMGetIncomingValue(instruction, i));
                var snapshot = bi_decl(c, bi_scalar(c, LLVMTypeOf(instruction)));
                bi_assign(c, bi_ref(c, snapshot), value);
                var destination = backend_find(&c.values, instruction);
                backend_require(c.backend, backend_associate(&copies, destination, snapshot));
                break;
            }
            i = i + 1;
        }
        instruction = LLVMGetNextInstruction(instruction);
    }
    var index: usize = 0;
    loop {
        var done = index == copies.length;
        if done {
            break;
        }
        var pair = &copies.data[index];
        bi_assign(c, bi_ref(c, pair.entity), bi_ref(c, pair.value));
        index = index + 1;
    }
    vector_dispose(BackendAssociation, &copies);
    var target = backend_find(&c.blocks, to);
    var label = sem_get(target);
    var entity = bi_node(c, 32, 3);
    var jump = sem_get(entity);
    backend_text(&jump.name, label.name.data);
    jump.binding = target;
    bi_append(c, c.block, entity);
}

fn bi_print(c: BackendImport*, value: void*, code: u32): void {
    var scalar = code;
    var pointer = code == 3;
    if pointer {
        value = bi_cast(c, value, 8, false);
        value = bi_cast(c, value, 10, true);
    } else {
        var signed = code == 0;
        if signed {
            value = bi_cast(c, value, 1, false);
            value = bi_cast(c, value, 0, true);
        } else {
            signed = code == 6;
            value = bi_cast(c, value, scalar, signed);
        }
    }
    var entity = bi_node(c, 17, 3);
    var n = sem_get(entity);
    n.value = value;
    bi_append(c, c.block, entity);
}

fn bi_call(c: BackendImport*, instruction: void*): void* {
    var callee = LLVMGetCalledValue(instruction);
    var length: usize = 0;
    var name = LLVMGetValueName2(callee, &length);
    var printing = backend_equal(name, "tower_print");
    if printing {
        var code = LLVMGetOperand(instruction, 0);
        var value = bi_value(c, LLVMGetOperand(instruction, 1));
        var constant = LLVMGetValueKind(code) == 18;
        if constant {
            bi_print(c, value, convert(u32, LLVMConstIntGetZExtValue(code)));
        }
        else {
            code = bi_value(c, code);
            var i: u32 = 0;
            loop {
                var done = i == 9;
                if done {
                    break;
                }
                var valid = i != 4;
                if valid {
                    var test = bi_binary(c, 8, code, bi_const(c, 1, convert(u64, i)), 2);
                    var outer = c.block;
                    var branch = sem_get(bi_if(c, test));
                    c.block = branch.body;
                    bi_print(c, value, i);
                    c.block = outer;
                }
                i = i + 1;
            }
        }
        return null;
    }
    var trapping = backend_equal(name, "tower_trap");
    if trapping {
        var entity = bi_node(c, 33, 3);
        var n = sem_get(entity);
        n.left = bi_value(c, LLVMGetOperand(instruction, 0));
        n.right = bi_cast(c, bi_value(c, LLVMGetOperand(instruction, 1)), 1, false);
        bi_append(c, c.block, entity);
        return null;
    }
    var allocating = backend_equal(name, "tower_allocate");
    var reallocating = backend_equal(name, "tower_reallocate");
    var deallocating = backend_equal(name, "tower_deallocate");
    var memory = allocating;
    if reallocating {
        memory = true;
    }
    if deallocating {
        memory = true;
    }
    if memory {
        var kind: u32 = 26;
        if reallocating {
            kind = 27;
        }
        if deallocating {
            kind = 28;
        }
        var entity = bi_node(c, kind, 10);
        var n = sem_get(entity);
        var offset: u32 = 0;
        n.element.scalar = 5;
        n.element.pointer_bytes = c.backend.pointer_bytes;
        if allocating {} else {
            n.left = bi_value(c, LLVMGetOperand(instruction, 0));
            offset = 1;
        }
        if deallocating {
            n.type.scalar = 3;
            n.type.pointers = 0;
            bi_append(c, c.block, entity);
            return null;
        }
        var count = bi_cast(c, bi_value(c, LLVMGetOperand(instruction, offset)), 8, false);
        offset = offset + 1;
        var size = bi_cast(c, bi_value(c, LLVMGetOperand(instruction, offset)), 8, false);
        // The generated runtime guards this product. Preserve failure as null
        // for overflow without allocating a wrapped, smaller object.
        var product = bi_binary(c, 2, count, size, 8);
        var safe_size = bi_select(c, bi_binary(c, 8, size, bi_const(c, 8, 0), 2), bi_const(c, 8, 1), size, 8);
        var restored = bi_binary(c, 3, product, safe_size, 8);
        var overflow = bi_binary(c, 9, restored, count, 2);
        var nonzero_size = bi_binary(c, 9, size, bi_const(c, 8, 0), 2);
        overflow = bi_binary(c, 5, overflow, nonzero_size, 2);
        var result = bi_decl(c, 10);
        var outer = c.block;
        var branch = sem_get(bi_if(c, overflow));
        c.block = branch.body;
        bi_assign(c, bi_ref(c, result), bi_const(c, 10, 0));
        c.block = branch.otherwise;
        n.right = product;
        bi_assign(c, bi_ref(c, result), entity);
        c.block = outer;
        return bi_ref(c, result);
    }
    var copy = backend_prefix(name, "llvm.memcpy.");
    var move = backend_prefix(name, "llvm.memmove.");
    if move {
        copy = true;
    }
    var fill_memory = backend_prefix(name, "llvm.memset.");
    memory = copy;
    if fill_memory {
        memory = true;
    }
    if memory {
        var kind: u32 = 29;
        if fill_memory {
            kind = 30;
        }
        var entity = bi_node(c, kind, 3);
        var n = sem_get(entity);
        n.left = bi_value(c, LLVMGetOperand(instruction, 0));
        n.right = bi_value(c, LLVMGetOperand(instruction, 1));
        n.value = bi_cast(c, bi_value(c, LLVMGetOperand(instruction, 2)), 8, false);
        var volatile_flag = LLVMGetOperand(instruction, 3);
        var volatile_memory = LLVMIsNull(volatile_flag) == 0;
        if volatile_memory {
            backend_fail(c.backend, "Volatile LLVM memory requires an explicit foundation contract");
        }
        bi_append(c, c.block, entity);
        return null;
    }
    var ignored = backend_prefix(name, "llvm.lifetime.");
    var assume = backend_equal(name, "llvm.assume");
    if assume {
        ignored = true;
    }
    if ignored {
        return null;
    }
    // InstCombine recognizes these ordinary scalar idioms even without target
    // vectorization. Legalize their bit semantics; do not re-optimize the graph.
    var absolute = backend_prefix(name, "llvm.abs.");
    if absolute {
        var type = LLVMTypeOf(instruction);
        var scalar = bi_scalar(c, type);
        var a = bi_value(c, LLVMGetOperand(instruction, 0));
        var sign_width = LLVMGetIntTypeWidth(type) - 1;
        var negative = bi_binary(c, 13, a, bi_const(c, scalar, bi_pow2(sign_width)), 2);
        var negated = bi_mask(c, bi_binary(c, 1, bi_const(c, scalar, 0), a, scalar), type);
        return bi_select(c, negative, negated, a, scalar);
    }
    var unsigned_add = backend_prefix(name, "llvm.uadd.sat.");
    var unsigned_subtract = backend_prefix(name, "llvm.usub.sat.");
    var signed_add = backend_prefix(name, "llvm.sadd.sat.");
    var signed_subtract = backend_prefix(name, "llvm.ssub.sat.");
    var saturating = unsigned_add;
    if unsigned_subtract {
        saturating = true;
    }
    if signed_add {
        saturating = true;
    }
    if signed_subtract {
        saturating = true;
    }
    if saturating {
        var type = LLVMTypeOf(instruction);
        var scalar = bi_scalar(c, type);
        var a = bi_value(c, LLVMGetOperand(instruction, 0));
        var b = bi_value(c, LLVMGetOperand(instruction, 1));
        var subtract = unsigned_subtract;
        if signed_subtract {
            subtract = true;
        }
        var operation: u32 = 0;
        if subtract {
            operation = 1;
        }
        var result = bi_mask(c, bi_binary(c, operation, a, b, scalar), type);
        var width = LLVMGetIntTypeWidth(type);
        if unsigned_add {
            var overflow = bi_binary(c, 10, result, a, 2);
            var maximum = bi_pow2(width) - 1;
            return bi_select(c, overflow, bi_const(c, scalar, maximum), result, scalar);
        }
        if unsigned_subtract {
            var overflow = bi_binary(c, 10, a, b, 2);
            return bi_select(c, overflow, bi_const(c, scalar, 0), result, scalar);
        }
        var changed = bi_binary(c, 7, a, result, scalar);
        var other = bi_binary(c, 7, b, result, scalar);
        if subtract {
            other = bi_binary(c, 7, a, b, scalar);
        }
        changed = bi_binary(c, 5, changed, other, scalar);
        var sign_width = width - 1;
        var sign = bi_pow2(sign_width);
        var overflow = bi_binary(c, 13, changed, bi_const(c, scalar, sign), 2);
        var negative = bi_binary(c, 13, a, bi_const(c, scalar, sign), 2);
        var maximum = sign - 1;
        var limit = bi_select(c, negative, bi_const(c, scalar, sign), bi_const(c, scalar, maximum), scalar);
        return bi_select(c, overflow, limit, result, scalar);
    }
    var minimum = backend_prefix(name, "llvm.umin.");
    var maximum = backend_prefix(name, "llvm.umax.");
    var signed_minimum = backend_prefix(name, "llvm.smin.");
    var signed_maximum = backend_prefix(name, "llvm.smax.");
    var minmax = minimum;
    if maximum {
        minmax = true;
    }
    if signed_minimum {
        minmax = true;
    }
    if signed_maximum {
        minmax = true;
    }
    if minmax {
        var a = bi_value(c, LLVMGetOperand(instruction, 0));
        var b = bi_value(c, LLVMGetOperand(instruction, 1));
        var predicate: u32 = 36;
        if maximum {
            predicate = 34;
        }
        if signed_minimum {
            predicate = 40;
        }
        if signed_maximum {
            predicate = 38;
        }
        var type = LLVMTypeOf(instruction);
        var condition = bi_compare(c, predicate, a, b, type);
        return bi_select(c, condition, a, b, bi_scalar(c, type));
    }
    var binding = backend_find(&c.values, callee);
    var absent = binding == null;
    if absent {
        backend_fail(c.backend, "Unsupported LLVM intrinsic or indirect call: ");
        backend_text(&c.backend.error, name);
        return null;
    }
    var entity = bi_node(c, 11, bi_scalar(c, LLVMTypeOf(instruction)));
    var n = sem_get(entity);
    n.binding = binding;
    var function = sem_get(binding);
    copy(&n.type, &function.type, sizeof(FoundationType));
    var count = LLVMGetNumArgOperands(instruction);
    var i: u32 = 0;
    loop {
        var done = i == count;
        if done {
            break;
        }
        var value = bi_value(c, LLVMGetOperand(instruction, i));
        var parameter = sem_get(function.parameters.data[convert(usize, i)]);
        value = bi_cast_type(c, value, &parameter.type);
        backend_require(c.backend, vector_push(void*, &n.items, value));
        i = i + 1;
    }
    var empty = n.type.scalar == 3;
    if empty {
        bi_append(c, c.block, entity);
        return null;
    }
    return bi_cast(c, bi_temp(c, entity), bi_scalar(c, LLVMTypeOf(instruction)), true);
}

fn bi_instruction(c: BackendImport*, instruction: void*, block: void*): void* {
    var op = LLVMGetInstructionOpcode(instruction);
    var type = LLVMTypeOf(instruction);
    var scalar = bi_scalar(c, type);
    var selected = op == 1;
    if selected {
        var entity = bi_node(c, 18, 3);
        var n = sem_get(entity);
        var valued = LLVMGetNumOperands(instruction) != 0;
        if valued {
            n.value = bi_value(c, LLVMGetOperand(instruction, 0));
            var function = sem_get(c.function);
            n.value = bi_cast_type(c, n.value, &function.type);
        }
        bi_append(c, c.block, entity);
        return null;
    }
    selected = op == 2;
    if selected {
        var conditional = LLVMGetNumSuccessors(instruction) == 2;
        if conditional {
            var condition = bi_value(c, LLVMGetCondition(instruction));
            var outer = c.block;
            var branch = sem_get(bi_if(c, condition));
            c.block = branch.body;
            bi_edge(c, block, LLVMGetSuccessor(instruction, 0));
            c.block = branch.otherwise;
            bi_edge(c, block, LLVMGetSuccessor(instruction, 1));
            c.block = outer;
        } else {
            bi_edge(c, block, LLVMGetSuccessor(instruction, 0));
        }
        return null;
    }
    selected = op == 7;
    if selected {
        // A defined Tower execution reaches unreachable only after an explicit
        // trap. Retain a deterministic diagnostic for corrupted/undefined input.
        var entity = bi_node(c, 33, 3);
        var n = sem_get(entity);
        var message = bi_node(c, 23, 10);
        var text = sem_get(message);
        backend_text(&text.name, "Reached unreachable LLVM block");
        n.left = message;
        n.right = bi_const(c, 1, 0);
        bi_append(c, c.block, entity);
        return null;
    }
    selected = op == 44;
    if selected {
        return null;
    }
    selected = op == 45;
    if selected {
        return bi_call(c, instruction);
    }
    selected = op == 29;
    if selected {
        return bi_gep(c, instruction);
    }
    selected = op == 26;
    if selected {
        var count = LLVMGetOperand(instruction, 0);
        var constant = LLVMGetValueKind(count) == 18;
        if constant {} else {
            backend_fail(c.backend, "Dynamic LLVM alloca cannot be represented by a static foundation local");
            return bi_const(c, 10, 0);
        }
        var bytes = LLVMABISizeOfType(c.backend.layout, LLVMGetAllocatedType(instruction));
        bytes = bytes * LLVMConstIntGetZExtValue(count);
        var storage = bi_storage(c, bytes, LLVMGetAlignment(instruction), false);
        return bi_address(c, bi_ref(c, storage));
    }
    selected = op == 28;
    var load = op == 27;
    if load {
        selected = true;
    }
    if selected {
        var invalid = LLVMGetVolatile(instruction) != 0;
        var atomic = LLVMGetOrdering(instruction) != 0;
        if atomic {
            invalid = true;
        }
        if invalid {
            backend_fail(c.backend, "Atomic/volatile LLVM memory requires an explicit foundation contract");
        }
        if load {
            return bi_memory_load(c, bi_value(c, LLVMGetOperand(instruction, 0)), type);
        }
        var stored = LLVMGetOperand(instruction, 0);
        bi_memory_store(c, bi_value(c, LLVMGetOperand(instruction, 1)), bi_value(c, stored), LLVMTypeOf(stored));
        return null;
    }
    // Diagnose before querying operands: some unsupported instructions have no
    // operands, and LLVM's C API requires valid indices even in release builds.
    var supported_shape = op >= 8;
    if supported_shape {
        supported_shape = op <= 25;
    }
    var cast_shape = op >= 30;
    if cast_shape {
        cast_shape = op <= 32;
    }
    if cast_shape {
        supported_shape = true;
    }
    cast_shape = op >= 39;
    if cast_shape {
        cast_shape = op <= 42;
    }
    if cast_shape {
        supported_shape = true;
    }
    selected = op == 46;
    if selected {
        supported_shape = true;
    }
    selected = op == 68;
    if selected {
        supported_shape = true;
    }
    if supported_shape {} else {
        backend_fail(c.backend, "Unsupported LLVM instruction in foundation return path: ");
        backend_decimal(&c.backend.error, convert(u64, op));
        return null;
    }
    var a_value = LLVMGetOperand(instruction, 0);
    var a = bi_value(c, a_value);
    selected = op == 68;
    if selected {
        return a;
    }
    selected = op == 30;
    var cast = op == 31;
    if cast {
        selected = true;
    }
    if selected {
        return bi_mask(c, a, type);
    }
    selected = op == 32;
    if selected {
        a = bi_signed(c, a, LLVMTypeOf(a_value));
        a = bi_cast(c, a, 7, true);
        return bi_mask(c, a, type);
    }
    selected = op == 39;
    if selected {
        a = bi_cast(c, a, 8, true);
        return bi_mask(c, a, type);
    }
    selected = op == 40;
    if selected {
        a = bi_cast(c, a, 8, false);
        return bi_cast(c, a, 10, true);
    }
    selected = op == 41;
    if selected {
        return bi_cast(c, a, scalar, true);
    }
    var b = bi_value(c, LLVMGetOperand(instruction, 1));
    selected = op == 42;
    if selected {
        return bi_compare(c, LLVMGetICmpPredicate(instruction), a, b, LLVMTypeOf(a_value));
    }
    selected = op == 46;
    if selected {
        var no = bi_value(c, LLVMGetOperand(instruction, 2));
        return bi_select(c, a, b, no, scalar);
    }
    selected = op >= 20;
    if selected {
        selected = op <= 22;
    }
    if selected {
        return bi_shift(c, op, a, b, type, LLVMGetOperand(instruction, 1));
    }
    var binary: u32 = 99;
    selected = op == 8;
    if selected {
        binary = 0;
    }
    selected = op == 10;
    if selected {
        binary = 1;
    }
    selected = op == 12;
    if selected {
        binary = 2;
    }
    selected = op == 14;
    if selected {
        binary = 3;
    }
    selected = op == 15;
    if selected {
        binary = 3;
    }
    selected = op == 17;
    if selected {
        binary = 4;
    }
    selected = op == 18;
    if selected {
        binary = 4;
    }
    selected = op == 23;
    if selected {
        binary = 5;
    }
    selected = op == 24;
    if selected {
        binary = 6;
    }
    selected = op == 25;
    if selected {
        binary = 7;
    }
    var supported = binary != 99;
    if supported {
        var signed = op == 15;
        selected = op == 18;
        if selected {
            signed = true;
        }
        if signed {
            a = bi_signed(c, a, type);
            b = bi_signed(c, b, type);
            a = bi_binary(c, binary, a, b, 6);
            a = bi_cast(c, a, 7, true);
        } else {
            a = bi_binary(c, binary, a, b, scalar);
        }
        return bi_mask(c, a, type);
    }
    backend_fail(c.backend, "Unsupported LLVM instruction in foundation return path: ");
    backend_decimal(&c.backend.error, convert(u64, op));
    return bi_const(c, scalar, 0);
}

import tower;

fn bi_initializer(c: BackendImport*, address: void*, initializer: void*, type: void*): void {
    var kind = LLVMGetTypeKind(type);
    var aggregate = kind == 10;
    var array = kind == 11;
    if array {
        aggregate = true;
    }
    if aggregate {
        var count: u64 = 0;
        if array {
            count = LLVMGetArrayLength2(type);
        }
        else {
            count = convert(u64, LLVMCountStructElementTypes(type));
        }
        var i: u64 = 0;
        loop {
            var done = i == count;
            if done {
                break;
            }
            var element: void* = null;
            var offset: u64 = 0;
            if array {
                element = LLVMGetElementType(type);
                offset = LLVMABISizeOfType(c.backend.layout, element) * i;
            } else {
                element = LLVMStructGetTypeAtIndex(type, convert(u32, i));
                offset = LLVMOffsetOfElement(c.backend.layout, type, convert(u32, i));
            }
            var child = LLVMGetAggregateElement(initializer, convert(u32, i));
            var pointer = bi_offset(c, address, bi_const(c, 8, offset));
            bi_initializer(c, pointer, child, element);
            i = i + 1;
        }
        return;
    }
    bi_memory_store(c, address, bi_value(c, initializer), type);
}

fn bi_function(c: BackendImport*, function: void*): void {
    c.function = backend_find(&c.values, function);
    var n = sem_get(c.function);
    c.block = n.body;
    c.declarations = bi_node(c, 12, 3);
    c.blocks.length = 0;
    c.literals.length = 0;
    var block = LLVMGetFirstBasicBlock(function);
    loop {
        var done = block == null;
        if done {
            break;
        }
        var label = bi_node(c, 31, 3);
        bi_name(c, label, "block");
        backend_require(c.backend, backend_associate(&c.blocks, block, label));
        var instruction = LLVMGetFirstInstruction(block);
        loop {
            done = instruction == null;
            if done {
                break;
            }
            var type = LLVMTypeOf(instruction);
            var valued = LLVMGetTypeKind(type) != 0;
            if valued {
                var local = bi_decl(c, bi_scalar(c, type));
                backend_require(c.backend, backend_associate(&c.values, instruction, local));
            }
            instruction = LLVMGetNextInstruction(instruction);
        }
        block = LLVMGetNextBasicBlock(block);
    }
    block = LLVMGetFirstBasicBlock(function);
    loop {
        var done = block == null;
        if done {
            break;
        }
        bi_append(c, c.block, backend_find(&c.blocks, block));
        var instruction = LLVMGetFirstInstruction(block);
        loop {
            done = instruction == null;
            if done {
                break;
            }
            var failed = c.backend.error.length != 0;
            if failed {
                return;
            }
            var locals = sem_get(c.declarations);
            var first_local = locals.items.length;
            var result = bi_instruction(c, instruction, block);
            var valued = result != null;
            if valued {
                var destination = backend_find(&c.values, instruction);
                bi_result(c, destination, result, first_local);
            }
            instruction = LLVMGetNextInstruction(instruction);
        }
        block = LLVMGetNextBasicBlock(block);
    }
    var declarations = sem_get(c.declarations);
    var body = sem_get(n.body);
    var i: usize = 0;
    loop {
        var done = i == body.items.length;
        if done {
            break;
        }
        backend_require(c.backend, vector_push(void*, &declarations.items, body.items.data[i]));
        i = i + 1;
    }
    n.body = c.declarations;
}

export fn backend_import_foundation(b: Backend*, root: void*): bool {
    var c: BackendImport;
    fill(&c, 0, sizeof(BackendImport));
    c.backend = b;
    c.root = root;
    c.block = root;
    c.declarations = root;
    var program = sem_attach(root, 0);
    program.type.scalar = 3;
    program.type.pointer_bytes = b.pointer_bytes;
    var original_root = sem_get(b.source_root);
    var original_index: usize = 0;
    loop {
        var done = original_index == original_root.items.length;
        if done {
            break;
        }
        var entity = original_root.items.data[original_index];
        var n = sem_get(entity);
        var record = n.kind == 19;
        if record {
            bi_append(&c, root, entity);
        }
        original_index = original_index + 1;
    }
    var function = LLVMGetFirstFunction(b.module);
    loop {
        var done = function == null;
        if done {
            break;
        }
        var length: usize = 0;
        var name = LLVMGetValueName2(function, &length);
        var builtin = backend_prefix(name, "llvm.");
        var runtime = backend_reserved(name);
        var main = backend_equal(name, "tower_main");
        if main {
            runtime = false;
        }
        if runtime {
            builtin = true;
        }
        if builtin {} else {
            var type = LLVMGetReturnType(LLVMGlobalGetValueType(function));
            var entity = bi_node(&c, 1, bi_scalar(&c, type));
            var n = sem_get(entity);
            n.external = LLVMIsDeclaration(function) != 0;
            bi_name(&c, entity, "function");
            var signature: FoundationNode* = null;
            var i: usize = 0;
            loop {
                done = i == b.symbols.length;
                if done {
                    break;
                }
                var matches = backend_equal(name, b.symbols.data[i]);
                if matches {
                    var original = sem_get(b.source_functions.data[i]);
                    var public = original.external;
                    if original.exported {
                        public = true;
                    }
                    if public {
                        signature = original;
                        copy(&n.type, &original.type, sizeof(FoundationType));
                    }
                    var named = original.name.length != 0;
                    if named {
                        n.name.length = 0;
                        backend_text(&n.name, backend_name(original));
                        n.exported = original.exported;
                    }
                    break;
                }
                i = i + 1;
            }
            n.body = bi_node(&c, 12, 3);
            var count = LLVMCountParams(function);
            var parameter: u32 = 0;
            loop {
                done = parameter == count;
                if done {
                    break;
                }
                var value = LLVMGetParam(function, parameter);
                var p = bi_node(&c, 2, bi_scalar(&c, LLVMTypeOf(value)));
                var public = signature != null;
                if public {
                    var original_parameter = sem_get(signature.parameters.data[convert(usize, parameter)]);
                    var parameter_node = sem_get(p);
                    copy(&parameter_node.type, &original_parameter.type, sizeof(FoundationType));
                }
                bi_name(&c, p, "argument");
                backend_require(b, vector_push(void*, &n.parameters, p));
                backend_require(b, backend_associate(&c.values, value, p));
                parameter = parameter + 1;
            }
            bi_append(&c, root, entity);
            backend_require(b, backend_associate(&c.values, function, entity));
        }
        function = LLVMGetNextFunction(function);
    }
    var global = LLVMGetFirstGlobal(b.module);
    loop {
        var done = global == null;
        if done {
            break;
        }
        var type = LLVMGlobalGetValueType(global);
        var storage = bi_storage(&c, LLVMABISizeOfType(b.layout, type), LLVMABIAlignmentOfType(b.layout, type), true);
        var node = sem_get(storage);
        node.global = true;
        backend_require(b, backend_associate(&c.values, global, storage));
        global = LLVMGetNextGlobal(global);
    }
    // Initialization temporaries belong to a short-lived function frame. Keeping
    // each generated byte-store temporary at module scope inflates global memory
    // and can exceed the frontend's top-level declaration budget in debug mode.
    var startup = bi_node(&c, 1, 3);
    bi_name(&c, startup, "initialize");
    var startup_node = sem_get(startup);
    startup_node.body = bi_node(&c, 12, 3);
    bi_append(&c, root, startup);
    c.block = startup_node.body;
    c.declarations = c.block;
    global = LLVMGetFirstGlobal(b.module);
    loop {
        var done = global == null;
        if done {
            break;
        }
        var initializer = LLVMGetInitializer(global);
        var missing = initializer == null;
        if missing {
            backend_fail(b, "Unresolved LLVM global in foundation return path");
        }
        else {
            bi_initializer(&c, bi_value(&c, global), initializer, LLVMGlobalGetValueType(global));
        }
        global = LLVMGetNextGlobal(global);
    }
    var entry = backend_find(&c.values, LLVMGetNamedFunction(b.module, "tower_main"));
    var call = bi_node(&c, 11, 3);
    var invocation = sem_get(call);
    invocation.binding = entry;
    bi_append(&c, c.block, call);
    bi_append(&c, c.block, bi_node(&c, 18, 3));
    var start_call = bi_node(&c, 11, 3);
    var start_invocation = sem_get(start_call);
    start_invocation.binding = startup;
    bi_append(&c, root, start_call);
    function = LLVMGetFirstFunction(b.module);
    loop {
        var done = function == null;
        if done {
            break;
        }
        var defined = LLVMIsDeclaration(function) == 0;
        if defined {
            bi_function(&c, function);
        }
        function = LLVMGetNextFunction(function);
    }
    vector_dispose(BackendAssociation, &c.values);
    vector_dispose(BackendAssociation, &c.literals);
    vector_dispose(BackendAssociation, &c.blocks);
    var valid = b.error.length == 0;
    return valid;
}

export fn backend_optimize_interpreter(b: Backend*, optimize: bool): bool {
    if optimize {
        var options = LLVMCreatePassBuilderOptions();
        LLVMPassBuilderOptionsSetVerifyEach(options, 1);
        LLVMPassBuilderOptionsSetLoopVectorization(options, 0);
        LLVMPassBuilderOptionsSetSLPVectorization(options, 0);
        // A scalar portable profile. These are upstream passes, not Tower
        // peepholes. lower-switch makes target-independent CFG import explicit.
        var error = LLVMRunPasses(b.module, "function(sroa,mem2reg),default<O2>,function(lower-switch)", null, options);
        LLVMDisposePassBuilderOptions(options);
        var failed = error != null;
        if failed {
            var message = LLVMGetErrorMessage(error);
            backend_fail(b, message);
            LLVMDisposeErrorMessage(message);
            return false;
        }
    }
    return backend_optimize(b, false);
}

import tower;

fn bi_pow2(width: u32): u64 {
    var result: u64 = 1;
    var i: u32 = 0;
    loop {
        var done = i == width;
        if done {
            return result;
        }
        result = result * 2;
        i = i + 1;
    }
}

fn bi_narrow_memory(type: void*): bool {
    var integer = LLVMGetTypeKind(type) == 8;
    if integer {
        var width = LLVMGetIntTypeWidth(type);
        var direct = width == 8;
        if direct {
            return false;
        }
        direct = width == 32;
        if direct {
            return false;
        }
        direct = width == 64;
        if direct {
            return false;
        }
        return true;
    }
    return false;
}

fn bi_memory_load(c: BackendImport*, address: void*, type: void*): void* {
    if bi_narrow_memory(type) {
        var width = LLVMGetIntTypeWidth(type);
        var count = width + 7;
        count = count / 8;
        var result = bi_const(c, 7, 0);
        var i: u32 = 0;
        loop {
            var done = i == count;
            if done {
                break;
            }
            var at = bi_offset(c, address, bi_const(c, 8, convert(u64, i)));
            var byte = bi_cast(c, bi_load(c, at, 5), 7, false);
            var shift = i * 8;
            byte = bi_binary(c, 2, byte, bi_const(c, 7, bi_pow2(shift)), 7);
            result = bi_binary(c, 6, result, byte, 7);
            i = i + 1;
        }
        return bi_mask(c, result, type);
    }
    return bi_load(c, address, bi_scalar(c, type));
}

fn bi_memory_store(c: BackendImport*, address: void*, value: void*, type: void*): void {
    if bi_narrow_memory(type) {
        var width = LLVMGetIntTypeWidth(type);
        var count = width + 7;
        count = count / 8;
        value = bi_cast(c, value, 7, false);
        var i: u32 = 0;
        loop {
            var done = i == count;
            if done {
                return;
            }
            var byte = bi_binary(c, 5, value, bi_const(c, 7, 255), 7);
            byte = bi_cast(c, byte, 5, false);
            var at = bi_offset(c, address, bi_const(c, 8, convert(u64, i)));
            bi_store(c, at, byte);
            value = bi_binary(c, 3, value, bi_const(c, 7, 256), 7);
            i = i + 1;
        }
    }
    bi_store(c, address, value);
}

fn bi_mask(c: BackendImport*, value: void*, type: void*): void* {
    var integer = LLVMGetTypeKind(type) == 8;
    if integer {
        var width = LLVMGetIntTypeWidth(type);
        var scalar = bi_scalar(c, type);
        var boolean = width == 1;
        if boolean {
            value = bi_cast(c, value, 7, false);
            value = bi_binary(c, 5, value, bi_const(c, 7, 1), 7);
        }
        value = bi_cast(c, value, scalar, false);
        var ordinary = width == 1;
        if ordinary {
            return value;
        }
        ordinary = width == 8;
        if ordinary {
            return value;
        }
        ordinary = width == 32;
        if ordinary {
            return value;
        }
        ordinary = width == 64;
        if ordinary {
            return value;
        }
        var mask = bi_pow2(width) - 1;
        return bi_binary(c, 5, value, bi_const(c, scalar, mask), scalar);
    }
    return value;
}

fn bi_signed(c: BackendImport*, value: void*, type: void*): void* {
    var width = LLVMGetIntTypeWidth(type);
    value = bi_cast(c, value, 7, false);
    var full = width == 64;
    if full {} else {
        var sign_width = width - 1;
        var sign = bi_const(c, 7, bi_pow2(sign_width));
        value = bi_binary(c, 7, value, sign, 7);
        value = bi_binary(c, 1, value, sign, 7);
    }
    return bi_cast(c, value, 6, true);
}

fn bi_gep(c: BackendImport*, instruction: void*): void* {
    var value = bi_value(c, LLVMGetOperand(instruction, 0));
    var type = LLVMGetGEPSourceElementType(instruction);
    var count = LLVMGetNumOperands(instruction);
    var i: i32 = 1;
    loop {
        var done = i == count;
        if done {
            return value;
        }
        var index = LLVMGetOperand(instruction, convert(u32, i));
        var bytes: void* = null;
        var first = i == 1;
        var record = LLVMGetTypeKind(type) == 10;
        if first {
            record = false;
        }
        if record {
            var field = convert(u32, LLVMConstIntGetZExtValue(index));
            bytes = bi_const(c, 8, LLVMOffsetOfElement(c.backend.layout, type, field));
            type = LLVMStructGetTypeAtIndex(type, field);
        } else {
            if first {} else {
                type = LLVMGetElementType(type);
            }
            var stride = LLVMABISizeOfType(c.backend.layout, type);
            var index_width = LLVMGetIntTypeWidth(LLVMTypeOf(index));
            var pointer_width = c.backend.pointer_bytes * 8;
            var wider_pointer = pointer_width > index_width;
            bytes = bi_value(c, index);
            if wider_pointer {
                bytes = bi_signed(c, bytes, LLVMTypeOf(index));
                bytes = bi_cast(c, bytes, 7, true);
            }
            bytes = bi_cast(c, bytes, 8, false);
            bytes = bi_binary(c, 2, bytes, bi_const(c, 8, stride), 8);
        }
        value = bi_offset(c, value, bytes);
        i = i + 1;
    }
}

fn bi_value(c: BackendImport*, value: void*): void* {
    var entity = backend_find(&c.values, value);
    var found = entity != null;
    if found {
        var n = sem_get(entity);
        if n.global {
            return bi_address(c, bi_ref(c, entity));
        }
        return bi_cast(c, bi_ref(c, entity), bi_scalar(c, LLVMTypeOf(value)), true);
    }
    var type = LLVMTypeOf(value);
    var scalar = bi_scalar(c, type);
    var zero = LLVMIsNull(value) != 0;
    var undef = LLVMIsUndef(value) != 0;
    if undef {
        zero = true;
    }
    var poison = LLVMIsPoison(value) != 0;
    if poison {
        zero = true;
    }
    if zero {
        return bi_literal(c, value, scalar, 0);
    }
    var kind = LLVMGetValueKind(value);
    var integer = kind == 18;
    if integer {
        return bi_literal(c, value, scalar, LLVMConstIntGetZExtValue(value));
    }
    var expression = kind == 10;
    if expression {
        var op = LLVMGetConstOpcode(value);
        var gep = op == 29;
        if gep {
            return bi_gep(c, value);
        }
        var cast = op == 39;
        var other = op == 40;
        if other {
            cast = true;
        }
        other = op == 41;
        if other {
            cast = true;
        }
        if cast {
            var operand = bi_value(c, LLVMGetOperand(value, 0));
            var pointer = scalar == 10;
            if pointer {
                var input = sem_get(operand);
                var integer = input.type.pointers == 0;
                if integer {
                    operand = bi_cast(c, operand, 8, false);
                }
                return bi_cast(c, operand, scalar, true);
            }
            operand = bi_cast(c, operand, 8, true);
            return bi_cast(c, operand, scalar, false);
        }
    }
    backend_fail(c.backend, "Unsupported LLVM value in foundation return path");
    return bi_const(c, scalar, 0);
}

fn bi_select(c: BackendImport*, condition: void*, yes: void*, no: void*, scalar: u32): void* {
    var result = bi_decl(c, scalar);
    var outer = c.block;
    var entity = bi_if(c, condition);
    var branch = sem_get(entity);
    c.block = branch.body;
    bi_assign(c, bi_ref(c, result), yes);
    c.block = branch.otherwise;
    bi_assign(c, bi_ref(c, result), no);
    c.block = outer;
    return bi_ref(c, result);
}

fn bi_compare(c: BackendImport*, predicate: u32, a: void*, b: void*, type: void*): void* {
    var op: u32 = 8;
    var signed = predicate >= 38;
    if signed {
        var native_width = LLVMGetIntTypeWidth(type) == 32;
        if native_width {
            a = bi_cast(c, a, 0, true);
            b = bi_cast(c, b, 0, true);
        } else {
            a = bi_signed(c, a, type);
            b = bi_signed(c, b, type);
        }
        predicate = predicate - 4;
    }
    var selected = predicate == 33;
    if selected {
        op = 9;
    }
    selected = predicate == 34;
    if selected {
        op = 12;
    }
    selected = predicate == 35;
    if selected {
        op = 13;
    }
    selected = predicate == 36;
    if selected {
        op = 10;
    }
    selected = predicate == 37;
    if selected {
        op = 11;
    }
    return bi_binary(c, op, a, b, 2);
}

fn bi_shift(c: BackendImport*, op: u32, a: void*, b: void*, type: void*, shift: void*): void* {
    // Totalized LLVM shifts: out-of-range poison may choose any value. Never
    // introduce a trap into speculative, subsequently unused LLVM operations.
    var width = LLVMGetIntTypeWidth(type);
    var immediate = LLVMGetValueKind(shift) == 18;
    if immediate {
        // Immediate shift legalization needs a constant scale, not a runtime
        // exponentiation loop. This translates an opcode; LLVM owns folding.
        var count = LLVMConstIntGetZExtValue(shift);
        var scalar = bi_scalar(c, type);
        var poison = count >= convert(u64, width);
        if poison {
            return bi_const(c, scalar, 0);
        }
        var factor = bi_const(c, scalar, bi_pow2(convert(u32, count)));
        var left = op == 20;
        if left {
            return bi_mask(c, bi_binary(c, 2, a, factor, scalar), type);
        }
        var logical = op == 21;
        if logical {
            return bi_binary(c, 3, a, factor, scalar);
        }
        var sign_width = width - 1;
        var negative = bi_binary(c, 13, a, bi_const(c, scalar, bi_pow2(sign_width)), 2);
        var mask_bits = bi_pow2(width) - 1;
        var mask = bi_const(c, scalar, mask_bits);
        var inverted = bi_binary(c, 7, a, mask, scalar);
        inverted = bi_binary(c, 3, inverted, factor, scalar);
        inverted = bi_binary(c, 7, inverted, mask, scalar);
        var positive = bi_binary(c, 3, a, factor, scalar);
        return bi_select(c, negative, inverted, positive, scalar);
    }
    a = bi_cast(c, a, 7, false);
    b = bi_cast(c, b, 7, false);
    b = bi_binary(c, 5, b, bi_const(c, 7, 63), 7);
    var power = bi_decl(c, 7);
    bi_assign(c, bi_ref(c, power), bi_const(c, 7, 1));
    var i: u32 = 0;
    loop {
        var done = i == 6;
        if done {
            break;
        }
        var bit = bi_pow2(i);
        var test = bi_binary(c, 5, b, bi_const(c, 7, bit), 7);
        test = bi_binary(c, 9, test, bi_const(c, 7, 0), 2);
        var outer = c.block;
        var branch = sem_get(bi_if(c, test));
        c.block = branch.body;
        var factor = bi_const(c, 7, bi_pow2(convert(u32, bit)));
        var product = bi_binary(c, 2, bi_ref(c, power), factor, 7);
        bi_assign(c, bi_ref(c, power), product);
        c.block = outer;
        i = i + 1;
    }
    var left = op == 20;
    if left {
        return bi_mask(c, bi_binary(c, 2, a, bi_ref(c, power), 7), type);
    }
    var arithmetic = op == 22;
    if arithmetic {
        var sign_width = width - 1;
        var sign = bi_pow2(sign_width);
        var negative = bi_binary(c, 13, a, bi_const(c, 7, sign), 2);
        var mask = bi_pow2(width) - 1;
        var inverted = bi_binary(c, 7, a, bi_const(c, 7, mask), 7);
        inverted = bi_binary(c, 3, inverted, bi_ref(c, power), 7);
        inverted = bi_binary(c, 7, inverted, bi_const(c, 7, mask), 7);
        var positive = bi_binary(c, 3, a, bi_ref(c, power), 7);
        return bi_mask(c, bi_select(c, negative, inverted, positive, 7), type);
    }
    return bi_mask(c, bi_binary(c, 3, a, bi_ref(c, power), 7), type);
}

