import 'coff-import';

// Link plans are transport-independent argument lists for upstream LLD.
// Native hosts execute the bundled upstream tool; WASI invokes its pinned ABI.
struct BackendLinkInput {
    name: vector(u8);
    bytes: vector(u8);
}

struct BackendLink {
    arguments: vector(u8*);
    inputs: vector(BackendLinkInput);
    error: vector(u8);
    output: vector(u8);
}

extern fn fopen(path: u8*, mode: u8*): void*;

extern fn fclose(file: void*): i32;

extern fn fread(bytes: u8*, size: usize, count: usize, file: void*): usize;

extern fn fwrite(bytes: u8*, size: usize, count: usize, file: void*): usize;

extern fn fileno(file: void*): i32;

extern fn remove(path: u8*): i32;

fn backend_link_argument(link: BackendLink*, prefix: u8*, value: u8*): void {
    var text: vector(u8);
    vector_init(u8, &text);
    backend_text(&text, prefix);
    backend_text(&text, value);
    var ok = vector_push(u8*, &link.arguments, text.data);
    var failed = ok == false;
    if failed {
        vector_dispose(u8, &text);
        backend_text(&link.error, "Unable to allocate linker arguments");
    }
}

export fn backend_link_reset_plan(link: BackendLink*): void {
    remove("tower-stack-probe.lib");
    remove("tower-platform.tbd");
    var i: usize = 0;
    loop {
        var done = i == link.arguments.length;
        if done {
            break;
        }
        free(link.arguments.data[i]);
        i = i + 1;
    }
    link.arguments.length = 0;
    link.error.length = 0;
    link.output.length = 0;
}

export fn backend_link_clear_inputs(link: BackendLink*): void {
    var i: usize = 0;
    loop {
        var done = i == link.inputs.length;
        if done {
            break;
        }
        var input = &link.inputs.data[i];
        remove(input.name.data);
        vector_dispose(u8, &input.name);
        vector_dispose(u8, &input.bytes);
        i = i + 1;
    }
    link.inputs.length = 0;
}

export fn backend_link_close(link: BackendLink*): void {
    var absent = link == null;
    if absent {
        return;
    }
    backend_link_reset_plan(link);
    backend_link_clear_inputs(link);
    vector_dispose(u8*, &link.arguments);
    vector_dispose(BackendLinkInput, &link.inputs);
    vector_dispose(u8, &link.error);
    vector_dispose(u8, &link.output);
    free(link);
}

fn backend_filename(name: u8*): bool {
    var length = backend_length(name);
    var invalid = length == 0;
    if invalid {
        return false;
    }
    invalid = length > 128;
    if invalid {
        return false;
    }
    var i: usize = 0;
    loop {
        var end = i == length;
        if end {
            return true;
        }
        var byte = name[i];
        var valid = byte >= 97;
        if valid {
            valid = byte <= 122;
        }
        var upper = byte >= 65;
        if upper {
            upper = byte <= 90;
        }
        if upper {
            valid = true;
        }
        var number = byte >= 48;
        if number {
            number = byte <= 57;
        }
        if number {
            valid = true;
        }
        var punctuation = byte == 46;
        if punctuation {
            valid = true;
        }
        punctuation = byte == 95;
        if punctuation {
            valid = true;
        }
        punctuation = byte == 45;
        if punctuation {
            valid = true;
        }
        invalid = valid == false;
        if invalid {
            return false;
        }
        i = i + 1;
    }
}

export fn backend_link_add_input(link: BackendLink*, name: u8*, data: u8*, length: usize): bool {
    var invalid = name == null;
    if invalid {
        return false;
    }
    invalid = data == null;
    if invalid {
        return false;
    }
    invalid = length > 67108864;
    if invalid {
        return false;
    }
    invalid = link.inputs.length >= 64;
    if invalid {
        return false;
    }
    invalid = backend_filename(name) == false;
    if invalid {
        return false;
    }
    invalid = backend_prefix(name, "tower-");
    if invalid {
        return false;
    }
    var i: usize = 0;
    var found: BackendLinkInput* = null;
    loop {
        var end = i == link.inputs.length;
        if end {
            break;
        }
        var same = backend_equal(link.inputs.data[i].name.data, name);
        if same {
            found = &link.inputs.data[i];
            break;
        }
        i = i + 1;
    }
    var absent = found == null;
    if absent {
        var needed = link.inputs.length + 1;
        var ok = vector_reserve(BackendLinkInput, &link.inputs, needed);
        invalid = ok == false;
        if invalid {
            return false;
        }
        found = &link.inputs.data[link.inputs.length];
        fill(found, 0, sizeof(BackendLinkInput));
        backend_text(&found.name, name);
        link.inputs.length = needed;
    }
    found.bytes.length = 0;
    backend_text_append(&found.bytes, data, length);
    var complete = found.bytes.length == length;
    return complete;
}

fn backend_write_file(link: BackendLink*, path: u8*, data: u8*, length: usize): bool {
    var file = fopen(path, "wb");
    var absent = file == null;
    if absent {
        backend_text(&link.error, "Cannot open linker input: ");
        backend_text(&link.error, path);
        return false;
    }
    var written = fwrite(data, 1, length, file);
    var status = fclose(file);
    var ok = written == length;
    if ok {
        ok = status == 0;
    }
    var failed = ok == false;
    if failed {
        backend_text(&link.error, "Cannot write linker input: ");
        backend_text(&link.error, path);
    }
    return ok;
}

fn backend_read_file(output: vector(u8)*, path: u8*): bool {
    var file = fopen(path, "rb");
    var absent = file == null;
    if absent {
        return false;
    }
    var status = backend_file_seek(file, 0, 2);
    var length = backend_file_position(file);
    var invalid = length < 0;
    var failed = status != 0;
    if failed {
        invalid = true;
    }
    if invalid {
        fclose(file);
        return false;
    }
    backend_file_seek(file, 0, 0);
    var count = convert(usize, length);
    var needed = count + 1;
    var ok = vector_reserve(u8, output, needed);
    if ok {
        var read = fread(output.data, 1, count, file);
        ok = read == count;
        if ok {
            output.length = count;
            output.data[count] = 0;
        }
    }
    fclose(file);
    return ok;
}

export fn backend_link_plan(link: BackendLink*, triple: u8*, functions: void**, count: usize, object: u8*, object_size: usize, runtime: u8*, runtime_size: usize): bool {
    backend_link_reset_plan(link);
    // A failed invocation cannot expose output left by a prior request.
    remove("tower-output.bin");
    var ok = backend_write_file(link, "tower-input.o", object, object_size);
    var failed = ok == false;
    if failed {
        return false;
    }
    var wasm = backend_prefix(triple, "wasm");
    var windows = backend_contains(triple, "windows");
    var mac = backend_contains(triple, "apple");
    if wasm {
        ok = backend_write_file(link, "tower-runtime.o", runtime, runtime_size);
        failed = ok == false;
        if failed {
            return false;
        }
        var allowed: vector(u8);
        vector_init(u8, &allowed);
        backend_text(&allowed, "tower_print\ntower_trap\n");
        var i: usize = 1;
        loop {
            var done = i >= count;
            if done {
                break;
            }
            var n = sem_get(functions[i]);
            if n.external {
                var spelling = foreign_symbol(foreign_profile_for_target(triple), backend_name(n));
                backend_text(&allowed, foreign_name_text(spelling));
                foreign_name_close(spelling);
                backend_text(&allowed, "\n");
            }
            i = i + 1;
        }
        ok = backend_write_file(link, "tower-allowed.txt", allowed.data, allowed.length);
        vector_dispose(u8, &allowed);
        failed = ok == false;
        if failed {
            return false;
        }
        backend_link_argument(link, "", "wasm-ld");
        backend_link_argument(link, "", "--no-entry");
        backend_link_argument(link, "", "--export=tower_main");
        backend_link_argument(link, "", "--export-memory");
        backend_link_argument(link, "", "--allow-undefined-file=tower-allowed.txt");
        backend_link_argument(link, "", "--threads=1");
        backend_link_argument(link, "", "--stack-first");
        backend_link_argument(link, "", "-z");
        backend_link_argument(link, "", "stack-size=4194304");
        backend_link_argument(link, "", "--initial-memory=8388608");
        backend_link_argument(link, "", "--max-memory=268435456");
        backend_link_argument(link, "", "tower-input.o");
        backend_link_argument(link, "", "tower-runtime.o");
    } else {
        if windows {
            backend_link_argument(link, "", "lld-link");
            backend_link_argument(link, "", "/entry:mainCRTStartup");
            backend_link_argument(link, "", "/subsystem:console");
            backend_link_argument(link, "", "/machine:x64");
            backend_link_argument(link, "", "/timestamp:0");
            backend_link_argument(link, "", "/threads:1");
            backend_link_argument(link, "", "/out:tower-output.bin");
        } else {
            if mac {
                backend_link_argument(link, "", "ld64.lld");
                backend_link_argument(link, "", "-arch");
                var x86 = backend_prefix(triple, "x86_64");
                if x86 {
                    backend_link_argument(link, "", "x86_64");
                }
                else {
                    backend_link_argument(link, "", "arm64");
                }
                backend_link_argument(link, "", "-platform_version");
                backend_link_argument(link, "", "macos");
                backend_link_argument(link, "", "11.0");
                backend_link_argument(link, "", "11.0");
                backend_link_argument(link, "", "-e");
                backend_link_argument(link, "", "_main");
            } else {
                backend_link_argument(link, "", "ld.lld");
                backend_link_argument(link, "", "--threads=1");
                backend_link_argument(link, "", "-static");
                backend_link_argument(link, "", "--build-id=none");
                backend_link_argument(link, "", "-e");
                backend_link_argument(link, "", "_start");
            }
        }
        backend_link_argument(link, "", "tower-input.o");
    }
    // Preserve deterministic lexical input order, matching the former map.
    var order: vector(usize);
    vector_init(usize, &order);
    var i: usize = 0;
    loop {
        var done = i == link.inputs.length;
        if done {
            break;
        }
        vector_push(usize, &order, i);
        var j = i;
        loop {
            done = j == 0;
            if done {
                break;
            }
            var previous = j - 1;
            var a = order.data[previous];
            var b = order.data[j];
            var left = link.inputs.data[a].name.data;
            var right = link.inputs.data[b].name.data;
            var k: usize = 0;
            loop {
                var different = left[k] != right[k];
                var end = left[k] == 0;
                if end {
                    different = true;
                }
                if different {
                    break;
                }
                k = k + 1;
            }
            var sorted = left[k] <= right[k];
            if sorted {
                break;
            }
            order.data[previous] = b;
            order.data[j] = a;
            j = previous;
        }
        i = i + 1;
    }
    i = 0;
    loop {
        var done = i == order.length;
        if done {
            break;
        }
        var input = &link.inputs.data[order.data[i]];
        ok = backend_write_file(link, input.name.data, input.bytes.data, input.bytes.length);
        backend_link_argument(link, "", input.name.data);
        i = i + 1;
    }
    vector_dispose(usize, &order);
    if windows {
        // LLVM's Windows x64 prologue calls the OS stack probe for large frames.
        // Keep guard-page probing and its special ABI; never replace it with a
        // normal Tower-call wrapper or disable probes to silence a link error.
        var archive: vector(u8);
        vector_init(u8, &archive);
        ok = coff_import_archive(&archive, CoffMachineAmd64(), "__chkstk", "kernelbase.dll");
        if ok {
            ok = backend_write_file(link, "tower-stack-probe.lib", archive.data, archive.length);
        } else {
            backend_text(&link.error, "Unable to allocate Windows stack-probe import metadata");
        }
        vector_dispose(u8, &archive);
        if ok {} else {
            return false;
        }
        backend_link_argument(link, "", "tower-stack-probe.lib");
    }
    if mac {
        // LLVM may lower zero-fill to Darwin's __bzero. Supplement the caller's
        // SDK description with that existing libSystem symbol; no replacement
        // implementation or additional runtime library is introduced.
        var symbols: u8* = "--- !tapi-tbd\ntbd-version: 4\ntargets: [ x86_64-macos, arm64-macos ]\ninstall-name: '/usr/lib/libSystem.B.dylib'\ncurrent-version: 1\ncompatibility-version: 1\nexports:\n  - targets: [ x86_64-macos ]\n    symbols: [ ___bzero, _bzero ]\n  - targets: [ arm64-macos ]\n    symbols: [ _bzero ]\n...\n";
        ok = backend_write_file(link, "tower-platform.tbd", symbols, backend_length(symbols));
        if ok {} else {
            return false;
        }
        backend_link_argument(link, "", "tower-platform.tbd");
    }
    i = 1;
    loop {
        var done = i >= count;
        if done {
            break;
        }
        var n = sem_get(functions[i]);
        if n.exported {
            var spelling = foreign_symbol(foreign_profile_for_target(triple), backend_name(n));
            if wasm {
                backend_link_argument(link, "--export=", foreign_name_text(spelling));
            }
            if windows {
                backend_link_argument(link, "/export:", foreign_name_text(spelling));
            }
            foreign_name_close(spelling);
        }
        i = i + 1;
    }
    if wasm {
        backend_link_argument(link, "", "--export=tower_allocate");
        backend_link_argument(link, "", "--export=tower_deallocate");
    }
    var nonwindows = windows == false;
    if nonwindows {
        backend_link_argument(link, "", "-o");
        backend_link_argument(link, "", "tower-output.bin");
    }
    ok = link.error.length == 0;
    return ok;
}

export fn backend_link_arguments(link: BackendLink*): u8** {
    return link.arguments.data;
}

export fn backend_link_argument_count(link: BackendLink*): usize {
    return link.arguments.length;
}

export fn backend_link_read_output(link: BackendLink*): bool {
    var ok = backend_read_file(&link.output, "tower-output.bin");
    var failed = ok == false;
    if failed {
        backend_text(&link.error, "Cannot read linked executable");
    }
    return ok;
}

export fn backend_link_create(): BackendLink* {
    var link = alloc(BackendLink, 1);
    var present = link != null;
    if present {
        fill(link, 0, sizeof(BackendLink));
    }
    return link;
}

import tower;

fn backend_type(b: Backend*, t: FoundationType*): void* {
    var pointer = t.pointers != 0;
    if pointer {
        return b.pointer_type;
    }
    var aggregate = semantic_aggregate(t);
    if aggregate {
        return LLVMArrayType2(b.i8, convert(u64, semantic_size(t)));
    }
    var empty = t.scalar == SVoid();
    if empty {
        return LLVMVoidTypeInContext(b.context);
    }
    return LLVMIntTypeInContext(b.context, semantic_width(t));
}

fn backend_size_value(b: Backend*, value: usize): void* {
    return LLVMConstInt(b.size_type, convert(u64, value), 0);
}

fn backend_constant(b: Backend*, t: FoundationType*, value: u64): void* {
    var pointer = t.pointers != 0;
    if pointer {
        return LLVMConstNull(b.pointer_type);
    }
    return LLVMConstInt(backend_type(b, t), value, 0);
}

fn backend_narrow(t: FoundationType*): bool {
    var scalar = t.pointers == 0;
    var byte = t.scalar == SU8();
    var boolean = t.scalar == SBool();
    if boolean {
        byte = true;
    }
    var result = scalar;
    if result {
        result = byte;
    }
    return result;
}

fn backend_zext_attribute(b: Backend*, value: void*, index: u32, call: bool): void {
    var kind = LLVMGetEnumAttributeKindForName("zeroext", 7);
    var attribute = LLVMCreateEnumAttribute(b.context, kind, 0);
    if call {
        LLVMAddCallSiteAttribute(value, index, attribute);
    }
    else {
        LLVMAddAttributeAtIndex(value, index, attribute);
    }
}

fn backend_abi(b: Backend*, value: void*, n: FoundationNode*, call: bool): void {
    var public = n.external;
    if n.exported {
        public = true;
    }
    if public {
        var narrow = backend_narrow(&n.type);
        if narrow {
            backend_zext_attribute(b, value, 0, call);
        }
        var i: usize = 0;
        loop {
            var done = i == n.parameters.length;
            if done {
                break;
            }
            var parameter = sem_get(n.parameters.data[i]);
            narrow = backend_narrow(&parameter.type);
            if narrow {
                var index = convert(u32, i) + 1;
                backend_zext_attribute(b, value, index, call);
            }
            i = i + 1;
        }
    }
}

fn backend_attribute(b: Backend*, function: void*, key: u8*, value: u8*): void {
    var key_length = convert(u32, backend_length(key));
    var value_length = convert(u32, backend_length(value));
    var attribute = LLVMCreateStringAttribute(b.context, key, key_length, value, value_length);
    LLVMAddAttributeAtIndex(function, 4294967295, attribute);
}

fn backend_runtime(b: Backend*, name: u8*, result: void*, types: void**, count: u32, import_name: u8*): void* {
    var type = LLVMFunctionType(result, types, count, 0);
    var function = LLVMAddFunction(b.module, name, type);
    var named = import_name != null;
    if named {
        named = b.wasm;
    }
    if named {
        backend_attribute(b, function, "wasm-import-module", "tower");
        backend_attribute(b, function, "wasm-import-name", import_name);
    }
    return function;
}

fn backend_runtime_declarations(b: Backend*): void {
    var types: void*[3];
    types[0] = b.i32;
    types[1] = b.i64;
    types[2] = b.i32;
    var empty = LLVMVoidTypeInContext(b.context);
    b.print_fn = backend_runtime(b, "tower_print", empty, &types[0], 3, "print");
    types[0] = b.pointer_type;
    types[1] = b.size_type;
    b.trap_fn = backend_runtime(b, "tower_trap", empty, &types[0], 2, "trap");
    types[0] = b.size_type;
    types[1] = b.size_type;
    b.allocate_fn = backend_runtime(b, "tower_allocate", b.pointer_type, &types[0], 2, null);
    types[0] = b.pointer_type;
    types[1] = b.size_type;
    types[2] = b.size_type;
    b.reallocate_fn = backend_runtime(b, "tower_reallocate", b.pointer_type, &types[0], 3, null);
    b.deallocate_fn = backend_runtime(b, "tower_deallocate", empty, &types[0], 1, null);
}

fn backend_call_values(b: Backend*, function: void*, args: void**, count: u32): void* {
    var call = LLVMBuildCall2(b.builder, LLVMGlobalGetValueType(function), function, args, count, "");
    LLVMSetInstructionCallConv(call, LLVMGetFunctionCallConv(function));
    return call;
}

fn backend_guard(b: Backend*, valid: void*, message: u8*): void {
    var ok = LLVMAppendBasicBlockInContext(b.context, b.current, "valid");
    var bad = LLVMAppendBasicBlockInContext(b.context, b.current, "error");
    LLVMBuildCondBr(b.builder, valid, ok, bad);
    LLVMPositionBuilderAtEnd(b.builder, bad);
    var args: void*[2];
    args[0] = LLVMBuildGlobalStringPtr(b.builder, message, "");
    args[1] = backend_size_value(b, b.source_offset);
    backend_call_values(b, b.trap_fn, &args[0], 2);
    LLVMBuildUnreachable(b.builder);
    LLVMPositionBuilderAtEnd(b.builder, ok);
}

fn backend_signed(t: FoundationType*): i32 {
    var signed = semantic_signed(t);
    if signed {
        return 1;
    }
    return 0;
}

fn backend_gep(b: Backend*, base: void*, offset: void*): void* {
    // Raw pointers deliberately have no inbounds promise.
    return LLVMBuildGEP2(b.builder, b.i8, base, &offset, 1, "");
}

fn backend_address(b: Backend*, entity: void*): void* {
    var n = sem_get(entity);
    var load = n.kind == KLoad();
    if load {
        return backend_read(b, n.value);
    }
    var field = n.kind == KField();
    var index = n.kind == KIndex();
    var place = field;
    if index {
        place = true;
    }
    if place {
        var base: void* = null;
        if n.indirect {
            base = backend_read(b, n.left);
        }
        else {
            base = backend_address(b, n.left);
        }
        var offset = backend_size_value(b, n.byte_offset);
        if index {
            var right = sem_get(n.right);
            var value = backend_read(b, n.right);
            value = LLVMBuildIntCast2(b.builder, value, b.size_type, backend_signed(&right.type), "");
            offset = LLVMBuildMul(b.builder, value, backend_size_value(b, semantic_size(&n.type)), "");
        }
        return backend_gep(b, base, offset);
    }
    var binding = n.binding;
    var absent = binding == null;
    if absent {
        binding = entity;
    }
    var definition = sem_get(binding);
    if definition.global {
        var global = backend_find(&b.globals, binding);
        absent = global == null;
        if absent {
            var name: vector(u8);
            vector_init(u8, &name);
            backend_text(&name, "tower.global.");
            backend_text(&name, backend_name(definition));
            var type = backend_type(b, &definition.type);
            global = LLVMAddGlobal(b.module, type, name.data);
            LLVMSetLinkage(global, 8);
            LLVMSetInitializer(global, LLVMGetUndef(type));
            LLVMSetAlignment(global, convert(u32, semantic_alignment(&definition.type)));
            backend_require(b, backend_associate(&b.globals, binding, global));
            vector_dispose(u8, &name);
        }
        return global;
    }
    return b.locals.data[definition.index];
}

fn backend_read(b: Backend*, entity: void*): void* {
    var n = sem_get(entity);
    var address = n.kind == KAddress();
    if address {
        return backend_address(b, n.value);
    }
    var string = n.kind == KString();
    if string {
        var value = backend_find(&b.strings, entity);
        var absent = value == null;
        if absent {
            var data = LLVMConstStringInContext(b.context, backend_name(n), convert(u32, n.name.length), 0);
            value = LLVMAddGlobal(b.module, LLVMTypeOf(data), "tower.string");
            LLVMSetLinkage(value, 9);
            LLVMSetInitializer(value, data);
            LLVMSetAlignment(value, 1);
            backend_require(b, backend_associate(&b.strings, entity, value));
        }
        return value;
    }
    var ordinary = n.kind == KOperand();
    var field = n.kind == KField();
    var index = n.kind == KIndex();
    if field {
        ordinary = true;
    }
    if index {
        ordinary = true;
    }
    if ordinary {
        if n.constant {
            return backend_constant(b, &n.type, n.bits);
        }
        var value = LLVMBuildLoad2(b.builder, backend_type(b, &n.type), backend_address(b, entity), "");
        LLVMSetAlignment(value, 1);
        return value;
    }
    return backend_expression(b, entity);
}

fn backend_call(b: Backend*, n: FoundationNode*): void* {
    var args: vector(void*);
    vector_init(void*, &args);
    var i: usize = 0;
    loop {
        var done = i == n.items.length;
        if done {
            break;
        }
        // Read each argument once, in source order.
        var value = backend_read(b, n.items.data[i]);
        backend_require(b, vector_push(void*, &args, value));
        i = i + 1;
    }
    var definition = sem_get(n.binding);
    var function = b.functions.data[definition.index];
    var result = backend_call_values(b, function, args.data, convert(u32, args.length));
    backend_abi(b, result, definition, true);
    var attributed = definition.external;
    if definition.exported {
        attributed = true;
    }
    if attributed {
        attributed = b.wasm;
    }
    if attributed {
        var count = LLVMGetAttributeCountAtIndex(function, 4294967295);
        var attributes = alloc(void*, convert(usize, count));
        LLVMGetAttributesAtIndex(function, 4294967295, attributes);
        var attribute: u32 = 0;
        loop {
            var done = attribute == count;
            if done {
                break;
            }
            LLVMAddCallSiteAttribute(result, 4294967295, attributes[attribute]);
            attribute = attribute + 1;
        }
        free(attributes);
    }
    vector_dispose(void*, &args);
    return result;
}

fn backend_conversion(b: Backend*, n: FoundationNode*, from: FoundationType*, value: void*): void* {
    var boolean = n.type.scalar == SBool();
    if boolean {
        var nonzero = LLVMBuildICmp(b.builder, 33, value, LLVMConstNull(LLVMTypeOf(value)), "");
        return LLVMBuildZExt(b.builder, nonzero, b.i8, "");
    }
    // The foundation integer domain is at most 64 bits. Compare in that
    // domain with explicit signedness; no synthetic i128 VM type is needed.
    var wide = LLVMBuildIntCast2(b.builder, value, b.i64, backend_signed(from), "");
    var width = semantic_width(&n.type);
    var signed = semantic_signed(&n.type);
    var magnitude: u64 = 1;
    var bits: u32 = 0;
    var limit = width;
    if signed {
        limit = limit - 1;
    }
    loop {
        var done = bits == limit;
        if done {
            break;
        }
        magnitude = magnitude * 2;
        bits = bits + 1;
    }
    var maximum_bits = magnitude - 1;
    var minimum_bits: u64 = 0;
    if signed {
        minimum_bits = minimum_bits - magnitude;
    }
    var truth = LLVMConstInt(LLVMIntTypeInContext(b.context, 1), 1, 0);
    var low = truth;
    var from_signed = semantic_signed(from);
    if from_signed {
        low = LLVMBuildICmp(b.builder, 39, wide, LLVMConstInt(b.i64, minimum_bits, 0), "");
    }
    var predicate: u32 = 37;
    if signed {
        if from_signed {
            predicate = 41;
        }
    }
    var high = LLVMBuildICmp(b.builder, predicate, wide, LLVMConstInt(b.i64, maximum_bits, 0), "");
    backend_guard(b, LLVMBuildAnd(b.builder, low, high, ""), "Numeric conversion out of range; use bits for bit reinterpretation");
    return LLVMBuildIntCast2(b.builder, value, backend_type(b, &n.type), backend_signed(from), "");
}

fn backend_expression(b: Backend*, entity: void*): void* {
    var n = sem_get(entity);
    var ordinary = n.kind == KOperand();
    var `match` = n.kind == KString();
    if `match` {
        ordinary = true;
    }
    `match` = n.kind == KField();
    if `match` {
        ordinary = true;
    }
    `match` = n.kind == KIndex();
    if `match` {
        ordinary = true;
    }
    `match` = n.kind == KAddress();
    if `match` {
        ordinary = true;
    }
    if ordinary {
        return backend_read(b, entity);
    }
    `match` = n.kind == KCall();
    if `match` {
        return backend_call(b, n);
    }
    `match` = n.kind == KSizeOf();
    if `match` {
        return backend_size_value(b, semantic_size(&n.element));
    }
    `match` = n.kind == KAlignOf();
    if `match` {
        return backend_size_value(b, semantic_alignment(&n.element));
    }
    `match` = n.kind == KAllocate();
    if `match` {
        var args: void*[2];
        args[0] = backend_read(b, n.right);
        args[1] = backend_size_value(b, semantic_size(&n.element));
        return backend_call_values(b, b.allocate_fn, &args[0], 2);
    }
    `match` = n.kind == KReallocate();
    if `match` {
        var args: void*[3];
        args[0] = backend_read(b, n.left);
        args[1] = backend_read(b, n.right);
        args[2] = backend_size_value(b, semantic_size(&n.element));
        return backend_call_values(b, b.reallocate_fn, &args[0], 3);
    }
    var left = n.value;
    `match` = n.kind == KBinary();
    if `match` {
        left = n.left;
    }
    var a = backend_expression(b, left);
    `match` = n.kind == KLoad();
    if `match` {
        var value = LLVMBuildLoad2(b.builder, backend_type(b, &n.type), a, "");
        LLVMSetAlignment(value, 1);
        return value;
    }
    var source = sem_get(left);
    var from = &source.type;
    `match` = n.kind == KBits();
    if `match` {
        var pointer = n.type.pointers != 0;
        var source_pointer = from.pointers != 0;
        var both = pointer;
        if both {
            both = source_pointer;
        }
        if both {
            return a;
        }
        if pointer {
            return LLVMBuildIntToPtr(b.builder, a, b.pointer_type, "");
        }
        if source_pointer {
            return LLVMBuildPtrToInt(b.builder, a, backend_type(b, &n.type), "");
        }
        return a;
    }
    `match` = n.kind == KConvert();
    if `match` {
        return backend_conversion(b, n, from, a);
    }
    var right = backend_expression(b, n.right);
    var pointer = from.pointers != 0;
    var arithmetic = n.op <= OSub();
    if arithmetic {
        arithmetic = pointer;
    }
    if arithmetic {
        var element: FoundationType;
        copy(&element, from, sizeof(FoundationType));
        element.pointers = element.pointers - 1;
        var r = sem_get(n.right);
        var delta = LLVMBuildIntCast2(b.builder, right, b.size_type, backend_signed(&r.type), "");
        delta = LLVMBuildMul(b.builder, delta, backend_size_value(b, semantic_size(&element)), "");
        var subtract = n.op == OSub();
        if subtract {
            delta = LLVMBuildNeg(b.builder, delta, "");
        }
        return backend_gep(b, a, delta);
    }
    `match` = n.op == OAdd();
    if `match` {
        return LLVMBuildAdd(b.builder, a, right, "");
    }
    `match` = n.op == OSub();
    if `match` {
        return LLVMBuildSub(b.builder, a, right, "");
    }
    `match` = n.op == OMul();
    if `match` {
        return LLVMBuildMul(b.builder, a, right, "");
    }
    `match` = n.op == OAnd();
    if `match` {
        return LLVMBuildAnd(b.builder, a, right, "");
    }
    `match` = n.op == OOr();
    if `match` {
        return LLVMBuildOr(b.builder, a, right, "");
    }
    `match` = n.op == OXor();
    if `match` {
        return LLVMBuildXor(b.builder, a, right, "");
    }
    var division = n.op == ODiv();
    var remainder = n.op == ORem();
    `match` = division;
    if remainder {
        `match` = true;
    }
    var signed = semantic_signed(from);
    if `match` {
        var nonzero = LLVMBuildICmp(b.builder, 33, right, LLVMConstNull(LLVMTypeOf(right)), "");
        backend_guard(b, nonzero, "Division by zero");
        if signed {
            var width = semantic_width(from);
            var limit = width - 1;
            var minimum: u64 = 1;
            var i: u32 = 0;
            loop {
                var done = i == limit;
                if done {
                    break;
                }
                minimum = minimum * 2;
                i = i + 1;
            }
            var min = LLVMConstInt(LLVMTypeOf(a), minimum, 0);
            var neg = LLVMConstInt(LLVMTypeOf(a), 18446744073709551615, 0);
            var first = LLVMBuildICmp(b.builder, 32, a, min, "");
            var second = LLVMBuildICmp(b.builder, 32, right, neg, "");
            var overflow = LLVMBuildAnd(b.builder, first, second, "");
            backend_guard(b, LLVMBuildNot(b.builder, overflow, ""), "Signed division overflow");
        }
        if division {
            if signed {
                return LLVMBuildSDiv(b.builder, a, right, "");
            }
            return LLVMBuildUDiv(b.builder, a, right, "");
        }
        if signed {
            return LLVMBuildSRem(b.builder, a, right, "");
        }
        return LLVMBuildURem(b.builder, a, right, "");
    }
    var predicate: u32 = 32;
    `match` = n.op == ONe();
    if `match` {
        predicate = 33;
    }
    `match` = n.op == OLt();
    if `match` {
        predicate = 36;
        if signed {
            predicate = 40;
        }
    }
    `match` = n.op == OLe();
    if `match` {
        predicate = 37;
        if signed {
            predicate = 41;
        }
    }
    `match` = n.op == OGt();
    if `match` {
        predicate = 34;
        if signed {
            predicate = 38;
        }
    }
    `match` = n.op == OGe();
    if `match` {
        predicate = 35;
        if signed {
            predicate = 39;
        }
    }
    var compare = LLVMBuildICmp(b.builder, predicate, a, right, "");
    return LLVMBuildZExt(b.builder, compare, b.i8, "");
}

fn backend_store(b: Backend*, destination: void*, value: void*): void {
    var store = LLVMBuildStore(b.builder, value, destination);
    LLVMSetAlignment(store, 1);
}

fn backend_assign(b: Backend*, target: void*, value: void*): void {
    // Capture the destination before any RHS side effects.
    var destination = backend_address(b, target);
    var result = backend_expression(b, value);
    backend_store(b, destination, result);
}

fn backend_terminated(b: Backend*): bool {
    var result = LLVMGetBasicBlockTerminator(LLVMGetInsertBlock(b.builder)) != null;
    return result;
}

fn backend_block(b: Backend*, entity: void*): void {
    var n = sem_get(entity);
    var i: usize = 0;
    loop {
        var done = i == n.items.length;
        if done {
            return;
        }
        var item = sem_get(n.items.data[i]);
        var active = backend_terminated(b) == false;
        var label = item.kind == 31;
        if label {
            active = true;
        }
        if active {
            backend_statement(b, n.items.data[i]);
        }
        i = i + 1;
    }
}

fn backend_branch(b: Backend*, block: void*): void {
    var open = backend_terminated(b) == false;
    if open {
        LLVMBuildBr(b.builder, block);
    }
}

fn backend_statement(b: Backend*, entity: void*): void {
    var n = sem_get(entity);
    b.source_offset = n.start;
    var label = n.kind == 31;
    if label {
        var block = backend_find(&b.labels, entity);
        backend_branch(b, block);
        LLVMPositionBuilderAtEnd(b.builder, block);
        return;
    }
    var jump = n.kind == 32;
    if jump {
        LLVMBuildBr(b.builder, backend_find(&b.labels, n.binding));
        return;
    }
    var trapping = n.kind == 33;
    if trapping {
        var args: void*[2];
        args[0] = backend_read(b, n.left);
        args[1] = LLVMBuildIntCast2(b.builder, backend_read(b, n.right), b.size_type, 0, "");
        backend_call_values(b, b.trap_fn, &args[0], 2);
        LLVMBuildUnreachable(b.builder);
        return;
    }
    var `match` = n.kind == KFunction();
    var type = n.kind == KType();
    if type {
        `match` = true;
    }
    if `match` {
        return;
    }
    `match` = n.kind == KBlock();
    if `match` {
        backend_block(b, entity);
        return;
    }
    `match` = n.kind == KDeclare();
    if `match` {
        var initialized = n.value != null;
        if initialized {
            backend_assign(b, entity, n.value);
        }
        return;
    }
    `match` = n.kind == KAssign();
    if `match` {
        backend_assign(b, n.target, n.value);
        return;
    }
    `match` = n.kind == KFree();
    if `match` {
        var argument = backend_read(b, n.left);
        backend_call_values(b, b.deallocate_fn, &argument, 1);
        return;
    }
    var move = n.kind == KCopy();
    var fill = n.kind == KFill();
    `match` = move;
    if fill {
        `match` = true;
    }
    if `match` {
        var destination = backend_read(b, n.left);
        var source = backend_read(b, n.right);
        var count = backend_read(b, n.value);
        if move {
            LLVMBuildMemMove(b.builder, destination, 1, source, 1, count);
        }
        else {
            LLVMBuildMemSet(b.builder, destination, source, count, 1);
        }
        return;
    }
    `match` = n.kind == KReturn();
    if `match` {
        var present = n.value != null;
        if present {
            LLVMBuildRet(b.builder, backend_read(b, n.value));
        }
        else {
            LLVMBuildRetVoid(b.builder);
        }
        return;
    }
    `match` = n.kind == KPrint();
    if `match` {
        var source = sem_get(n.value);
        var value = backend_read(b, n.value);
        var tag = source.type.scalar;
        var pointer = source.type.pointers != 0;
        if pointer {
            value = LLVMBuildPtrToInt(b.builder, value, b.i64, "");
            tag = 3;
        }
        else {
            value = LLVMBuildIntCast2(b.builder, value, b.i64, 0, "");
        }
        var args: void*[3];
        args[0] = LLVMConstInt(b.i32, convert(u64, tag), 0);
        args[1] = value;
        args[2] = LLVMConstInt(b.i32, convert(u64, b.pointer_bytes), 0);
        backend_call_values(b, b.print_fn, &args[0], 3);
        return;
    }
    `match` = n.kind == KIf();
    if `match` {
        var condition = backend_read(b, n.value);
        var yes = LLVMAppendBasicBlockInContext(b.context, b.current, "if.body");
        var no = LLVMAppendBasicBlockInContext(b.context, b.current, "if.else");
        var after = LLVMAppendBasicBlockInContext(b.context, b.current, "if.end");
        condition = LLVMBuildICmp(b.builder, 33, condition, LLVMConstNull(b.i8), "");
        LLVMBuildCondBr(b.builder, condition, yes, no);
        LLVMPositionBuilderAtEnd(b.builder, yes);
        backend_block(b, n.body);
        backend_branch(b, after);
        LLVMPositionBuilderAtEnd(b.builder, no);
        var other = n.otherwise != null;
        if other {
            backend_block(b, n.otherwise);
        }
        backend_branch(b, after);
        LLVMPositionBuilderAtEnd(b.builder, after);
        return;
    }
    `match` = n.kind == KLoop();
    if `match` {
        var head = LLVMAppendBasicBlockInContext(b.context, b.current, "loop");
        var after = LLVMAppendBasicBlockInContext(b.context, b.current, "loop.end");
        LLVMBuildBr(b.builder, head);
        LLVMPositionBuilderAtEnd(b.builder, head);
        var needed = b.loops.length + 1;
        var ok = vector_reserve(BackendLoop, &b.loops, needed);
        backend_require(b, ok);
        var failed = ok == false;
        if failed {
            return;
        }
        b.loops.data[b.loops.length].head = head;
        b.loops.data[b.loops.length].after = after;
        b.loops.length = needed;
        backend_block(b, n.body);
        backend_branch(b, head);
        b.loops.length = b.loops.length - 1;
        LLVMPositionBuilderAtEnd(b.builder, after);
        return;
    }
    var exit = n.kind == KBreak();
    var again = n.kind == KContinue();
    `match` = exit;
    if again {
        `match` = true;
    }
    if `match` {
        var index = b.loops.length - 1;
        var destination = b.loops.data[index].head;
        if exit {
            destination = b.loops.data[index].after;
        }
        LLVMBuildBr(b.builder, destination);
        return;
    }
    backend_expression(b, entity);
}

fn backend_reserved(name: u8*): bool {
    var found = backend_equal(name, "tower_main");
    if found {
        return true;
    }
    found = backend_equal(name, "tower_print");
    if found {
        return true;
    }
    found = backend_equal(name, "tower_trap");
    if found {
        return true;
    }
    found = backend_equal(name, "tower_allocate");
    if found {
        return true;
    }
    found = backend_equal(name, "tower_reallocate");
    if found {
        return true;
    }
    return backend_equal(name, "tower_deallocate");
}

export fn backend_lower(b: Backend*, root: void*, functions: void**, count: usize, pointer_bytes: u32, library: bool): bool {
    b.source_root = root;
    var failed = b.error.length != 0;
    if failed {
        return false;
    }
    var mismatch = pointer_bytes != b.pointer_bytes;
    if mismatch {
        backend_fail(b, "Foundation target layout does not match LLVM target");
        return false;
    }
    if library {
        var program = sem_get(root);
        var i: usize = 0;
        loop {
            var done = i == program.items.length;
            if done {
                break;
            }
            var n = sem_get(program.items.data[i]);
            var allowed = n.kind == KFunction();
            var type = n.kind == KType();
            if type {
                allowed = true;
            }
            failed = allowed == false;
            if failed {
                b.source_offset = n.start;
                backend_fail(b, "Library source cannot contain top-level executable statements");
                return false;
            }
            i = i + 1;
        }
    }
    backend_runtime_declarations(b);
    var i: usize = 0;
    loop {
        var done = i == count;
        if done {
            break;
        }
        var n = sem_get(functions[i]);
        var entry = i == 0;
        var omit = entry;
        if omit {
            omit = library;
        }
        if omit {
            backend_require(b, vector_push(void*, &b.functions, null));
            backend_require(b, vector_push(u8*, &b.symbols, null));
            i = i + 1;
            continue;
        }
        var public = n.external;
        if n.exported {
            public = true;
        }
        if public {
            var reserved = backend_reserved(backend_name(n));
            if reserved {
                b.source_offset = n.start;
                backend_fail(b, "Function symbol conflicts with Tower runtime: ");
                backend_text(&b.error, backend_name(n));
                return false;
            }
        }
        var args: vector(void*);
        vector_init(void*, &args);
        var j: usize = 0;
        loop {
            done = j == n.parameters.length;
            if done {
                break;
            }
            var p = sem_get(n.parameters.data[j]);
            backend_require(b, vector_push(void*, &args, backend_type(b, &p.type)));
            j = j + 1;
        }
        var type = LLVMFunctionType(backend_type(b, &n.type), args.data, convert(u32, args.length), 0);
        vector_dispose(void*, &args);
        var name: vector(u8);
        vector_init(u8, &name);
        var convention: u32 = 0;
        if entry {
            backend_text(&name, "tower_main");
        }
        else {
            var private = public == false;
            if private {
                backend_text(&name, "tower.fn.");
            }
            if public {
                var spelling = foreign_symbol(b.foreign_profile, backend_name(n));
                convention = foreign_llvm_convention(spelling);
                var error = foreign_name_error(spelling);
                var failed_name = error[0] != 0;
                if failed_name {
                    b.source_offset = n.start;
                    backend_fail(b, error);
                    foreign_name_close(spelling);
                    vector_dispose(u8, &name);
                    return false;
                }
                backend_text(&name, foreign_name_text(spelling));
                foreign_name_close(spelling);
            } else {
                backend_text(&name, backend_name(n));
            }
        }
        if public {
            var reserved = backend_reserved(name.data);
            var duplicate = LLVMGetNamedFunction(b.module, name.data) != null;
            if duplicate {
                reserved = true;
            }
            if reserved {
                b.source_offset = n.start;
                backend_fail(b, "Duplicate or reserved foreign symbol: ");
                backend_text(&b.error, name.data);
                vector_dispose(u8, &name);
                return false;
            }
        }
        var function = LLVMAddFunction(b.module, name.data, type);
        LLVMSetFunctionCallConv(function, convention);
        var internal = public == false;
        var nonentry = entry == false;
        if internal {
            internal = nonentry;
        }
        if internal {
            LLVMSetLinkage(function, 8);
        }
        backend_abi(b, function, n, false);
        if b.wasm {
            if n.external {
                backend_attribute(b, function, "wasm-import-module", "env");
                backend_attribute(b, function, "wasm-import-name", name.data);
            }
            if n.exported {
                backend_attribute(b, function, "wasm-export-name", name.data);
            }
        }
        backend_require(b, vector_push(u8*, &b.symbols, name.data));
        backend_require(b, vector_push(void*, &b.functions, function));
        backend_require(b, vector_push(void*, &b.source_functions, functions[i]));
        i = i + 1;
    }
    i = 0;
    loop {
        var done = i == count;
        if done {
            break;
        }
        var n = sem_get(functions[i]);
        var function = b.functions.data[i];
        var omit = function == null;
        if n.external {
            omit = true;
        }
        if omit {
            i = i + 1;
            continue;
        }
        b.current = function;
        b.locals.length = 0;
        b.loops.length = 0;
        b.labels.length = 0;
        var entry = LLVMAppendBasicBlockInContext(b.context, function, "entry");
        LLVMPositionBuilderAtEnd(b.builder, entry);
        var j: usize = 0;
        loop {
            done = j == n.locals.length;
            if done {
                break;
            }
            var local = sem_get(n.locals.data[j]);
            var slot: void* = null;
            var nonglobal = local.global == false;
            if nonglobal {
                slot = LLVMBuildAlloca(b.builder, backend_type(b, &local.type), backend_name(local));
                LLVMSetAlignment(slot, convert(u32, semantic_alignment(&local.type)));
            }
            backend_require(b, vector_push(void*, &b.locals, slot));
            j = j + 1;
        }
        j = 0;
        loop {
            done = j == n.parameters.length;
            if done {
                break;
            }
            backend_store(b, backend_address(b, n.parameters.data[j]), LLVMGetParam(function, convert(u32, j)));
            j = j + 1;
        }
        var body = n.body;
        var top = i == 0;
        if top {
            body = root;
        }
        var block_node = sem_get(body);
        j = 0;
        loop {
            done = j == block_node.items.length;
            if done {
                break;
            }
            var item = block_node.items.data[j];
            var label = sem_get(item);
            var is_label = label.kind == 31;
            if is_label {
                var block = LLVMAppendBasicBlockInContext(b.context, function, backend_name(label));
                backend_require(b, backend_associate(&b.labels, item, block));
            }
            j = j + 1;
        }
        backend_block(b, body);
        var open = backend_terminated(b) == false;
        if open {
            var empty = n.type.scalar == SVoid();
            var scalar = n.type.pointers == 0;
            if empty {
                empty = scalar;
            }
            if empty {
                LLVMBuildRetVoid(b.builder);
            }
            else {
                LLVMBuildUnreachable(b.builder);
            }
        }
        i = i + 1;
    }
    failed = b.error.length != 0;
    if failed {
        return false;
    }
    var valid = backend_verify(b);
    if valid {
        b.raw = LLVMPrintModuleToString(b.module);
    }
    return valid;
}

import tower;

fn backend_verify(b: Backend*): bool {
    var message: u8* = null;
    // LLVMReturnStatusAction: malformed IR is a diagnostic, never process abort.
    var status = LLVMVerifyModule(b.module, 2, &message);
    var failed = status != 0;
    if failed {
        backend_fail(b, message);
    }
    LLVMDisposeMessage(message);
    var result = status == 0;
    return result;
}

export fn backend_optimize(b: Backend*, optimize: bool): bool {
    var failed = b.error.length != 0;
    if failed {
        return false;
    }
    if optimize {
        var options = LLVMCreatePassBuilderOptions();
        LLVMPassBuilderOptionsSetVerifyEach(options, 1);
        var error = LLVMRunPasses(b.module, "function(sroa,mem2reg,instcombine<no-verify-fixpoint>,simplifycfg),default<O2>", b.machine, options);
        LLVMDisposePassBuilderOptions(options);
        failed = error != null;
        if failed {
            var message = LLVMGetErrorMessage(error);
            backend_fail(b, message);
            LLVMDisposeErrorMessage(message);
            return false;
        }
    }
    var valid = backend_verify(b);
    if valid {
        b.optimized = LLVMPrintModuleToString(b.module);
    }
    return valid;
}

export fn backend_emit(b: Backend*): bool {
    var failed = b.error.length != 0;
    if failed {
        return false;
    }
    var message: u8* = null;
    // LLVMObjectFile, not assembly or an interchange encoding.
    var status = LLVMTargetMachineEmitToMemoryBuffer(b.machine, b.module, 1, &message, &b.object);
    failed = status != 0;
    if failed {
        backend_fail(b, message);
    }
    var present = message != null;
    if present {
        LLVMDisposeMessage(message);
    }
    var result = status == 0;
    return result;
}

import tower;

// Host build service for compiler reactors. Inputs and arguments are explicit
// capabilities supplied by the build recipe, never filesystem/tool searches.
// Keep adding Tower modules to that recipe as native adapters are ported; remove
// their prebuilt support objects only after successor/differential checks pass.
export fn backend_reactor_argument(link: BackendLink*, argument: u8*): void {
    backend_link_argument(link, "", argument);
}

export fn backend_reactor_link(link: BackendLink*): bool {
    var i: usize = 0;
    loop {
        var done = i == link.inputs.length;
        if done {
            break;
        }
        var input = &link.inputs.data[i];
        var ok = backend_write_file(link, input.name.data, input.bytes.data, input.bytes.length);
        if ok {} else {
            return false;
        }
        i = i + 1;
    }
    var valid = link.error.length == 0;
    if valid {
        return backend_link_wasi(link, "wasm32-unknown-unknown");
    }
    return false;
}

export fn backend_reactor_bytes(link: BackendLink*): u8* {
    return link.output.data;
}

export fn backend_reactor_size(link: BackendLink*): usize {
    return link.output.length;
}

export fn backend_reactor_error(link: BackendLink*): u8* {
    return link.error.data;
}

import tower;

extern fn __wasi_clock_time_get(clock: u32, precision: u64, time: u64*): u32;

fn backend_session_clock(): u64 {
    var now: u64 = 0;
    // Monotonic time measures execution only; it never affects generated code.
    __wasi_clock_time_get(1, 1000, &now);
    return now;
}

import tower;

// Backend service over validated Foundation entities. Source parsing and worker/
// CLI scheduling belong to callers. Results own their buffers until reset/close.
struct BackendSession {
    target: vector(u8);
    response: vector(u8);
    backend: Backend*;
    linker: BackendLink*;
    decoder: BackendDecoder*;
    runtime: u8*;
    runtime_size: usize;
    object_only: bool;
    optimization_enabled: bool;
    times: u64[6];
}

extern fn semantic_format_type(type: FoundationType*, output: vector(u8)*): void;

fn backend_json(out: vector(u8)*, text: u8*, length: usize): void {
    backend_text(out, "\"");
    var i: usize = 0;
    var digits: u8* = "0123456789abcdef";
    loop {
        var done = i == length;
        if done {
            break;
        }
        var byte = text[i];
        var escape = byte == 34;
        var slash = byte == 92;
        if slash {
            escape = true;
        }
        if escape {
            backend_text(out, "\\");
            backend_text_append(out, &text[i], 1);
        } else {
            var control = byte < 32;
            if control {
                backend_text(out, "\\u00");
                var high = convert(usize, byte) / 16;
                var low = convert(usize, byte) % 16;
                backend_text_append(out, &digits[high], 1);
                backend_text_append(out, &digits[low], 1);
            } else {
                backend_text_append(out, &text[i], 1);
            }
        }
        i = i + 1;
    }
    backend_text(out, "\"");
}

fn backend_json_text(out: vector(u8)*, text: u8*): void {
    backend_json(out, text, backend_length(text));
}

export fn backend_session_create(runtime: u8*, length: usize): BackendSession* {
    var s = alloc(BackendSession, 1);
    var failed = s == null;
    if failed {
        return null;
    }
    fill(s, 0, sizeof(BackendSession));
    s.linker = backend_link_create();
    failed = s.linker == null;
    if failed {
        free(s);
        return null;
    }
    s.runtime = runtime;
    s.runtime_size = length;
    backend_text(&s.target, "wasm32-unknown-unknown");
    return s;
}

export fn backend_session_reset(s: BackendSession*): void {
    backend_close(s.backend);
    backend_disassembly_close(s.decoder);
    s.backend = null;
    s.decoder = null;
    s.object_only = false;
    s.response.length = 0;
    backend_link_reset_plan(s.linker);
    fill(&s.times[0], 0, sizeof(u64[6]));
}

export fn backend_session_close(s: BackendSession*): void {
    var absent = s == null;
    if absent {
        return;
    }
    backend_session_reset(s);
    backend_link_close(s.linker);
    vector_dispose(u8, &s.target);
    vector_dispose(u8, &s.response);
    free(s);
}

export fn backend_session_set_target(s: BackendSession*, target: u8*): bool {
    var absent = target == null;
    if absent {
        return false;
    }
    var valid = backend_filename(target);
    if valid {
        s.target.length = 0;
        backend_text(&s.target, target);
    }
    return valid;
}

export fn backend_session_clear_inputs(s: BackendSession*): void {
    backend_link_clear_inputs(s.linker);
}

export fn backend_session_add_input(s: BackendSession*, name: u8*, bytes: u8*, length: usize): bool {
    return backend_link_add_input(s.linker, name, bytes, length);
}

export fn backend_session_failure(s: BackendSession*, error: u8*, offset: usize): u8* {
    s.linker.output.length = 0;
    s.response.length = 0;
    backend_text(&s.response, "{\"status\":\"error\",\"error\":");
    backend_json_text(&s.response, error);
    backend_text(&s.response, ",\"errorOffset\":");
    backend_decimal(&s.response, convert(u64, offset));
    backend_text(&s.response, "}");
    return s.response.data;
}

export fn backend_session_begin(s: BackendSession*, source: u8*, length: usize): u32 {
    backend_session_reset(s);
    var invalid = source == null;
    var large = length > 8388608;
    if large {
        invalid = true;
    }
    if invalid {
        backend_session_failure(s, "Invalid foundation source length", 0);
        return 0;
    }
    var i: usize = 0;
    loop {
        var done = i == length;
        if done {
            break;
        }
        var zero = source[i] == 0;
        if zero {
            backend_session_failure(s, "Foundation source cannot contain NUL bytes", 0);
            return 0;
        }
        i = i + 1;
    }
    s.times[0] = backend_session_clock();
    s.backend = backend_open(s.target.data);
    var absent = s.backend == null;
    if absent {
        backend_session_failure(s, "Unable to allocate backend storage", 0);
        return 0;
    }
    var failed = s.backend.error.length != 0;
    if failed {
        backend_session_failure(s, backend_error(s.backend), 0);
        return 0;
    }
    return s.backend.pointer_bytes;
}

export fn backend_session_bytes(s: BackendSession*): u8* {
    if s.object_only {
        return backend_bytes(s.backend);
    }
    return s.linker.output.data;
}

export fn backend_session_size(s: BackendSession*): usize {
    if s.object_only {
        return backend_size(s.backend);
    }
    return s.linker.output.length;
}

export fn backend_session_before(s: BackendSession*): u8* {
    var present = s.backend != null;
    if present {
        present = s.backend.raw != null;
        if present {
            return s.backend.raw;
        }
    }
    return "";
}

export fn backend_session_after(s: BackendSession*): u8* {
    var present = s.backend != null;
    if present {
        present = s.backend.optimized != null;
        if present {
            return s.backend.optimized;
        }
    }
    return "";
}

export fn backend_session_disassembly(s: BackendSession*): u8* {
    var present = s.decoder != null;
    if present {
        return backend_disassembly_text(s.decoder);
    }
    return "";
}

export fn backend_session_response(s: BackendSession*): u8* {
    return s.response.data;
}

fn backend_session_names(b: Backend*, out: vector(u8)*, functions: void**, count: usize, imports: bool): void {
    backend_text(out, "[");
    var first = true;
    var i: usize = 1;
    loop {
        var done = i >= count;
        if done {
            break;
        }
        var n = sem_get(functions[i]);
        var selected = n.exported;
        if imports {
            selected = n.external;
        }
        if selected {
            var comma = first == false;
            if comma {
                backend_text(out, ",");
            }
            backend_json_text(out, backend_function_name(b, i));
            first = false;
        }
        i = i + 1;
    }
    backend_text(out, "]");
}

fn backend_session_report(s: BackendSession*, functions: void**, count: usize): void {
    var out = &s.response;
    out.length = 0;
    backend_text(out, "{\"status\":\"compiled\",\"format\":");
    var format: u8* = "elf";
    var windows = backend_contains(s.target.data, "windows");
    if windows {
        format = "pe";
    }
    var mac = backend_contains(s.target.data, "apple");
    if mac {
        format = "macho";
    }
    if s.backend.wasm {
        format = "wasm";
    }
    if s.object_only {
        format = "object";
    }
    backend_json_text(out, format);
    backend_text(out, ",\"target\":");
    backend_json_text(out, s.target.data);
    backend_text(out, ",\"imports\":");
    backend_session_names(s.backend, out, functions, count, true);
    backend_text(out, ",\"exports\":");
    backend_session_names(s.backend, out, functions, count, false);
    backend_text(out, ",\"signatures\":{");
    var first = true;
    var i: usize = 1;
    loop {
        var done = i >= count;
        if done {
            break;
        }
        var n = sem_get(functions[i]);
        if n.external {
            var comma = first == false;
            if comma {
                backend_text(out, ",");
            }
            first = false;
            backend_json_text(out, backend_function_name(s.backend, i));
            backend_text(out, ":[");
            var j: usize = 0;
            loop {
                done = j == n.parameters.length;
                if done {
                    break;
                }
                comma = j != 0;
                if comma {
                    backend_text(out, ",");
                }
                var parameter = sem_get(n.parameters.data[j]);
                var name: vector(u8);
                vector_init(u8, &name);
                semantic_format_type(&parameter.type, &name);
                backend_json(out, name.data, name.length);
                vector_dispose(u8, &name);
                j = j + 1;
            }
            backend_text(out, "]");
        }
        i = i + 1;
    }
    backend_text(out, "},\"timings\":{");
    i = 0;
    loop {
        var done = i == 6;
        if done {
            break;
        }
        var unlinked = i == 4;
        if unlinked {
            unlinked = s.object_only;
        }
        if unlinked {
            i = i + 1;
            continue;
        }
        var comma = i != 0;
        if comma {
            backend_text(out, ",");
        }
        var name: u8* = "parse";
        var `match` = i == 1;
        if `match` {
            name = "before";
        }
        `match` = i == 2;
        if `match` {
            name = "after";
        }
        `match` = i == 3;
        if `match` {
            name = "emit";
        }
        `match` = i == 4;
        if `match` {
            name = "link";
        }
        `match` = i == 5;
        if `match` {
            name = "disassembly";
        }
        backend_json_text(out, name);
        backend_text(out, ":");
        var micros = s.times[i] / 1000;
        var millis = micros / 1000;
        var fraction = micros % 1000;
        backend_decimal(out, millis);
        backend_text(out, ".");
        var padding = fraction < 100;
        if padding {
            backend_text(out, "0");
        }
        padding = fraction < 10;
        if padding {
            backend_text(out, "0");
        }
        backend_decimal(out, fraction);
        i = i + 1;
    }
    backend_text(out, "},\"bytes\":");
    backend_decimal(out, convert(u64, backend_session_size(s)));
    backend_text(out, ",\"passes\":");
    if s.optimization_enabled {
        backend_json_text(out, "sroa, mem2reg, instcombine, simplifycfg, O2");
    }
    else {
        backend_json_text(out, "disabled");
    }
    backend_text(out, "}");
}

export fn backend_session_compile(s: BackendSession*, root: void*, functions: void**, count: usize, width: u32, flags: u32): u8* {
    var started = backend_session_clock();
    s.times[0] = started - s.times[0];
    var object_flags = flags & 3;
    s.object_only = object_flags != 0;
    var library_flag = flags & 2;
    var library = library_flag != 0;
    var ok = backend_lower(s.backend, root, functions, count, width, library);
    var next = backend_session_clock();
    s.times[1] = next - started;
    started = next;
    if ok {
        var no_optimization = flags & 8;
        var optimize = no_optimization == 0;
        s.optimization_enabled = optimize;
        ok = backend_optimize(s.backend, optimize);
    }
    next = backend_session_clock();
    s.times[2] = next - started;
    started = next;
    if ok {
        ok = backend_emit(s.backend);
    }
    next = backend_session_clock();
    s.times[3] = next - started;
    started = next;
    var failed = ok == false;
    if failed {
        return backend_session_failure(s, backend_error(s.backend), s.backend.error_offset);
    }
    var executable = s.object_only == false;
    if executable {
        ok = backend_link_plan(s.linker, s.target.data, functions, count, backend_bytes(s.backend), backend_size(s.backend), s.runtime, s.runtime_size);
        // Match the existing measurement boundary: argument/file preparation
        // precedes the upstream linker invocation. Wall time includes both.
        started = backend_session_clock();
        if ok {
            ok = backend_link_wasi(s.linker, s.target.data);
        }
        failed = ok == false;
        if failed {
            return backend_session_failure(s, s.linker.error.data, 0);
        }
    }
    next = backend_session_clock();
    s.times[4] = next - started;
    started = next;
    s.decoder = backend_disassemble(backend_session_bytes(s), backend_session_size(s), s.target.data);
    next = backend_session_clock();
    s.times[5] = next - started;
    backend_session_report(s, functions, count);
    return s.response.data;
}

export fn backend_session_import(s: BackendSession*, root: void*, functions: void**, count: usize, width: u32, optimize: bool, output: void*): bool {
    var ok = backend_lower(s.backend, root, functions, count, width, false);
    if ok {
        ok = backend_optimize_interpreter(s.backend, optimize);
    }
    if ok {
        ok = backend_import_foundation(s.backend, output);
    }
    if ok {} else {
        backend_session_failure(s, backend_error(s.backend), s.backend.error_offset);
    }
    return ok;
}

export fn backend_session_import_report(s: BackendSession*, optimize: bool): u8* {
    s.response.length = 0;
    backend_text(&s.response, "{\"status\":\"compiled\",\"format\":\"foundation\",\"optimizationProfile\":");
    if optimize {
        backend_text(&s.response, "1");
    }
    else {
        backend_text(&s.response, "2");
    }
    backend_text(&s.response, "}");
    return s.response.data;
}

