// Derived automata over integer symbols, shared by character and token grammars.
// The source grammar/entities remain authoritative. Limits bound compilation work.
struct AutomatonState {
    kind: u32;
    out: i32;
    other: i32;
    negated: bool;
    ranges: vector(SymbolRange);
}

struct Automaton {
    states: AutomatonState*;
    count: usize;
    limit: u32;
    error: u32;
}

struct AutomatonSubset {
    bits: u64[8];
}

struct AutomatonWork {
    masks: u64[64];
    visited: u8[512];
    pending: i32[1024];
    seeds: i32[512];
    subsets: vector(AutomatonSubset);
    links: vector(i32);
    buckets: i32[2039];
    row: vector(i32);
    alphabet: vector(u32);
}

export fn automaton_create(symbol_limit: u32): Automaton* {
    var result = alloc(Automaton, 1);
    var failed = result == null;
    if failed {
        return null;
    }
    fill(result, 0, sizeof(Automaton));
    result.states = alloc(AutomatonState, 512);
    failed = result.states == null;
    if failed {
        free(result);
        return null;
    }
    var bytes = sizeof(AutomatonState) * 512;
    fill(result.states, 0, bytes);
    result.limit = symbol_limit;
    return result;
}

export fn automaton_destroy(value: Automaton*): void {
    var empty = value == null;
    if empty {
        return;
    }
    var i: usize = 0;
    loop {
        var done = i == value.count;
        if done {
            break;
        }
        vector_dispose(SymbolRange, &value.states[i].ranges);
        i = i + 1;
    }
    free(value.states);
    free(value);
}

export fn automaton_error(value: Automaton*): u32 {
    return value.error;
}

// Kinds: 0 = consuming range, 1 = epsilon split, 2 = accepting state.
export fn automaton_add(value: Automaton*, kind: u32, out: i32, other: i32, negated: bool): i32 {
    var full = value.count >= 512;
    if full {
        value.error = 1;
        return -1;
    }
    var index = value.count;
    value.states[index].kind = kind;
    value.states[index].out = out;
    value.states[index].other = other;
    value.states[index].negated = negated;
    value.count = index + 1;
    return convert(i32, index);
}

export fn automaton_range(value: Automaton*, index: i32, first: u32, last: u32): bool {
    var invalid = index < 0;
    if invalid {
        return false;
    }
    var state = &value.states[index];
    var size = state.ranges.length + 1;
    var ok = vector_reserve(SymbolRange, &state.ranges, size);
    if ok {
        state.ranges.data[state.ranges.length].first = first;
        state.ranges.data[state.ranges.length].last = last;
        state.ranges.length = size;
    } else {
        value.error = 2;
    }
    return ok;
}

export fn automaton_patch(value: Automaton*, index: i32, other: bool, target: i32): void {
    var invalid = index < 0;
    if invalid {
        return;
    }
    if other {
        value.states[index].other = target;
    }
    else {
        value.states[index].out = target;
    }
}

fn automaton_sift(values: u32*, size: usize, start: usize): void {
    var root = start;
    loop {
        var child = root * 2;
        child = child + 1;
        var done = child >= size;
        if done {
            return;
        }
        var right = child + 1;
        var exists = right < size;
        if exists {
            var larger = values[right] > values[child];
            if larger {
                child = right;
            }
        }
        var ordered = values[root] >= values[child];
        if ordered {
            return;
        }
        var saved = values[root];
        values[root] = values[child];
        values[child] = saved;
        root = child;
    }
}

fn automaton_sort(values: u32*, size: usize): void {
    var start = size / 2;
    loop {
        var done = start == 0;
        if done {
            break;
        }
        start = start - 1;
        automaton_sift(values, size, start);
    }
    var end = size;
    loop {
        var done = end <= 1;
        if done {
            return;
        }
        end = end - 1;
        var saved = values[0];
        values[0] = values[end];
        values[end] = saved;
        automaton_sift(values, end, 0);
    }
}

fn automaton_has(work: AutomatonWork*, subset: AutomatonSubset*, index: usize): bool {
    var word = index / 64;
    var bit = index % 64;
    var masked = subset.bits[word] & work.masks[bit];
    var present = masked != 0;
    return present;
}

fn automaton_closure(value: Automaton*, work: AutomatonWork*, count: usize, result: AutomatonSubset*): bool {
    fill(result, 0, sizeof(AutomatonSubset));
    fill(&work.visited, 0, value.count);
    var bytes = count * sizeof(i32);
    copy(&work.pending, &work.seeds, bytes);
    var any = false;
    loop {
        var done = count == 0;
        if done {
            return any;
        }
        count = count - 1;
        var index = work.pending[count];
        var absent = index < 0;
        if absent {
            continue;
        }
        var seen = work.visited[index] != 0;
        if seen {
            continue;
        }
        work.visited[index] = 1;
        var state = &value.states[index];
        var split = state.kind == 1;
        if split {
            work.pending[count] = state.out;
            count = count + 1;
            work.pending[count] = state.other;
            count = count + 1;
        } else {
            var word = index / 64;
            var bit = index % 64;
            result.bits[word] = result.bits[word] | work.masks[bit];
            any = true;
        }
    }
}

fn automaton_intern(value: Automaton*, work: AutomatonWork*, subset: AutomatonSubset*): i32 {
    var hash: u64 = 2166136261;
    var words = value.count + 63;
    words = words / 64;
    var i: usize = 0;
    loop {
        var done = i == words;
        if done {
            break;
        }
        hash = hash ^ subset.bits[i];
        hash = hash * 16777619;
        i = i + 1;
    }
    var bucket = hash % 2039;
    var found = work.buckets[bucket];
    loop {
        var done = found < 0;
        if done {
            break;
        }
        var same = true;
        i = 0;
        loop {
            done = i == words;
            if done {
                break;
            }
            var different = subset.bits[i] != work.subsets.data[found].bits[i];
            if different {
                same = false;
                break;
            }
            i = i + 1;
        }
        if same {
            return found;
        }
        found = work.links.data[found];
    }
    var index = work.subsets.length;
    var count = index + 1;
    var complexity = count * work.alphabet.length;
    var large = index >= 1024;
    if large {
        value.error = 3;
        return -1;
    }
    large = complexity > 262144;
    if large {
        value.error = 3;
        return -1;
    }
    var ok = vector_reserve(AutomatonSubset, &work.subsets, count);
    if ok {} else {
        value.error = 2;
        return -1;
    }
    ok = vector_push(i32, &work.links, work.buckets[bucket]);
    if ok {} else {
        value.error = 2;
        return -1;
    }
    var result = convert(i32, index);
    copy(&work.subsets.data[result], subset, sizeof(AutomatonSubset));
    work.subsets.length = count;
    work.buckets[bucket] = result;
    return result;
}

fn automaton_build(value: Automaton*, start: i32, accepting: usize, table: LexerTable*, work: AutomatonWork*, reject_empty: bool): u32 {
    var failed = value.error != 0;
    if failed {
        return value.error;
    }
    var mask: u64 = 1;
    var i: usize = 0;
    loop {
        var done = i == 64;
        if done {
            break;
        }
        work.masks[i] = mask;
        mask = mask * 2;
        i = i + 1;
    }
    var bucket_bytes = sizeof(i32) * 2039;
    fill(&work.buckets, 255, bucket_bytes);
    var count: usize = 2;
    i = 0;
    loop {
        var done = i == value.count;
        if done {
            break;
        }
        var ranges = value.states[i].ranges.length * 2;
        count = count + ranges;
        i = i + 1;
    }
    var ok = vector_reserve(u32, &work.alphabet, count);
    if ok {} else {
        return 2;
    }
    work.alphabet.data[0] = 0;
    work.alphabet.data[1] = value.limit;
    count = 2;
    i = 0;
    loop {
        var done = i == value.count;
        if done {
            break;
        }
        var state = &value.states[i];
        var j: usize = 0;
        loop {
            done = j == state.ranges.length;
            if done {
                break;
            }
            work.alphabet.data[count] = state.ranges.data[j].first;
            count = count + 1;
            work.alphabet.data[count] = state.ranges.data[j].last + 1;
            count = count + 1;
            j = j + 1;
        }
        i = i + 1;
    }
    automaton_sort(work.alphabet.data, count);
    work.alphabet.length = 1;
    i = 1;
    loop {
        var done = i == count;
        if done {
            break;
        }
        var previous = i - 1;
        var different = work.alphabet.data[i] != work.alphabet.data[previous];
        if different {
            work.alphabet.data[work.alphabet.length] = work.alphabet.data[i];
            work.alphabet.length = work.alphabet.length + 1;
        }
        i = i + 1;
    }
    ok = lex_table_set_alphabet(table, work.alphabet.data, work.alphabet.length);
    if ok {} else {
        return 2;
    }
    work.seeds[0] = start;
    var initial: AutomatonSubset;
    automaton_closure(value, work, 1, &initial);
    var nullable = automaton_has(work, &initial, accepting);
    if reject_empty {
        if nullable {
            return 4;
        }
    }
    var first = automaton_intern(value, work, &initial);
    failed = first < 0;
    if failed {
        return value.error;
    }
    var columns = work.alphabet.length - 1;
    ok = vector_reserve(i32, &work.row, columns);
    if ok {} else {
        return 2;
    }
    var row: usize = 0;
    loop {
        var done = row == work.subsets.length;
        if done {
            return 0;
        }
        var accepted = automaton_has(work, &work.subsets.data[row], accepting);
        var column: usize = 0;
        loop {
            done = column == columns;
            if done {
                break;
            }
            var symbol = work.alphabet.data[column];
            var seeds: usize = 0;
            i = 0;
            loop {
                done = i == value.count;
                if done {
                    break;
                }
                var present = automaton_has(work, &work.subsets.data[row], i);
                var state = &value.states[i];
                var character = state.kind == 0;
                if present {
                    if character {
                        var inside = false;
                        var j: usize = 0;
                        loop {
                            done = j == state.ranges.length;
                            if done {
                                break;
                            }
                            var above = symbol >= state.ranges.data[j].first;
                            var below = symbol <= state.ranges.data[j].last;
                            if above {
                                if below {
                                    inside = true;
                                    break;
                                }
                            }
                            j = j + 1;
                        }
                        var matches = inside != state.negated;
                        if matches {
                            work.seeds[seeds] = state.out;
                            seeds = seeds + 1;
                        }
                    }
                }
                i = i + 1;
            }
            var subset: AutomatonSubset;
            var nonempty = automaton_closure(value, work, seeds, &subset);
            var next: i32 = -1;
            if nonempty {
                next = automaton_intern(value, work, &subset);
                failed = next < 0;
                if failed {
                    return value.error;
                }
            }
            work.row.data[column] = next;
            column = column + 1;
        }
        ok = lex_table_append(table, work.row.data, columns, accepted);
        if ok {} else {
            return 2;
        }
        row = row + 1;
    }
}

// Returns 0 on success, 1 for NFA size, 2 allocation, 3 DFA size, 4 nullable.
export fn automaton_compile(value: Automaton*, start: i32, accepting: usize, table: LexerTable*, reject_empty: bool): u32 {
    var work = alloc(AutomatonWork, 1);
    var failed = work == null;
    if failed {
        return 2;
    }
    fill(work, 0, sizeof(AutomatonWork));
    var result = automaton_build(value, start, accepting, table, work, reject_empty);
    vector_dispose(AutomatonSubset, &work.subsets);
    vector_dispose(i32, &work.links);
    vector_dispose(i32, &work.row);
    vector_dispose(u32, &work.alphabet);
    free(work);
    return result;
}

import tower;

// .towerbc v1: portable, versioned distribution envelope. Canonical Foundation
// is the semantic authority; packed words/constants are a verified execution
// cache. A loader rebuilds the graph and checks the cache before any execution.
// This makes reconstruction exact without inventing a second type/binding ABI.
// All integer fields and payload words are little endian, regardless of host.
fn bc_read(data: u8*, at: usize, size: usize): u64 {
    var result: u64 = 0;
    var factor: u64 = 1;
    var i: usize = 0;
    loop {
        var end = i == size;
        if end {
            return result;
        }
        var index = at + i;
        var byte = convert(u64, data[index]);
        byte = byte * factor;
        result = result | byte;
        factor = factor * 256;
        i = i + 1;
    }
}

fn bc_write(data: u8*, at: usize, value: u64, size: usize): void {
    var i: usize = 0;
    loop {
        var end = i == size;
        if end {
            return;
        }
        var index = at + i;
        data[index] = im_byte(value);
        value = value / 256;
        i = i + 1;
    }
}

fn bc_checksum(data: u8*, length: usize): u64 {
    // FNV-1a detects corruption; it is not authentication. The cache comparison
    // against freshly checked Foundation, not this hash, validates instructions.
    var hash: u64 = 14695981039346656037;
    var i: usize = 0;
    loop {
        var end = i == length;
        if end {
            return hash;
        }
        var byte: u64 = 0;
        var prefix = i < 48;
        var payload = i >= 56;
        var included = im_or(prefix, payload);
        if included {
            byte = convert(u64, data[i]);
        }
        hash = hash ^ byte;
        hash = hash * 1099511628211;
        i = i + 1;
    }
}

export fn bytecode_validate(data: u8*, length: usize): u32 {
    var short = length < 56;
    if short {
        return 1;
    }
    var large = length > 268435456;
    if large {
        return 1;
    }
    var magic = "TOWERBC";
    var i: usize = 0;
    loop {
        var end = i == 8;
        if end {
            break;
        }
        var different = data[i] != magic[i];
        if different {
            return 2;
        }
        i = i + 1;
    }
    var version = bc_read(data, 8, 4) != 1;
    if version {
        return 3;
    }
    version = bc_read(data, 12, 4) != 2;
    if version {
        return 4;
    }
    version = bc_read(data, 16, 4) != 2;
    if version {
        return 5;
    }
    var width = bc_read(data, 20, 4);
    var invalid = width != 4;
    var not64 = width != 8;
    invalid = im_and(invalid, not64);
    if invalid {
        return 6;
    }
    invalid = bc_read(data, 24, 4) > 2;
    if invalid {
        return 7;
    }
    invalid = bc_read(data, 44, 4) != 0;
    if invalid {
        return 7;
    }
    var source = bc_read(data, 28, 4);
    invalid = source > 8388608;
    if invalid {
        return 1;
    }
    var words = bc_read(data, 32, 4);
    words = words * 4;
    var constants = bc_read(data, 36, 4);
    constants = constants * 8;
    var total = source + words;
    total = total + constants;
    total = total + 56;
    invalid = total != convert(u64, length);
    if invalid {
        return 1;
    }
    invalid = bc_read(data, 40, 4) != total;
    if invalid {
        return 1;
    }
    var checksum = bc_checksum(data, length);
    invalid = bc_read(data, 48, 8) != checksum;
    if invalid {
        return 8;
    }
    return 0;
}

export fn bytecode_error(code: u32): u8* {
    var selected = code == 1;
    if selected {
        return "Invalid .towerbc length or section bounds";
    }
    selected = code == 2;
    if selected {
        return "Invalid .towerbc magic";
    }
    selected = code == 3;
    if selected {
        return "Unsupported .towerbc container version";
    }
    selected = code == 4;
    if selected {
        return "Unsupported .towerbc semantics version";
    }
    selected = code == 5;
    if selected {
        return "Unsupported .towerbc cache version";
    }
    selected = code == 6;
    if selected {
        return "Unsupported .towerbc target layout";
    }
    selected = code == 7;
    if selected {
        return "Unsupported .towerbc optimization profile or flags";
    }
    selected = code == 8;
    if selected {
        return ".towerbc checksum mismatch";
    }
    return ".towerbc cache disagrees with checked Foundation";
}

export fn bytecode_source_size(data: u8*): usize {
    return convert(usize, bc_read(data, 28, 4));
}

export fn bytecode_pointer_bytes(data: u8*): usize {
    return convert(usize, bc_read(data, 20, 4));
}

export fn bytecode_encode(f: FMState*, source: u8*, source_size: usize, width: usize, profile: u32, length: usize*): u8* {
    var invalid_profile = profile > 2;
    if invalid_profile {
        return null;
    }
    var words = f.words.length * 4;
    var constants = f.constants.length * 8;
    var total = source_size + words;
    total = total + constants;
    total = total + 56;
    var invalid = source_size > 8388608;
    var large = total > 268435456;
    invalid = im_or(invalid, large);
    if invalid {
        *length = 0;
        return null;
    }
    var data = alloc(u8, total);
    var failed = data == null;
    if failed {
        *length = 0;
        return null;
    }
    fill(data, 0, 56);
    copy(data, "TOWERBC", 8);
    bc_write(data, 8, 1, 4);
    bc_write(data, 12, 2, 4);
    bc_write(data, 16, 2, 4);
    bc_write(data, 20, convert(u64, width), 4);
    bc_write(data, 24, convert(u64, profile), 4);
    bc_write(data, 28, convert(u64, source_size), 4);
    bc_write(data, 32, convert(u64, f.words.length), 4);
    bc_write(data, 36, convert(u64, f.constants.length), 4);
    bc_write(data, 40, convert(u64, total), 4);
    copy(&data[56], source, source_size);
    var at = source_size + 56;
    var i: usize = 0;
    loop {
        var end = i == f.words.length;
        if end {
            break;
        }
        bc_write(data, at, convert(u64, f.words.data[i]), 4);
        at = at + 4;
        i = i + 1;
    }
    i = 0;
    loop {
        var end = i == f.constants.length;
        if end {
            break;
        }
        bc_write(data, at, f.constants.data[i], 8);
        at = at + 8;
        i = i + 1;
    }
    bc_write(data, 48, bc_checksum(data, total), 8);
    *length = total;
    return data;
}

export fn bytecode_free(data: u8*): void {
    free(data);
}

export fn bytecode_matches(f: FMState*, data: u8*): bool {
    var different = bc_read(data, 32, 4) != convert(u64, f.words.length);
    if different {
        return false;
    }
    different = bc_read(data, 36, 4) != convert(u64, f.constants.length);
    if different {
        return false;
    }
    var at = bytecode_source_size(data);
    at = at + 56;
    var i: usize = 0;
    loop {
        var end = i == f.words.length;
        if end {
            break;
        }
        different = bc_read(data, at, 4) != convert(u64, f.words.data[i]);
        if different {
            return false;
        }
        at = at + 4;
        i = i + 1;
    }
    i = 0;
    loop {
        var end = i == f.constants.length;
        if end {
            return true;
        }
        different = bc_read(data, at, 8) != f.constants.data[i];
        if different {
            return false;
        }
        at = at + 8;
        i = i + 1;
    }
}

import tower;

// Editor queries over the compiler's shared syntax entities. Recovery text is
// scratch input to the ordinary parser, never a second AST or program format.
// Candidate lists retain borrowed entity handles only for the duration of a query.
struct CompletionSpan {
    start: usize;
    end: usize;
    opaque: bool;
}

struct CompletionQuery {
    active: void*;
    program: SemanticProgram;
    context: SemanticContext;
    editor: SemanticEditor;
    semantic: bool;
    analyzed: bool;
    inspection: bool;
    truncated: bool;
    input: vector(u8);
    roots: vector(void*);
    bases: vector(usize);
    source: u8*;
    length: usize;
    cursor: usize;
    from: usize;
    to: usize;
    boundary: usize;
    mode: u32;
    hidden: bool;
    recovered: vector(u8);
    names: vector(u8*);
    bindings: vector(u8*);
    output: vector(u8);
    count: usize;
}

extern fn syntax_completion_create(source: u8*, mode: u32): void*;

extern fn syntax_destroy(session: void*): void;

extern fn syntax_completion_module(session: void*): void*;

extern fn syntax_completion_enable(session: void*): void;

extern fn syntax_completion_accepts(session: void*, text: u8*, literal: bool): bool;

extern fn syntax_completion_callable(session: void*): bool;

extern fn syntax_completion_identifier(session: void*, text: u8*): bool;

extern fn syntax_completion_close(session: void*, type_name: u8*): u8*;

export fn completion_from(q: CompletionQuery*): usize {
    return q.from;
}

fn completion_attach(q: CompletionQuery*, root: void*, base: usize): void {
    var node = sem_child(root, 0);
    if sem_is(node, "Statement") {
        node = sem_unwrap(node);
    }
    sem_require(entity_attach(root, q.program.root, ""));
    var target = sem_get(q.program.root);
    sem_push(&target.items, node);
    sem_push(&q.roots, root);
    sem_require(vector_push(usize, &q.bases, base));
}

fn completion_parse(q: CompletionQuery*, source: u8*, mode: u32, future: bool): bool {
    var base = q.input.length;
    var length = sem_length(source);
    sem_require(bytes_append(&q.input, source, length));
    sem_require(vector_push(u8, &q.input, 10));
    var session = syntax_completion_create(source, mode);
    var entries: vector(void*);
    vector_init(void*, &entries);
    var count: usize = 0;
    loop {
        var editor_condition1 = count == 1024;
        if editor_condition1 {
            q.truncated = true;
            break;
        }
        var revision = syntax_get_revision(session);
        var root = syntax_next(session);
        var editor_condition2 = root == null;
        if editor_condition2 {
            break;
        }
        var keep = revision == syntax_get_revision(session);
        if future {
            var span = sem_match(root);
            var editor_condition3 = span.start < q.cursor;
            if editor_condition3 {
                keep = false;
            }
        }
        if keep {
            sem_push(&entries, root);
        } else {
            if q.inspection {
                // Keep grammar entities for inspection without adding them to
                // the executable statement list consumed by ordinary checking.
                sem_require(entity_attach(root, q.program.root, ""));
                sem_push(&q.roots, root);
                sem_require(vector_push(usize, &q.bases, base));
            }
            entity_release(root);
        }
        count = count + 1;
    }
    var error = syntax_get_error(session);
    var clean = error[0] == 0;
    // Only the entry's actual import closure contributes external declarations.
    // These are fresh ordinary module entities, retained before session teardown.
    if future {} else {
        var module = syntax_completion_module(session);
        var present = module != null;
        if present {
            var i: usize = 0;
            var total = frontend_module_count(module);
            loop {
                var done = i == total;
                if done {
                    break;
                }
                var dependency = frontend_module_at(module, i);
                var imported = dependency != module;
                if imported {
                    var dependency_base = q.input.length;
                    var data = frontend_module_source(dependency);
                    var bytes = frontend_module_size(dependency);
                    sem_require(bytes_append(&q.input, data, bytes));
                    sem_require(vector_push(u8, &q.input, 10));
                    var n: usize = 0;
                    var trees = frontend_module_roots(dependency);
                    loop {
                        done = n == trees;
                        if done {
                            break;
                        }
                        completion_attach(q, frontend_module_tree(dependency, n), dependency_base);
                        n = n + 1;
                    }
                }
                i = i + 1;
            }
        }
    }
    var i: usize = 0;
    loop {
        var done = i == entries.length;
        if done {
            break;
        }
        completion_attach(q, entries.data[i], base);
        entity_release(entries.data[i]);
        i = i + 1;
    }
    vector_dispose(void*, &entries);
    syntax_destroy(session);
    return clean;
}

export fn completion_analyze(q: CompletionQuery*, active: void*, mode: u32, files: u8**, lengths: usize*, count: usize): void {
    q.active = active;
    if q.hidden {
        return;
    }
    var editor_condition4 = mode != 0;
    if editor_condition4 {
        return;
    }
    var editor_condition5 = q.mode == 2;
    if editor_condition5 {
        return;
    }
    // Select a concrete identifier through the current lexer. Its coordinates,
    // not its spelling, mark the query, including under local token overrides.
    var hole: vector(u8);
    vector_init(u8, &hole);
    var prefix_length = q.cursor - q.from;
    var preferred = &q.source[q.from];
    sem_require(bytes_append(&hole, preferred, prefix_length));
    sem_require(host_text_terminate(&hole));
    var attempt: usize = 0;
    loop {
        if syntax_completion_identifier(active, hole.data) {
            break;
        }
        var editor_check_1 = attempt == 6;
        if editor_check_1 {
            vector_dispose(u8, &hole);
            return;
        }
        var spelling: u8* = "a";
        var editor_check_2 = attempt == 1;
        if editor_check_2 {
            spelling = "A";
        }
        var editor_check_3 = attempt == 2;
        if editor_check_3 {
            spelling = "aa";
        }
        var editor_check_4 = attempt == 3;
        if editor_check_4 {
            spelling = "AA";
        }
        var editor_check_5 = attempt == 4;
        if editor_check_5 {
            spelling = "_";
        }
        var editor_check_6 = attempt == 5;
        if editor_check_6 {
            spelling = "`a`";
        }
        hole.length = 0;
        completion_text(&hole, spelling);
        sem_require(host_text_terminate(&hole));
        attempt = attempt + 1;
    }
    q.editor.length = hole.length;
    var text: vector(u8);
    vector_init(u8, &text);
    sem_require(bytes_append(&text, q.source, q.from));
    completion_text(&text, hole.data);
    vector_dispose(u8, &hole);
    var prefix_end = text.length;
    var suffix_length = q.length - q.to;
    sem_require(bytes_append(&text, &q.source[q.to], suffix_length));
    sem_require(host_text_terminate(&text));
    var root = tower_node_create();
    semantic_initialize(&q.program, root, 4);
    q.semantic = true;
    var valid = completion_parse(q, text.data, mode, false);
    // Prefer the actual suffix, so later operands and declarations participate
    // in resolution. Fall back to a bounded LR continuation for incomplete edits.
    if valid {} else {
        semantic_program_dispose(&q.program);
        entity_release(root);
        root = tower_node_create();
        semantic_initialize(&q.program, root, 4);
        q.roots.length = 0;
        q.bases.length = 0;
        q.input.length = 0;
        text.length = prefix_end;
        sem_require(host_text_terminate(&text));
        var probe = syntax_completion_create(text.data, mode);
        syntax_completion_enable(probe);
        var i: usize = 0;
        loop {
            var editor_condition6 = i == 1024;
            if editor_condition6 {
                break;
            }
            var root = syntax_next(probe);
            var editor_condition7 = root == null;
            if editor_condition7 {
                break;
            }
            entity_release(root);
            i = i + 1;
        }
        var suffix = syntax_completion_close(probe, semantic_scalar_name(SVoid()));
        var editor_condition8 = suffix == null;
        if editor_condition8 {
            syntax_destroy(probe);
            vector_dispose(u8, &text);
            return;
        }
        // host_text_terminate writes beyond length; append replaces that terminator.
        completion_text(&text, suffix);
        sem_require(host_text_terminate(&text));
        syntax_destroy(probe);
        valid = completion_parse(q, text.data, mode, false);
        if valid {} else {
            vector_dispose(u8, &text);
            return;
        }
        completion_parse(q, q.recovered.data, mode, true);
    }
    vector_dispose(u8, &text);
    var i: usize = 0;
    sem_require(host_text_terminate(&q.input));
    var c = &q.context;
    sem_context_init(c, &q.program);
    q.analyzed = true;
    c.source = q.input.data;
    c.editor = &q.editor;
    q.editor.offset = q.from;
    c.generics = generic_begin(root);
    i = 0;
    loop {
        var editor_condition10 = i == q.roots.length;
        if editor_condition10 {
            break;
        }
        var entry = sem_state(c, c.source_bases, q.roots.data[i]);
        entry.number = q.bases.data[i];
        i = i + 1;
    }
    sem_run(c);
    // Observed scope tables borrow real entities and remain valid until dispose.
    if q.editor.found {
        c.scope = q.editor.scope;
    }
    c.editor = null;
    q.program.error.length = 0;
}

extern fn host_json_quote(out: vector(u8)*, source: u8*, count: usize): bool;

extern fn host_json_unsigned(out: vector(u8)*, value: u64): bool;

extern fn host_text_terminate(out: vector(u8)*): bool;

fn completion_word(byte: u8): bool {
    var yes = byte >= 65;
    if yes {
        yes = byte <= 90;
    }
    if yes {
        return true;
    }
    yes = byte >= 97;
    if yes {
        yes = byte <= 122;
    }
    if yes {
        return true;
    }
    yes = byte >= 48;
    if yes {
        yes = byte <= 57;
    }
    if yes {
        return true;
    }
    var underscore = byte == 95;
    return underscore;
}

fn completion_slice(source: u8*, start: usize, end: usize, word: u8*): bool {
    var size = end - start;
    var same = size == sem_length(word);
    if same {} else {
        return false;
    }
    var i: usize = 0;
    loop {
        var done = i == size;
        if done {
            return true;
        }
