    frontend_bedrock_alternative(&b);
    frontend_bedrock_term(&b, b.alternative, "import", "", true);
    frontend_bedrock_term(&b, b.alternative, "ImportPath", "name", false);
    frontend_bedrock_term(&b, b.alternative, ";", "", true);
    frontend_bedrock_alternative(&b);
    frontend_bedrock_term(&b, b.alternative, "import", "", true);
    frontend_bedrock_term(&b, b.alternative, "String", "name", false);
    frontend_bedrock_term(&b, b.alternative, ";", "", true);

    frontend_table_dispose(&b.patterns);
    if b.failed {
        var present = b.document != null;
        if present {
            entity_release(b.document);
        }
        return null;
    }
    return b.document;
}

import tower;

// Immutable revision snapshots retain shared grammar entities. Cache slots are
// disposable host handles; no parser semantics or source is encoded in them.
struct FrontendRevision {
    references: usize;
    slot: usize;
    rules: vector(SyntaxRuleView);
    names: vector(u8);
    alternatives: vector(void*);
    tokens: vector(void*);
}

struct FrontendCache {
    entries: vector(FrontendRevision*);
    builds: usize;
    hits: usize;
}

fn frontend_revision_release(revision: FrontendRevision*): void {
    var missing = revision == null;
    if missing {
        return;
    }
    revision.references = revision.references - 1;
    var retained = revision.references != 0;
    if retained {
        return;
    }
    var i: usize = 0;
    loop {
        var done = i == revision.alternatives.length;
        if done {
            break;
        }
        entity_release(revision.alternatives.data[i]);
        i = i + 1;
    }
    i = 0;
    loop {
        var done = i == revision.tokens.length;
        if done {
            break;
        }
        entity_release(revision.tokens.data[i]);
        i = i + 1;
    }
    vector_dispose(SyntaxRuleView, &revision.rules);
    vector_dispose(u8, &revision.names);
    vector_dispose(void*, &revision.alternatives);
    vector_dispose(void*, &revision.tokens);
    free(revision);
}

fn frontend_revision_nodes(target: vector(void*)*, nodes: void**, count: usize): bool {
    var needed = target.length + count;
    var overflow = needed < target.length;
    if overflow {
        return false;
    }
    var ok = vector_reserve(void*, target, needed);
    if ok {} else {
        return false;
    }
    var i: usize = 0;
    loop {
        var done = i == count;
        if done {
            return true;
        }
        entity_retain(nodes[i]);
        target.data[target.length] = nodes[i];
        target.length = target.length + 1;
        i = i + 1;
    }
}

fn frontend_revision_create(rules: SyntaxRuleView*, count: usize, tokens: void**, token_count: usize): FrontendRevision* {
    var revision = alloc(FrontendRevision, 1);
    var missing = revision == null;
    if missing {
        return null;
    }
    fill(revision, 0, sizeof(FrontendRevision));
    revision.references = 1;
    // One names buffer and one retained-alternative buffer for the revision.
    // Rule views borrow these stable allocations; nothing grows after linking.
    var names: usize = 0;
    var alternatives: usize = 0;
    var ok: bool = true;
    var i: usize = 0;
    loop {
        var done = i == count;
        if done {
            break;
        }
        var next = names + rules[i].name_length;
        var overflow = next < names;
        var full = next == lr_none();
        if full {
            overflow = true;
        }
        if overflow {
            ok = false;
            break;
        }
        names = next + 1;
        next = alternatives + rules[i].count;
        overflow = next < alternatives;
        if overflow {
            ok = false;
            break;
        }
        alternatives = next;
        i = i + 1;
    }
    if ok {
        ok = vector_reserve(SyntaxRuleView, &revision.rules, count);
    }
    if ok {
        ok = vector_reserve(u8, &revision.names, names);
    }
    if ok {
        ok = vector_reserve(void*, &revision.alternatives, alternatives);
    }
    i = 0;
    loop {
        if ok {} else {
            break;
        }
        var done = i == count;
        if done {
            break;
        }
        var target = &revision.rules.data[i];
        target.name = &revision.names.data[revision.names.length];
        target.name_length = rules[i].name_length;
        target.count = rules[i].count;
        target.alternatives = null;
        var populated = target.count != 0;
        if populated {
            target.alternatives = &revision.alternatives.data[revision.alternatives.length];
        }
        ok = bytes_append(&revision.names, rules[i].name, rules[i].name_length);
        if ok {
            ok = vector_push(u8, &revision.names, 0);
        }
        if ok {
            ok = frontend_revision_nodes(&revision.alternatives, rules[i].alternatives, rules[i].count);
        }
        revision.rules.length = revision.rules.length + 1;
        i = i + 1;
    }
    if ok {
        ok = frontend_revision_nodes(&revision.tokens, tokens, token_count);
    }
    if ok {
        return revision;
    }
    frontend_revision_release(revision);
    return null;
}

fn frontend_revision_same(revision: FrontendRevision*, rules: SyntaxRuleView*, count: usize,
tokens: void**, token_count: usize, kind: void*): bool {
    var different = revision.rules.length != count;
    if different {
        return false;
    }
    different = revision.tokens.length != token_count;
    if different {
        return false;
    }
    var i: usize = 0;
    loop {
        var done = i == count;
        if done {
            break;
        }
        var previous = &revision.rules.data[i];
        var next = &rules[i];
        var order = syntax_bytes_compare(previous.name, previous.name_length, next.name, next.name_length);
        different = order != 0;
        if different {
            return false;
        }
        different = previous.count != next.count;
        if different {
            return false;
        }
        var j: usize = 0;
        loop {
            done = j == next.count;
            if done {
                break;
            }
            var same = syntax_nodes_equal(previous.alternatives[j], next.alternatives[j], kind, true);
            different = same != 1;
            if different {
                return false;
            }
            j = j + 1;
        }
        i = i + 1;
    }
    i = 0;
    loop {
        var done = i == token_count;
        if done {
            return true;
        }
        var same = syntax_nodes_equal(revision.tokens.data[i], tokens[i], kind, true);
        different = same != 1;
        if different {
            return false;
        }
        i = i + 1;
    }
}

export fn frontend_cache_dispose(cache: FrontendCache*): void {
    var i: usize = 0;
    loop {
        var done = i == cache.entries.length;
        if done {
            break;
        }
        frontend_revision_release(cache.entries.data[i]);
        i = i + 1;
    }
    vector_dispose(FrontendRevision*, &cache.entries);
    cache.builds = 0;
    cache.hits = 0;
}

// Destination must be empty. Formatting forks share immutable snapshots but
// keep independent recency, counters and compiled-table handle ownership.
export fn frontend_cache_copy(target: FrontendCache*, source: FrontendCache*): bool {
    var count = source.entries.length;
    var ok = vector_reserve(FrontendRevision*, &target.entries, count);
    if ok {} else {
        return false;
    }
    var i: usize = 0;
    loop {
        var done = i == count;
        if done {
            break;
        }
        var revision = source.entries.data[i];
        revision.references = revision.references + 1;
        target.entries.data[i] = revision;
        i = i + 1;
    }
    target.entries.length = count;
    target.builds = source.builds;
    target.hits = source.hits;
    return true;
}

fn frontend_cache_touch(cache: FrontendCache*, index: usize): void {
    var entry = cache.entries.data[index];
    var last = cache.entries.length - 1;
    loop {
        var done = index == last;
        if done {
            break;
        }
        var next = index + 1;
        cache.entries.data[index] = cache.entries.data[next];
        index = next;
    }
    cache.entries.data[last] = entry;
}

export fn frontend_cache_find(cache: FrontendCache*, rules: SyntaxRuleView*, count: usize,
tokens: void**, token_count: usize, kind: void*): usize {
    var i: usize = 0;
    loop {
        var done = i == cache.entries.length;
        if done {
            cache.builds = cache.builds + 1;
            return lr_none();
        }
        var revision = cache.entries.data[i];
        var same = frontend_revision_same(revision, rules, count, tokens, token_count, kind);
        if same {
            frontend_cache_touch(cache, i);
            cache.hits = cache.hits + 1;
            return revision.slot;
        }
        i = i + 1;
    }
}

// Store only after successful table construction. Allocation failure leaves
// every previous entry and slot unchanged; caching is optional for correctness.
export fn frontend_cache_store(cache: FrontendCache*, rules: SyntaxRuleView*, count: usize,
tokens: void**, token_count: usize): usize {
    var revision = frontend_revision_create(rules, count, tokens, token_count);
    var missing = revision == null;
    if missing {
        return lr_none();
    }
    var full = cache.entries.length == 64;
    if full {
        revision.slot = cache.entries.data[0].slot;
        frontend_revision_release(cache.entries.data[0]);
        cache.entries.data[0] = revision;
        frontend_cache_touch(cache, 0);
    } else {
        revision.slot = cache.entries.length;
        var ok = vector_push(FrontendRevision*, &cache.entries, revision);
        if ok {} else {
            frontend_revision_release(revision);
            return lr_none();
        }
    }
    return revision.slot;
}

export fn frontend_cache_pattern(cache: FrontendCache*, entity: void*, kind: void*): void {
    var component = entity_component_get(entity, kind);
    var node = bits(SyntaxNode*, entity_component_data(component));
    var i = cache.entries.length;
    loop {
        var done = i == 0;
        if done {
            return;
        }
        i = i - 1;
        var revision = cache.entries.data[i];
        var j: usize = 0;
        loop {
            done = j == revision.tokens.length;
            if done {
                break;
            }
            component = entity_component_get(revision.tokens.data[j], kind);
            var previous = bits(SyntaxNode*, entity_component_data(component));
            var same = syntax_text_equal(&node.text, &previous.text);
            if same {
                syntax_node_pattern(node, previous.compiled);
                return;
            }
            j = j + 1;
        }
    }
}

import tower;

// Source/module orchestration over the same semantic program and parse entities.
// Composed with the semantic declarations; no copied Foundation operation model.
extern fn frontend_module_session(module: void*): void*;

extern fn syntax_next(session: void*): void*;

extern fn syntax_get_error(session: void*): u8*;

extern fn syntax_get_revision(session: void*): usize;

extern fn syntax_get_error_offset(session: void*): usize;

extern fn bytes_append(target: vector(u8)*, data: u8*, count: usize): bool;

struct FrontendSource {
    data: u8*;
    length: usize;
}

fn frontend_source_length(source: u8*): usize {
    var length: usize = 0;
    loop {
        var done = source[length] == 0;
        if done {
            return length;
        }
        length = length + 1;
    }
}

fn frontend_compile_error(program: SemanticProgram*, message: u8*): void {
    var length = frontend_source_length(message);
    sem_require(bytes_append(&program.error, message, length));
}

extern fn frontend_module_root(source: u8*, environment: void*): void*;

extern fn frontend_module_finish(module: void*): void;

extern fn frontend_module_count(module: void*): usize;

extern fn frontend_module_at(module: void*, index: usize): void*;

extern fn frontend_module_source(module: void*): u8*;

extern fn frontend_module_size(module: void*): usize;

extern fn frontend_module_roots(module: void*): usize;

extern fn frontend_module_tree(module: void*, index: usize): void*;

extern fn frontend_module_destroy(module: void*): void;

extern fn frontend_module_position(module: void*, base: usize): void;

extern fn frontend_module_diagnostic(module: void*, offset: usize): void;

export fn frontend_compile_sources(program: SemanticProgram*, sources: FrontendSource*, count: usize, environment: void*): void {
    var source: vector(u8);
    var roots: vector(void*);
    var bases: vector(usize);
    var modules: vector(void*);
    vector_init(u8, &source);
    vector_init(void*, &roots);
    vector_init(usize, &bases);
    vector_init(void*, &modules);
    var index: usize = 0;
    loop {
        var done = index == count;
        if done {
            break;
        }
        var module = frontend_module_root(sources[index].data, environment);
        sem_require(vector_push(void*, &modules, module));
        var session = frontend_module_session(module);
        loop {
            var root = syntax_next(session);
            var finished = root == null;
            if finished {
                break;
            }
            entity_release(root);
        }
        var error = syntax_get_error(session);
        var failed = error[0] != 0;
        if failed {
            frontend_compile_error(program, error);
            program.error_offset = syntax_get_error_offset(session);
            frontend_module_diagnostic(module, program.error_offset);
        }
        if failed {
            break;
        }
        frontend_module_finish(module);
        var dependency: usize = 0;
        var dependencies = frontend_module_count(module);
        loop {
            done = dependency == dependencies;
            if done {
                break;
            }
            var current = frontend_module_at(module, dependency);
            var base = source.length;
            frontend_module_position(current, base);
            var data = frontend_module_source(current);
            var length = frontend_module_size(current);
            sem_require(bytes_append(&source, data, length));
            sem_require(vector_push(u8, &source, 10));
            var n: usize = 0;
            var trees = frontend_module_roots(current);
            loop {
                done = n == trees;
                if done {
                    break;
                }
                var root = frontend_module_tree(current, n);
                var node = sem_child(root, 0);
                var statement = sem_is(node, "Statement");
                if statement {
                    statement = sem_child_count(node) == 1;
                    if statement {
                        node = sem_child(node, 0);
                    }
                }
                sem_require(entity_attach(root, program.root, ""));
                var target = sem_get(program.root);
                sem_require(vector_push(void*, &target.items, node));
                sem_require(vector_push(void*, &roots, root));
                sem_require(vector_push(usize, &bases, base));
                n = n + 1;
            }
            dependency = dependency + 1;
        }
        index = index + 1;
    }
    sem_require(vector_push(u8, &source, 0));
    var ok = program.error.length == 0;
    if ok {
        semantic_compile(program, roots.data, bases.data, roots.length, source.data);
    }
    index = 0;
    loop {
        var done = index == modules.length;
        if done {
            break;
        }
        frontend_module_destroy(modules.data[index]);
        index = index + 1;
    }
    vector_dispose(void*, &modules);
    vector_dispose(u8, &source);
    vector_dispose(void*, &roots);
    vector_dispose(usize, &bases);
}

import tower;

// Error-only bounded lookahead correction. This pull protocol borrows numeric
// LR frames; it never copies parse trees or rewinds the real source stream.
struct FrontendRulePosition {
    production: usize;
    term: usize;
}

struct FrontendContextPosition {
    production: usize;
    term: usize;
    first: u32;
    last: u32;
    terminal: bool;
}

struct FrontendExpectation {
    id: u32;
    insertion: bool;
    completes: bool;
    contexts: vector(FrontendRulePosition);
}

struct FrontendDiagnostic {
    runtime: LRRuntime*;
    budget: LRProbeBudget;
    original: LRProbe*;
    stack: LRProbe*;
    continuation: LRProbe*;
    candidates: u32[64];
    count: usize;
    index: usize;
    current: FrontendExpectation;
    options: vector(FrontendExpectation);
    phase: u32;
    accepted: u32;
    state: usize;
    offset: usize;
    position: usize;
    ahead: usize;
    lookahead: u32;
    prefix: bool;
    reader: bool;
    bad_input: bool;
    complete: bool;
    done: bool;
}

export fn frontend_diagnostic_destroy(d: FrontendDiagnostic*): void {
    var absent = d == null;
    if absent {
        return;
    }
    lr_probe_destroy(d.original);
    lr_probe_destroy(d.stack);
    lr_probe_destroy(d.continuation);
    vector_dispose(FrontendRulePosition, &d.current.contexts);
    var i: usize = 0;
    loop {
        var done = i == d.options.length;
        if done {
            break;
        }
        vector_dispose(FrontendRulePosition, &d.options.data[i].contexts);
        i = i + 1;
    }
    vector_dispose(FrontendExpectation, &d.options);
    free(d);
}

export fn frontend_diagnostic_create(parser: LRParser*, prefix: bool,
reader: bool, bad_input: bool, lookahead: u32, offset: usize): FrontendDiagnostic* {
    var d = alloc(FrontendDiagnostic, 1);
    var missing = d == null;
    if missing {
        return null;
    }
    fill(d, 0, sizeof(FrontendDiagnostic));
    d.runtime = parser.runtime;
    d.prefix = prefix;
    d.reader = reader;
    d.bad_input = bad_input;
    d.lookahead = lookahead;
    d.offset = offset;
    d.complete = true;
    d.budget.remaining = 8192;
    d.budget.complete = true;
    var count = lr_parser_frame_count(parser);
    var invalid = count == 0;
    var too_deep = count > 4096;
    if too_deep {
        invalid = true;
    }
    if invalid {
        d.done = true;
        return d;
    }
    d.original = lr_probe_create(parser, &d.budget);
    missing = d.original == null;
    if missing {
        d.complete = false;
        d.done = true;
        return d;
    }
    var frames = lr_probe_frames(d.original);
    var last = count - 1;
    var state = frames[last].state;
    var actions = lr_runtime_actions(d.runtime, state);
    d.count = lr_runtime_action_count(d.runtime, state);
    var truncated = d.count > 64;
    if truncated {
        d.count = 64;
        d.complete = false;
    }
    // Runtime rows are already sorted by first terminal ID. No extra sort or
    // unbounded candidate allocation is necessary on an error path.
    var i: usize = 0;
    loop {
        var done = i == d.count;
        if done {
            break;
        }
        d.candidates[i] = actions[i].first;
        i = i + 1;
    }
    return d;
}

fn frontend_diagnostic_consume(d: FrontendDiagnostic*, id: u32): u32 {
    var previous = lr_probe_clone(d.continuation);
    var missing = previous == null;
    if missing {
        return 0;
    }
    var before: usize;
    var status = lr_probe_step(d.continuation, id, &before);
    var boundary = d.prefix;
    var ordinary = id != 4294967294;
    if ordinary {} else {
        boundary = false;
    }
    if boundary {
        var accepted = status == 2;
        var rejected = status == 0;
        if rejected {
            var ending = lr_probe_step(previous, 4294967294, &before);
            accepted = ending == 2;
        }
        if accepted {
            lr_probe_reset(d.continuation);
            status = lr_probe_step(d.continuation, id, &before);
        }
    }
    lr_probe_destroy(previous);
    return status;
}

// Called only for the state preceding a hypothetical expected terminal. The
// positions are the table's ordered derived LR items, never user intent guesses.
export fn frontend_diagnostic_contexts(d: FrontendDiagnostic*, items: FrontendContextPosition*, count: usize): void {
    var frames = lr_probe_frames(d.stack);
    var frame_count = lr_probe_count(d.stack);
    var i: usize = 0;
    loop {
        var done = i == count;
        if done {
            break;
        }
        var item = &items[i];
        var active = item.term != 0;
        var last = frame_count - 1;
        var within = item.term < last;
        if within {} else {
            active = false;
        }
        if active {
            var begin = last - item.term;
            var position = begin;
            var consumed: bool = false;
            loop {
                done = position == last;
                if done {
                    break;
                }
                if frames[position].consumed {
                    consumed = true;
                    break;
                }
                position = position + 1;
            }
            var rule = &d.runtime.rules.data[item.production];
            active = consumed;
            within = item.term < rule.count;
            if within {} else {
                active = false;
            }
            if active {
                active = item.terminal;
                within = d.current.id >= item.first;
                if within {} else {
                    active = false;
                }
                within = d.current.id <= item.last;
                if within {} else {
                    active = false;
                }
                if active {
                    var context: FrontendRulePosition;
                    context.production = item.production;
                    context.term = item.term;
                    var ok = lr_append(FrontendRulePosition, &d.current.contexts, &context);
                    if ok {} else {
                        d.complete = false;
                        d.done = true;
                        return;
                    }
                }
            }
        }
        i = i + 1;
    }
    d.phase = 2;
}

export fn frontend_diagnostic_feed(d: FrontendDiagnostic*, valid: bool, position: usize, id: u32): void {
    d.position = position;
    if valid {} else {
        d.current.insertion = false;
        d.complete = false;
        d.phase = 4;
        return;
    }
    var status = frontend_diagnostic_consume(d, id);
    d.current.insertion = status != 0;
    d.ahead = d.ahead + 1;
    var eof = id == 4294967294;
    if eof {
        d.phase = 4;
    }
}

// 0 finished; 1 requests table item positions; 2 requests a contextual lexer
// lookahead. Hosts only supply borrowed data and input, not repair decisions.
export fn frontend_diagnostic_next(d: FrontendDiagnostic*): u32 {
    loop {
        if d.done {
            return 0;
        }
        var begin = d.phase == 0;
        if begin {
            var finished = d.index == d.count;
            if finished {
                d.done = true;
                return 0;
            }
            d.stack = lr_probe_clone(d.original);
            var missing = d.stack == null;
            if missing {
                d.complete = false;
                d.done = true;
                return 0;
            }
            d.current.id = d.candidates[d.index];
            d.index = d.index + 1;
            d.state = lr_none();
            d.accepted = lr_probe_step(d.stack, d.current.id, &d.state);
            var rejected = d.accepted == 0;
            if rejected {
                lr_probe_destroy(d.stack);
                d.stack = null;
                continue;
            }
            d.phase = 2;
            var context = d.state != lr_none();
            if context {
                d.phase = 1;
                return 1;
            }
        }
        var contexts = d.phase == 1;
        if contexts {
            return 1;
        }
        begin = d.phase == 2;
        if begin {
            d.phase = 4;
            var can_insert = d.accepted == 1;
            var ordinary = d.current.id != 4294967294;
            if ordinary {} else {
                can_insert = false;
            }
            if d.reader {} else {
                if d.bad_input {
                    can_insert = false;
                }
            }
            if can_insert {
                d.continuation = lr_probe_clone(d.stack);
                d.current.insertion = d.continuation != null;
                d.position = d.offset;
                d.ahead = 0;
                if d.current.insertion {
                    if d.reader {
                        d.phase = 3;
                    } else {
                        var status = frontend_diagnostic_consume(d, d.lookahead);
                        d.current.insertion = status != 0;
                    }
                }
            }
        }
        var reading = d.phase == 3;
        if reading {
            var more = d.ahead < 3;
            if d.current.insertion {} else {
                more = false;
            }
            if more {
                var frames = lr_probe_frames(d.continuation);
                var last = lr_probe_count(d.continuation);
                last = last - 1;
                d.state = frames[last].state;
                return 2;
            }
            d.phase = 4;
        }
        var finish = d.phase == 4;
        if finish {
            var boundary = d.current.insertion;
            if d.prefix {} else {
                boundary = false;
            }
            if boundary {
                var end = lr_probe_clone(d.stack);
                var exists = end != null;
                if exists {
                    var before: usize;
                    var status = lr_probe_step(end, 4294967294, &before);
                    d.current.completes = status == 2;
                }
                lr_probe_destroy(end);
            }
            var ok = lr_append(FrontendExpectation, &d.options, &d.current);
            if ok {} else {
                d.complete = false;
                d.done = true;
                return 0;
            }
            fill(&d.current, 0, sizeof(FrontendExpectation));
            lr_probe_destroy(d.stack);
            lr_probe_destroy(d.continuation);
            d.stack = null;
            d.continuation = null;
            d.phase = 0;
        }
    }
}

