        var lower = letter >= 97;
        if lower {
            lower = letter <= 122;
        }
        if lower {
            letter = letter - 32;
        }
        var valid = letter >= 65;
        if valid {
            valid = letter <= 90;
        }
        if valid {} else {
            vector_dispose(usize, &parts);
            return false;
        }
        module_require(vector_push(u8, result, letter));
        module_require(bytes_append(result, ":/", 2));
        absolute = true;
        i = 3;
    }
    loop {
        var byte = path[i];
        var done = byte == 0;
        if done {
            break;
        }
        var separator = byte == 47;
        if separator {} else {
            separator = byte == 92;
        }
        if separator {
            i = i + 1;
            continue;
        }
        var start = i;
        loop {
            byte = path[i];
            done = byte == 0;
            if done {
                break;
            }
            separator = byte == 47;
            if separator {} else {
                separator = byte == 92;
            }
            if separator {
                break;
            }
            i = i + 1;
        }
        var length = i - start;
        var dot = length == 1;
        if dot {
            dot = path[start] == 46;
        }
        if dot {
            continue;
        }
        var parent = length == 2;
        if parent {
            parent = path[start] == 46;
        }
        if parent {
            var next = start + 1;
            parent = path[next] == 46;
        }
        var can_pop = parts.length > protected_parts;
        if parent {
            if can_pop {
                var last = parts.length - 1;
                var offset = parts.data[last];
                var check = offset;
                var slash = result.data[check] == 47;
                if slash {
                    check = check + 1;
                }
                var previous_length = result.length - check;
                var previous_parent = previous_length == 2;
                if previous_parent {
                    previous_parent = result.data[check] == 46;
                }
                if previous_parent {
                    check = check + 1;
                    previous_parent = result.data[check] == 46;
                }
                can_pop = previous_parent == false;
                if can_pop {
                    result.length = offset;
                    parts.length = last;
                    continue;
                }
            }
            if absolute {
                vector_dispose(usize, &parts);
                return false;
            }
        }
        module_require(vector_push(usize, &parts, result.length));
        var nonempty = result.length != 0;
        if nonempty {
            var last = result.length - 1;
            var slash = result.data[last] == 47;
            if slash {} else {
                module_require(vector_push(u8, result, 47));
            }
        }
        var segment = path + start;
        module_require(bytes_append(result, segment, length));
    }
    var complete = parts.length >= protected_parts;
    vector_dispose(usize, &parts);
    if complete {} else {
        return false;
    }
    module_require(vector_push(u8, result, 0));
    result.length = result.length - 1;
    return true;
}

fn module_directory(path: u8*, result: vector(u8)*): void {
    module_require(module_path(path, result));
    // A configured relative root is a search directory, even though its
