            directory = module_text(&parent.graph.environment.fallback);
        }
        search = search + 1;
        var empty = directory[0] == 0;
        if empty {
            continue;
        }
        text.length = 0;
        module_require(node_text_set(&base, directory));
        module_require(bytes_append(&base, "/", 1));
        module_require(vector_push(u8, &base, 0));
        base.length = base.length - 1;
        ok = module_candidate(base.data, name, path);
        if ok {
            status = module_read(parent.graph.environment, path.data, text);
        }
    }
    vector_dispose(u8, &base);
    return status;
}

fn module_load(parent: FrontendModule*, name: u8*): FrontendModule* {
    var path: vector(u8);
    var text: vector(u8);
    vector_init(u8, &path);
    vector_init(u8, &text);
    var status = module_resolve(parent, name, &path, &text);
    var result: FrontendModule* = null;
    var ok = status == ModuleReady();
    if ok {
        var i: usize = 0;
        loop {
            var done = i == parent.graph.entities.length;
            if done {
                break;
            }
            var old = module_node(parent.graph, parent.graph.entities.data[i]);
            var same = module_equal(path.data, old.source.name.data);
            if same {
                result = old;
                break;
            }
            i = i + 1;
        }
        var found = result != null;
        if found {
            var active = result.state == ModuleLoading();
            if active {
                module_fail(parent, "Import cycle through ", path.data);
                result = null;
            }
        } else {
            var cached = module_cached(parent.graph.environment, path.data, text.data);
            var available = cached != null;
            if available {
                result = module_clone(parent.graph, cached);
            }
            else {
                var deep = parent.graph.depth >= ModuleMaximumDepth();
                if deep {
                    module_fail(parent, "Import depth exceeds 128: ", path.data);
                }
                else {
                    result = module_new(parent.graph, path.data, text.data);
                    result.explicit = true;
                    parent.graph.depth = parent.graph.depth + 1;
                    var session = syntax_create(result.source.text.data, result);
                    loop {
                        var root = syntax_next(session);
                        var done = root == null;
                        if done {
                            break;
                        }
                        entity_release(root);
                    }
                    var error = syntax_get_error(session);
                    var failed = error[0] != 0;
                    if failed {
                        module_fail(result, "", error);
                        frontend_module_diagnostic(result, syntax_get_error_offset(session));
                    }
                    syntax_destroy(session);
                    parent.graph.depth = parent.graph.depth - 1;
                    result.state = ModuleLoaded();
                    module_require(vector_push(FrontendModule*, &parent.graph.order, result));
                    var clean = parent.graph.error.length == 0;
                    if clean {
                        module_cache_store(result);
                    }
                }
            }
        }
    } else {
        var invalid = status == ModuleInvalidSource();
        if invalid {
            module_fail(parent, "Imported source must be UTF-8 without NUL bytes: ", name);
        }
        else {
            var limited = status == ModuleSourceLimit();
            if limited {
                module_fail(parent, "Imported source exceeds 8 MiB: ", name);
            }
            else {
                module_fail(parent, "Cannot read imported module: ", name);
            }
        }
    }
    vector_dispose(u8, &path);
    vector_dispose(u8, &text);
    return result;
}

// Dotted segments retain components on their actual parse entities. The joined
// slash path is a derived lookup key; formatting uses the preserved segments.
fn module_import_name(reader: SyntaxReader*, node: void*, value: SyntaxNode*): bool {
    var span = syntax_reader_span(reader, node);
    var missing = span == null;
    if missing {
        return false;
    }
    var first = reader.source.text.data[span.start];
    var quoted = first == 34;
    if quoted {} else {
        quoted = first == 39;
    }
    var ok: bool = true;
    if quoted {
        value.literal = true;
        ok = syntax_reader_quoted(reader, node, &value.name);
    } else {
        var segment = syntax_reader_member(node, "segment");
        var legacy = segment == null;
        if legacy {
            // Editable older Bedrock grammars can still capture Identifier directly.
            ok = syntax_reader_name(reader, node, &value.name);
        } else {
            loop {
                var done = node == null;
                if done {
                    break;
                }
                segment = syntax_reader_required(reader, node, "segment");
                missing = segment == null;
                if missing {
                    return false;
                }
                var part = syntax_reader_attach(reader, segment, SyntaxTerm());
                missing = part == null;
                if missing {
                    return false;
                }
                ok = syntax_reader_name(reader, segment, &part.text);
                if ok {
                    ok = part.text.length != 0;
                }
                if ok {
                    ok = vector_push(void*, &value.items, segment);
                }
                if ok {} else {
                    return false;
                }
                node = syntax_reader_member(node, "previous");
            }
            syntax_reader_reverse(&value.items);
            var i: usize = 0;
            loop {
                var done = i == value.items.length;
                if done {
                    break;
                }
                var separator = i != 0;
                if separator {
                    module_require(foundation_name_append(&value.name, 47));
                }
                var part = frontend_syntax(value.items.data[i], reader.syntax_kind);
                module_require(bytes_append(&value.name, part.text.data, part.text.length));
                i = i + 1;
            }
            module_require(foundation_name_append(&value.name, 0));
            value.name.length = value.name.length - 1;
        }
    }
    if ok {
        ok = value.name.length != 0;
        var i: usize = 0;
        loop {
            var done = i == value.name.length;
            if done {
                break;
            }
            var windows_separator = value.name.data[i] == 92;
            if windows_separator {
                value.name.data[i] = 47;
            }
            i = i + 1;
        }
    }
    return ok;
}

export fn frontend_module_import(module: FrontendModule*, node: void*, source: SyntaxSource*): bool {
    var reader: SyntaxReader;
    fill(&reader, 0, sizeof(SyntaxReader));
    reader.source = source;
    reader.match_kind = parser_match_get_type();
    reader.syntax_kind = syntax_component_type();
    var value = syntax_reader_attach(&reader, node, SyntaxImport());
    var name = syntax_reader_required(&reader, node, "name");
    var ok = reader.error == null;
    if ok {
        ok = module_import_name(&reader, name, value);
    }
    if module.body {
        module_fail(module, "Imports must precede this file's declarations and statements", "");
        return false;
    }
    if ok {} else {
        module_fail(module, "Invalid import declaration", "");
        return false;
    }
    var dependency = module_load(module, value.name.data);
    var present = dependency != null;
    if present {
        module_require(vector_push(FrontendModule*, &module.dependencies, dependency));
        entity_retain(node);
        module_require(vector_push(void*, &module.imports, node));
    }
    module.explicit = true;
    var is_root = module.entity == module.graph.entities.data[0];
    if is_root {
        module.graph.environment.implicit = false;
    }
    var clean = module.graph.error.length == 0;
    return clean;
}

export fn frontend_module_record(module: FrontendModule*, root: void*, declaration: bool): void {
    var node = entity_child_at(root, 0);
    if declaration {
        var value = frontend_syntax(node, syntax_component_type());
        var imported = value.kind == SyntaxImport();
        if imported {
            return;
        }
        entity_retain(node);
        module_require(vector_push(void*, &module.declarations, node));
    } else {
        entity_retain(root);
        module_require(vector_push(void*, &module.roots, root));
    }
    module.body = true;
}

export fn frontend_module_finish(module: FrontendModule*): void {
    module.state = ModuleLoaded();
    module_require(vector_push(FrontendModule*, &module.graph.order, module));
}

export fn frontend_module_count(module: FrontendModule*): usize {
    return module.graph.order.length;
}

export fn frontend_module_at(module: FrontendModule*, index: usize): FrontendModule* {
    return module.graph.order.data[index];
}

export fn frontend_module_source(module: FrontendModule*): u8* {
    return module.source.text.data;
}

export fn frontend_module_size(module: FrontendModule*): usize {
    return module.source.text.length;
}

export fn frontend_module_roots(module: FrontendModule*): usize {
    return module.roots.length;
}

export fn frontend_module_tree(module: FrontendModule*, index: usize): void* {
    return module.roots.data[index];
}

export fn frontend_module_destroy(module: FrontendModule*): void {
    var graph = module.graph;
    var active = graph.environment.active == module;
    if active {
        graph.environment.active = null;
    }
    var i: usize = 0;
    loop {
        var done = i == graph.entities.length;
        if done {
            break;
        }
        var current = module_node(graph, graph.entities.data[i]);
        var n: usize = 0;
        loop {
            done = n == current.declarations.length;
            if done {
                break;
            }
            entity_release(current.declarations.data[n]);
            n = n + 1;
        }
        n = 0;
        loop {
            done = n == current.roots.length;
            if done {
                break;
            }
            entity_release(current.roots.data[n]);
            n = n + 1;
        }
        n = 0;
        loop {
            done = n == current.imports.length;
            if done {
                break;
            }
            entity_release(current.imports.data[n]);
            n = n + 1;
        }
        vector_dispose(void*, &current.imports);
        module_grammar_clear(&current.grammar);
        vector_dispose(SyntaxRuleView, &current.grammar.rules);
        vector_dispose(void*, &current.grammar.tokens);
        vector_dispose(void*, &current.declarations);
        vector_dispose(void*, &current.roots);
        vector_dispose(FrontendModule*, &current.dependencies);
        syntax_source_release(current.source);
        entity_release(current.entity);
        i = i + 1;
    }
    vector_dispose(void*, &graph.entities);
    vector_dispose(FrontendModule*, &graph.order);
    vector_dispose(u8, &graph.error);
    var kind = graph.kind != null;
    if kind {
        entity_release(graph.kind);
    }
    if graph.owns_environment {
        frontend_modules_destroy(graph.environment);
    }
    free(graph);
}

export fn frontend_modules_create(): ModuleEnvironment* {
    var environment = alloc(ModuleEnvironment, 1);
    var ok = environment != null;
    module_require(ok);
    fill(environment, 0, sizeof(ModuleEnvironment));
    return environment;
}

export fn frontend_modules_reset_compilation(environment: ModuleEnvironment*): void {
    var missing = environment == null;
    if missing {
        return;
    }
    var present = environment.compilation_session != null;
    if present {
        syntax_destroy(environment.compilation_session);
    }
    environment.compilation_session = null;
}

// Reuse parser tables, never program-specific parse trees or semantic components.
export fn frontend_module_session(module: FrontendModule*): void* {
    var environment = module.graph.environment;
    var missing = environment.compilation_session == null;
    if missing {
        environment.compilation_session = syntax_create(module.source.text.data, module);
    }
    else {
        syntax_reset(environment.compilation_session, module.source.text.data, module);
    }
    return environment.compilation_session;
}

export fn frontend_modules_destroy(environment: ModuleEnvironment*): void {
    frontend_modules_reset_compilation(environment);
    var i: usize = 0;
    loop {
        var done = i == environment.cache.length;
        if done {
            break;
        }
        frontend_module_destroy(environment.cache.data[i]);
        i = i + 1;
    }
    vector_dispose(FrontendModule*, &environment.cache);
    frontend_modules_clear(environment);
    frontend_modules_used_clear(environment);
    vector_dispose(ModuleInput, &environment.inputs);
    i = 0;
    loop {
        var done = i == environment.aliases.length;
        if done {
            break;
        }
        vector_dispose(u8, &environment.aliases.data[i].name);
        vector_dispose(u8, &environment.aliases.data[i].path);
        i = i + 1;
    }
    vector_dispose(ModuleAlias, &environment.aliases);
    vector_dispose(u8, &environment.entry);
    vector_dispose(u8, &environment.library);
    vector_dispose(u8, &environment.fallback);
    vector_dispose(u8*, &environment.used);
    frontend_modules_sources_clear(environment);
    vector_dispose(SyntaxSource*, &environment.sources);
    vector_dispose(usize, &environment.bases);
    free(environment);
}

// Only declaration-only modules are cached. Ordinary parse trees acquire
// program-specific semantic components and must be rebuilt for each program.
// Cache identity includes exact source bytes of every transitive dependency.
fn module_cacheable(module: FrontendModule*): bool {
    var ordinary = module.roots.length != 0;
    if ordinary {
        return false;
    }
    var i: usize = 0;
    loop {
        var done = i == module.dependencies.length;
        if done {
            return true;
        }
        var ok = module_cacheable(module.dependencies.data[i]);
        if ok {} else {
            return false;
        }
        i = i + 1;
    }
}

fn module_cache_valid(environment: ModuleEnvironment*, module: FrontendModule*): bool {
    var text: vector(u8);
    vector_init(u8, &text);
    var status = module_read(environment, module.source.name.data, &text);
    var ok = status == ModuleReady();
    if ok {
        ok = module_equal(text.data, module.source.text.data);
    }
    vector_dispose(u8, &text);
    if ok {} else {
        return false;
    }
    var i: usize = 0;
    loop {
        var done = i == module.dependencies.length;
        if done {
            return true;
        }
        var path: vector(u8);
        vector_init(u8, &path);
        vector_init(u8, &text);
        var declaration = frontend_syntax(module.imports.data[i], syntax_component_type());
        status = module_resolve(module, declaration.name.data, &path, &text);
        ok = status == ModuleReady();
        if ok {
            ok = module_equal(path.data, module.dependencies.data[i].source.name.data);
        }
        vector_dispose(u8, &path);
        vector_dispose(u8, &text);
        if ok {
            ok = module_cache_valid(environment, module.dependencies.data[i]);
        }
        if ok {} else {
            return false;
        }
        i = i + 1;
    }
}

fn module_cached(environment: ModuleEnvironment*, path: u8*, text: u8*): FrontendModule* {
    var i: usize = 0;
    loop {
        var done = i == environment.cache.length;
        if done {
            return null;
        }
        var candidate = environment.cache.data[i];
        var same = module_equal(candidate.source.name.data, path);
        if same {
            same = module_equal(candidate.source.text.data, text);
        }
        if same {
            same = module_cache_valid(environment, candidate);
        }
        if same {
            return candidate;
        }
        i = i + 1;
    }
}

fn module_clone(graph: ModuleGraph*, source: FrontendModule*): FrontendModule* {
    var i: usize = 0;
    loop {
        var done = i == graph.entities.length;
        if done {
            break;
        }
        var old = module_node(graph, graph.entities.data[i]);
        var same = module_equal(old.source.name.data, source.source.name.data);
        if same {
            var active = old.state == ModuleLoading();
            if active {
                module_fail(old, "Import cycle through ", old.source.name.data);
                return null;
            }
            return old;
        }
        i = i + 1;
    }
    var result = module_new(graph, source.source.name.data, source.source.text.data);
    result.explicit = true;
    i = 0;
    loop {
        var done = i == source.dependencies.length;
        if done {
            break;
        }
        var dependency = module_clone(graph, source.dependencies.data[i]);
        var missing = dependency == null;
        if missing {
            return null;
        }
        module_require(vector_push(FrontendModule*, &result.dependencies, dependency));
        i = i + 1;
    }
    i = 0;
    loop {
        var done = i == source.declarations.length;
        if done {
            break;
        }
        var declaration = source.declarations.data[i];
        entity_retain(declaration);
        module_require(vector_push(void*, &result.declarations, declaration));
        i = i + 1;
    }
    i = 0;
    loop {
        var done = i == source.imports.length;
        if done {
            break;
        }
        var declaration = source.imports.data[i];
        entity_retain(declaration);
        module_require(vector_push(void*, &result.imports, declaration));
        i = i + 1;
    }
    result.body = true;
    result.state = ModuleLoaded();
    module_require(vector_push(FrontendModule*, &graph.order, result));
    return result;
}

fn module_cache_store(module: FrontendModule*): void {
    var eligible = module_cacheable(module);
    if eligible {} else {
        return;
    }
    var environment = module.graph.environment;
    var graph = alloc(ModuleGraph, 1);
    var present = graph != null;
    module_require(present);
    fill(graph, 0, sizeof(ModuleGraph));
    graph.environment = environment;
    var snapshot = module_clone(graph, module);
    var full = environment.cache.length == ModuleCacheEntries();
    if full {
        frontend_module_destroy(environment.cache.data[0]);
        var i: usize = 1;
        loop {
            var done = i == environment.cache.length;
            if done {
                break;
            }
            var previous = i - 1;
            environment.cache.data[previous] = environment.cache.data[i];
            i = i + 1;
        }
        environment.cache.length = environment.cache.length - 1;
    }
    module_require(vector_push(FrontendModule*, &environment.cache, snapshot));
}

export fn frontend_modules_used_clear(environment: ModuleEnvironment*): void {
    var i: usize = 0;
    loop {
        var done = i == environment.used.length;
        if done {
            break;
        }
        free(environment.used.data[i]);
        i = i + 1;
    }
    environment.used.length = 0;
}

export fn frontend_modules_used_count(environment: ModuleEnvironment*): usize {
