export fn frontend_modules_error_file(environment: ModuleEnvironment*): u8* {
    var absent = environment.diagnostic == null;
    if absent {
        return "";
    }
    return environment.diagnostic.name.data;
}

export fn frontend_modules_error_offset(environment: ModuleEnvironment*): usize {
    return environment.diagnostic_offset;
}

// Native transport asks the same source map used by browser execution handles.
export fn frontend_modules_location(environment: ModuleEnvironment*, offset: usize, line: usize*, column: usize*): u8* {
    var source = environment.diagnostic;
    var found = source != null;
    if found {
        offset = environment.diagnostic_offset;
    }
    else {
        var i: usize = 0;
        loop {
            var done = i == environment.sources.length;
            if done {
                break;
            }
            var candidate = environment.sources.data[i];
            var base = environment.bases.data[i];
            var end = base + candidate.text.length;
            var selected = offset >= base;
            if selected {
                selected = offset <= end;
            }
            if selected {
                source = candidate;
                offset = offset - base;
                break;
            }
            i = i + 1;
        }
    }
    found = source != null;
    if found {
        syntax_source_location(source, offset, line, column);
        return source.name.data;
    }
    return "";
}

fn module_make_path(text: vector(u8)*, path: u8*): void {
    var i: usize = 0;
    loop {
        var byte = path[i];
        var done = byte == 0;
        if done {
            return;
        }
        var escape = byte == 32;
        if escape {} else {
            escape = byte == 35;
        }
        if escape {} else {
            escape = byte == 58;
        }
        if escape {} else {
            escape = byte == 92;
        }
        if escape {
            module_require(vector_push(u8, text, 92));
        }
        var dollar = byte == 36;
        if dollar {
            module_require(vector_push(u8, text, 36));
        }
        module_require(vector_push(u8, text, byte));
        i = i + 1;
    }
}

export fn frontend_modules_depfile(environment: ModuleEnvironment*, output: u8*, path: u8*): bool {
    var omitted = path[0] == 0;
    if omitted {
        return true;
    }
    var text: vector(u8);
    vector_init(u8, &text);
    module_make_path(&text, output);
    module_require(bytes_append(&text, ":", 1));
    var i: usize = 0;
    loop {
        var done = i == environment.used.length;
        if done {
            break;
        }
        module_require(bytes_append(&text, " ", 1));
        module_make_path(&text, environment.used.data[i]);
        i = i + 1;
    }
    module_require(bytes_append(&text, "\n", 1));
    var file = fopen(path, "wb");
    var ok = file != null;
    if ok {
        var written = fwrite(text.data, 1, text.length, file);
        ok = written == text.length;
        var closed = fclose(file) == 0;
        if closed {} else {
            ok = false;
        }
    }
    vector_dispose(u8, &text);
    return ok;
}

import tower;

// Token patterns use the same character grammar/table reader as Bedrock.
// Errors use the shared text formatter and Unicode character positions.
struct FrontendPatternCompiler {
    kinds: FrontendKinds;
    table: FrontendTable;
}

export fn frontend_pattern_destroy(compiler: FrontendPatternCompiler*): void {
    var absent = compiler == null;
    if absent {
        return;
    }
    frontend_table_dispose(&compiler.table);
    free(compiler);
}

export fn frontend_pattern_create(kinds: FrontendKinds*): FrontendPatternCompiler* {
    var compiler = alloc(FrontendPatternCompiler, 1);
    var absent = compiler == null;
    if absent {
        return null;
    }
    copy(&compiler.kinds, kinds, sizeof(FrontendKinds));
    var ok = frontend_pattern_table(&compiler.table, &compiler.kinds);
    if ok {
        return compiler;
    }
    frontend_pattern_destroy(compiler);
    return null;
}

fn frontend_pattern_position(source: u8*, length: usize, offset: usize): usize {
    var character: usize = 1;
    var at: usize = 0;
    loop {
        var done = at >= offset;
        var end = at >= length;
        if end {
            done = true;
        }
        if done {
            return character;
        }
        var id: u32;
        var remaining = length - at;
        var width = tower_utf8_decode(&source[at], remaining, &id);
        var invalid = width == 0;
        if invalid {
            width = 1;
        }
        at = at + width;
        character = character + 1;
    }
}

export fn frontend_pattern_read(compiler: FrontendPatternCompiler*, source: u8*, length: usize,
error: FormatResult*): SyntaxPattern* {
    var formatter: FormatEngine;
    fill(&formatter, 0, sizeof(FormatEngine));
    formatter.result = error;
    var too_long = length > 4096;
    if too_long {
        format_text(&formatter, "Token pattern exceeds 4096 bytes");
        return null;
    }
    var valid = tower_utf8_validate(source, length, 0) != 0;
    if valid {} else {
        format_text(&formatter, "Invalid UTF-8 in token pattern");
        return null;
    }
    var missing = compiler == null;
    if missing {
        format_text(&formatter, "Unable to allocate token pattern grammar");
        return null;
    }
    var input: FrontendCharacters;
    fill(&input, 0, sizeof(FrontendCharacters));
    input.source = source;
    input.length = length;
    var root = frontend_read_characters(&compiler.table, &compiler.kinds, &input);
    missing = root == null;
    if missing {
        var allocation = input.error == 1;
        if allocation {
            format_text(&formatter, "Unable to allocate token pattern");
            return null;
        }
        format_text(&formatter, "Unexpected ");
        var end = input.offset == length;
        if end {
            format_text(&formatter, "end of input");
        } else {
            var zero = source[input.offset] == 0;
            if zero {
                format_text(&formatter, "'\\0'");
            } else {
                var id: u32;
                var remaining = length - input.offset;
                var width = tower_utf8_decode(&source[input.offset], remaining, &id);
                format_escape(&formatter, &source[input.offset], width, 39);
            }
        }
        format_text(&formatter, ". In token pattern at character ");
        var position = frontend_pattern_position(source, length, input.offset);
        format_unsigned(&formatter, convert(u64, position));
        return null;
    }
    var pattern = syntax_pattern_create(root);
    entity_release(root);
    missing = pattern == null;
    if missing {
        format_text(&formatter, "Unable to allocate token pattern");
        return null;
    }
    var offset: usize = 0;
    var message = regex_compile_tree(pattern.grammar, source, compiler.kinds.`match`, pattern.table, &offset);
    var failed = message != null;
    if failed {
        format_text(&formatter, message);
        format_text(&formatter, " at pattern character ");
        var position = frontend_pattern_position(source, length, offset);
        format_unsigned(&formatter, convert(u64, position));
        syntax_pattern_release(pattern);
        return null;
    }
    return pattern;
}

import tower;

// Table ownership shared by character and token readers. These are derived LR
// indexes over ordinary grammar entities, not a second grammar representation.
struct FrontendKinds {
    rule: void*;
    reference: void*;
    string: void*;
    range: void*;
    `match`: void*;
    syntax: void*;
}

struct FrontendTable {
    grammar: LRGrammar*;
    runtime: LRRuntime*;
}

export fn frontend_table_dispose(table: FrontendTable*): void {
    lr_runtime_destroy(table.runtime);
    lr_grammar_destroy(table.grammar);
    fill(table, 0, sizeof(FrontendTable));
}

// Grammar names must be resolved before this step. Both ordinary grammars and
// character grammars use the same analysis, conflict check and specialization.
export fn frontend_table_finish(table: FrontendTable*, constructs: bool, specialize: bool): u32 {
    var grammar = table.grammar;
    var unresolved: usize = 0;
    loop {
        var done = unresolved == grammar.unresolved.length;
        if done {
            break;
        }
        var symbol = grammar.unresolved.data[unresolved].symbol;
        var missing = grammar.symbols.data[symbol].first == 4294967294;
        if missing {
            return 3;
        }
        unresolved = unresolved + 1;
    }
    var analysis = lr_analysis_create(grammar.rules.data, grammar.rules.length,
    grammar.symbols.data, grammar.symbols.length, grammar.names.length);
    var missing = analysis == null;
    if missing {
        return 1;
    }
    var index: usize = 0;
    loop {
        var done = index == grammar.names.length;
        if done {
            break;
        }
        lr_analysis_order(analysis, index, grammar.names.data[index].order);
        index = index + 1;
    }
    var states: LRStates* = null;
    var ok = lr_analysis_compute(analysis);
    if ok {
        states = lr_states_create(analysis);
        ok = states != null;
    }
    if ok {
        ok = lr_states_lalr(states, constructs);
    }
    if ok {
        table.runtime = lr_runtime_create(states);
        ok = table.runtime != null;
    }
    var status: u32 = 1;
    if ok {
        var conflict: LRConflict;
        var ambiguous = lr_runtime_conflict(table.runtime, &conflict);
        if ambiguous {
            status = 2;
        } else {
            if specialize {
                lr_runtime_specialize(table.runtime, states);
            }
            lr_grammar_finish(grammar);
            status = 0;
        }
    }
    lr_states_destroy(states);
    lr_analysis_destroy(analysis);
    return status;
}

export fn frontend_table_init(table: FrontendTable*, root: void*, kinds: FrontendKinds*): bool {
    fill(table, 0, sizeof(FrontendTable));
    var absent = root == null;
    if absent {
        return false;
    }
    var empty = entity_child_count(root) == 0;
    if empty {
        return false;
    }
    table.grammar = lr_grammar_create(root, kinds.rule, kinds.reference, kinds.string, kinds.range);
    var ok = table.grammar != null;
    return ok;
}

extern fn parse_forest_create(): void*;

extern fn parse_forest_destroy(forest: void*): void;

extern fn tower_utf8_validate(source: u8*, length: usize, reject_nul: u32): u32;

struct FrontendCharacters {
    source: u8*;
    length: usize;
    cursor: usize;
    offset: usize;
    error: u32;
}

// The reader owns only its forest and LR stack. Input and table are borrowed;
// acceptance transfers one ordinary parse-tree reference to the caller.
export fn frontend_read_characters(table: FrontendTable*, kinds: FrontendKinds*, input: FrontendCharacters*): void* {
    var parser = lr_parser_create(table.runtime, false, true);
    var forest = parse_forest_create();
    var ok = parser != null;
    var present = forest != null;
    if present {} else {
        ok = false;
    }
    var root: void* = null;
    input.error = 1;
    var ready: bool = false;
    var id: u32 = 4294967294;
    var start: usize = 0;
    var length: usize = 0;
    loop {
        if ok {} else {
            break;
        }
        var step: LRStep;
        var action = lr_parser_step(parser, ready, id, false, start, length, &step);
        var read = action == 0;
        if read {
            start = input.cursor;
            length = 0;
            id = 4294967294;
            var remaining = start < input.length;
            if remaining {
                var count = input.length - start;
                length = tower_utf8_decode(&input.source[start], count, &id);
                var invalid = length == 0;
                if invalid {
                    input.error = 3;
                    break;
                }
                input.cursor = start + length;
            }
            ready = true;
            continue;
        }
        var accept = action == 3;
        if accept {
            root = lr_tree_accept(parser, forest);
            input.error = 0;
            break;
        }
        var shift = action == 1;
        var sequence = action == 6;
        if sequence {
            shift = true;
        }
        if shift {
            var input_node: void* = null;
            var status = lr_tree_shift(parser, forest, table.grammar, kinds.`match`, &step, &input_node, "");
            ok = status == 1;
            ready = false;
            continue;
        }
        var reduce = action == 2;
        sequence = action == 7;
        if sequence {
            reduce = true;
        }
        if reduce {
            ok = lr_tree_reduce(parser, forest, table.grammar, &step, &root);
            var complete = root != null;
            if complete {
                input.error = 0;
                break;
            }
            continue;
        }
        input.error = 2;
        break;
    }
    input.offset = start;
    if present {
        parse_forest_destroy(forest);
    }
    lr_parser_destroy(parser);
    return root;
}

export fn frontend_pattern_table(table: FrontendTable*, kinds: FrontendKinds*): bool {
    var root = regex_grammar_create();
    var ok = frontend_table_init(table, root, kinds);
    if ok {
        var status = frontend_table_finish(table, false, true);
        ok = status == 0;
    }
    entity_release(root);
    return ok;
}

export fn frontend_pattern_compile(table: FrontendTable*, kinds: FrontendKinds*, text: u8*): SyntaxPattern* {
    var input: FrontendCharacters;
    fill(&input, 0, sizeof(FrontendCharacters));
    input.source = text;
    input.length = syntax_text_length(text);
    var too_long = input.length > 4096;
    if too_long {
        return null;
    }
    var status = tower_utf8_validate(text, input.length, 0);
    var valid = status != 0;
    if valid {} else {
        return null;
    }
    var root = frontend_read_characters(table, kinds, &input);
    var absent = root == null;
    if absent {
        return null;
    }
    var pattern = syntax_pattern_create(root);
    entity_release(root);
    absent = pattern == null;
    if absent {
        return null;
    }
    var offset: usize = 0;
    var error = regex_compile_tree(pattern.grammar, text, kinds.`match`, pattern.table, &offset);
    var failed = error != null;
    if failed {
        syntax_pattern_release(pattern);
        return null;
    }
    return pattern;
}

import tower;

// Compiler transformations over the shared entity store. C++ only exposes
// existing payload access until those components are also defined in Tower.
extern fn compiler_node_label(node: Entity*, label: u8*): bool;

extern fn compiler_name_is(node: Entity*, name: u8*): bool;

extern fn compiler_name_equal(left: Entity*, right: Entity*): bool;

extern fn compiler_node_copy_metadata(source: Entity*, destination: Entity*): void;

extern fn compiler_generic_type(index: usize): Entity*;

fn compiler_component_get(node: Entity*, type: Entity*): void* {
    var missing = node == null;
    if missing {
        return null;
    }
    var component = entity_component_get(node, type);
    var data = entity_component_data(component);
    return bits(void*, data);
}

extern fn compiler_component_add(node: Entity*, type: Entity*, size: usize): void*;

fn compiler_node_count(node: Entity*): usize {
    var missing = node == null;
    if missing {
        return 0;
    }
    return entity_child_count(node);
}

fn compiler_node_member(node: Entity*, role: u8*): Entity* {
    var missing = node == null;
    if missing {
        return null;
    }
    var index = entity_member_index(node, role);
    return entity_child_at(node, index);
}

// These are semantic components attached to real definition/instance nodes.
// Fixed bounds match the current foundation parameter and function limits.
struct GenericTemplate {
    parameters: Entity*[64];
    type_parameters: bool[64];
    count: usize;
    type_count: usize;
    kind: u32;
}

struct GenericInstance {
    definition: Entity*;
    use: Entity*;
    node: Entity*;
    arguments: Entity*[64];
    count: usize;
    next: GenericInstance*;
}

struct GenericOrigin {
    definition: Entity*;
    use: Entity*;
}

// This linked index is derived from instance components, scoped to one program
// and its explicit target. It is not a second representation of the program.
struct GenericContext {
    root: Entity*;
    template_type: Entity*;
    instance_type: Entity*;
    origin_type: Entity*;
    first: GenericInstance*;
    count: usize;
    copied: usize;
    error: u8*;
}

export fn generic_begin(root: Entity*): GenericContext* {
    var type = compiler_generic_type(0);
    var data = compiler_component_add(root, type, sizeof(GenericContext));
    var context = bits(GenericContext*, data);
    fill(context, 0, sizeof(GenericContext));
    context.root = root;
    context.template_type = compiler_generic_type(1);
    context.instance_type = compiler_generic_type(2);
    context.origin_type = compiler_generic_type(3);
    return context;
}

export fn generic_error(context: GenericContext*): u8* {
    return context.error;
}

fn generic_parameters(context: GenericContext*, template: GenericTemplate*, node: Entity*, depth: usize): void {
    var deep = depth > 128;
    if deep {
        context.error = "Template parameter nesting exceeds 128";
        return;
    }
    var parameter = compiler_node_label(node, "CoreParameter");
    if parameter {
        var full = template.count == 64;
        if full {
            context.error = "A template supports at most 64 parameters";
            return;
        }
        var annotation = compiler_node_member(node, "type");
        var type = compiler_name_is(annotation, "type");
        template.parameters[template.count] = node;
        template.type_parameters[template.count] = type;
        template.count = template.count + 1;
        if type {
            template.type_count = template.type_count + 1;
        }
        return;
    }
    var i: usize = 0;
    var count = compiler_node_count(node);
    loop {
        var done = i == count;
        if done {
            break;
        }
        var child = entity_child_at(node, i);
        var next = depth + 1;
        generic_parameters(context, template, child, next);
        i = i + 1;
    }
}

export fn generic_register(context: GenericContext*, definition: Entity*): u32 {
    var temporary: GenericTemplate;
    var template = &temporary;
    fill(template, 0, sizeof(GenericTemplate));
    var params = compiler_node_member(definition, "params");
    generic_parameters(context, template, params, 0);
    var result = compiler_node_member(definition, "type");
    var produces_type = compiler_name_is(result, "type");
    var generic = template.type_count != 0;
    if generic {
        template.kind = 1;
    }
    if produces_type {
        template.kind = 2;
    }
    var needed = template.kind != 0;
    if needed {
        var data = compiler_component_add(definition, context.template_type, sizeof(GenericTemplate));
        copy(data, template, sizeof(GenericTemplate));
    }
    return template.kind;
}

export fn generic_parameter_count(context: GenericContext*, definition: Entity*): usize {
    var data = compiler_component_get(definition, context.template_type);
    var template = bits(GenericTemplate*, data);
    return template.count;
}

export fn generic_type_parameter(context: GenericContext*, definition: Entity*, index: usize): bool {
    var data = compiler_component_get(definition, context.template_type);
    var template = bits(GenericTemplate*, data);
    var valid = index < template.count;
    if valid {
        return template.type_parameters[index];
    }
    return false;
}

struct CloneFrame {
    source: Entity*;
    destination: Entity*;
    next: usize;
}

fn compiler_clone_node(source: Entity*, context: GenericContext*, use: Entity*): Entity* {
    var result = entity_create(source.store);
    var failed = result == null;
    if failed {
        return null;
    }
    compiler_node_copy_metadata(source, result);
    var record = context != null;
    if record {
        var data = compiler_component_add(result, context.origin_type, sizeof(GenericOrigin));
        var origin = bits(GenericOrigin*, data);
        origin.definition = source;
        origin.use = use;
    }
    return result;
}

// An explicit work stack preserves deep-tree support without host recursion.
fn compiler_clone_branch(source: Entity*, remaining: usize*, context: GenericContext*, use: Entity*): Entity* {
    var exhausted = *remaining == 0;
    if exhausted {
        return null;
    }
    var capacity: usize = 16;
    var frames = alloc(CloneFrame, capacity);
    var failed = frames == null;
    if failed {
        return null;
    }
    var result = compiler_clone_node(source, context, use);
    failed = result == null;
    if failed {
        free(frames);
        return null;
    }
    *remaining = *remaining - 1;
    frames[0].source = source;
    frames[0].destination = result;
    frames[0].next = 0;
    var length: usize = 1;
    loop {
        var empty = length == 0;
        if empty {
            break;
        }
        var top = length - 1;
        var frame = &frames[top];
        var count = compiler_node_count(frame.source);
        var done = frame.next == count;
        if done {
            length = top;
            continue;
        }
        exhausted = *remaining == 0;
        if exhausted {
            failed = true;
            break;
        }
        var full = length == capacity;
        if full {
            capacity = capacity * 2;
            var next = realloc(CloneFrame, frames, capacity);
            failed = next == null;
            if failed {
                break;
            }
            frames = next;
            frame = &frames[top];
        }
        var child = entity_child_at(frame.source, frame.next);
        var role = entity_child_name(frame.source, frame.next);
        var copy = compiler_clone_node(child, context, use);
        failed = copy == null;
        if failed {
            break;
        }
        *remaining = *remaining - 1;
        var attached = entity_attach(copy, frame.destination, role);
        entity_release(copy);
        failed = attached == false;
        if failed {
            break;
        }
        frame.next = frame.next + 1;
        frames[length].source = child;
        frames[length].destination = copy;
        frames[length].next = 0;
        length = length + 1;
    }
    free(frames);
    if failed {
        entity_release(result);
        return null;
    }
    return result;
}

export fn compiler_clone_tree(source: Entity*, limit: usize, copied: usize*): Entity* {
    var remaining = limit;
    var result = compiler_clone_branch(source, &remaining, null, null);
    *copied = limit - remaining;
    return result;
}

export fn generic_instantiate(context: GenericContext*, definition: Entity*, use: Entity*, arguments: Entity**, count: usize): Entity* {
    var data = compiler_component_get(definition, context.template_type);
    var template = bits(GenericTemplate*, data);
    var needed = template.type_count;
    var type_constructor = template.kind == 2;
    if type_constructor {
        needed = template.count;
    }
    var wrong = count != needed;
    if wrong {
        context.error = "Wrong number of compile-time arguments";
        return null;
    }
    var current = context.first;
    loop {
        var done = current == null;
        if done {
            break;
        }
        var same = current.definition == definition;
        var i: usize = 0;
        loop {
            var complete = i == count;
            if complete {
                break;
            }
            var different = current.arguments[i] != arguments[i];
            if different {
                same = false;
            }
            i = i + 1;
        }
        if same {
            return current.node;
        }
        current = current.next;
    }
    var full = context.count == 256;
    if full {
        context.error = "Template specialization limit exceeded (256 instances); check recursive type arguments";
        return null;
    }
    var remaining: usize = 65536;
    remaining = remaining - context.copied;
    var before = remaining;
    var node = compiler_clone_branch(definition, &remaining, context, use);
    var copied = before - remaining;
    context.copied = context.copied + copied;
    var failed = node == null;
    if failed {
        context.error = "Template expansion exceeds 65536 nodes or could not allocate its work stack";
        return null;
    }
    data = compiler_component_add(node, context.instance_type, sizeof(GenericInstance));
    var instance = bits(GenericInstance*, data);
    fill(instance, 0, sizeof(GenericInstance));
    instance.definition = definition;
    instance.use = use;
    instance.node = node;
    instance.count = count;
    var i: usize = 0;
    loop {
        var done = i == count;
        if done {
            break;
        }
        instance.arguments[i] = arguments[i];
        i = i + 1;
    }
    var attached = entity_attach(node, context.root, null);
    if attached {} else {
        entity_release(node);
        context.error = "Unable to attach template instance";
        return null;
    }
    // Publish before semantic resolution, so recursive references reuse this node.
    instance.next = context.first;
    context.first = instance;
    context.count = context.count + 1;
    entity_release(node);
    return node;
}

export fn generic_lookup(context: GenericContext*, node: Entity*, name: Entity*): Entity* {
    var empty = context.first == null;
    if empty {
        return null;
    }
    var origin = compiler_component_get(node, context.origin_type);
    var original = origin == null;
    if original {
        return null;
    }
    loop {
        var done = node == null;
        if done {
            return null;
        }
        var data = compiler_component_get(node, context.instance_type);
        var present = data != null;
        if present {
            var instance = bits(GenericInstance*, data);
            data = compiler_component_get(instance.definition, context.template_type);
            var template = bits(GenericTemplate*, data);
            var i: usize = 0;
            var argument: usize = 0;
            loop {
                var finished = i == template.count;
                if finished {
                    return null;
                }
                var compile_time = template.type_parameters[i];
                var type_constructor = template.kind == 2;
                if type_constructor {
                    compile_time = true;
                }
                if compile_time {
                    var parameter = compiler_node_member(template.parameters[i], "name");
                    var same = compiler_name_equal(parameter, name);
                    if same {
                        return instance.arguments[argument];
                    }
                    argument = argument + 1;
                }
                i = i + 1;
            }
        }
        node = entity_parent(node);
    }
}

// Initial type-function evaluator: one optional struct declaration, then return
// that struct or an existing type/type-producing call. General staged execution
// will extend this instead of introducing a second template expression language.
export fn generic_type_result(context: GenericContext*, instance: Entity*): Entity* {
    var body = compiler_node_member(instance, "body");
    var structure: Entity* = null;
    var returned: Entity* = null;
    var count = compiler_node_count(body);
    var i: usize = 0;
    loop {
        var done = i == count;
        if done {
            break;
        }
        var statement = entity_child_at(body, i);
        var relevant = compiler_node_label(statement, "Statement");
        if relevant {
            statement = entity_child_at(statement, 0);
            var already_returned = returned != null;
            var is_struct = compiler_node_label(statement, "CoreStruct");
            var is_return = compiler_node_label(statement, "CoreReturn");
            if already_returned {
                context.error = "A type constructor must end with its return";
                return null;
            }
            if is_struct {
                var duplicate = structure != null;
                if duplicate {
                    context.error = "A type constructor currently supports one local struct";
                    return null;
                }
                structure = statement;
            } else {
                if is_return {
                    returned = compiler_node_member(statement, "value");
                } else {
                    context.error = "Type constructors currently support a struct and return; general compile-time execution is not implemented";
                    return null;
                }
            }
        }
        i = i + 1;
    }
    var missing = returned == null;
    if missing {
        context.error = "A type constructor must return a type";
        return null;
    }
    var local = structure != null;
    if local {
        var name = compiler_node_member(structure, "name");
        var same = compiler_name_equal(name, returned);
        if same {
            return structure;
        }
        context.error = "A type constructor with a local struct must return that struct";
        return null;
    }
    loop {
        var children = compiler_node_count(returned);
        var wrapper = children == 1;
        if wrapper {
            returned = entity_child_at(returned, 0);
        } else {
            return returned;
        }
    }
}

export fn generic_origin(context: GenericContext*, node: Entity*): Entity* {
    var data = compiler_component_get(node, context.origin_type);
    var present = data != null;
    if present {
        var origin = bits(GenericOrigin*, data);
        return origin.use;
    }
    return null;
}

export fn generic_definition(context: GenericContext*, node: Entity*): Entity* {
    var data = compiler_component_get(node, context.origin_type);
    var present = data != null;
    if present {
        var origin = bits(GenericOrigin*, data);
        return origin.definition;
    }
    return node;
}

import tower;

// Existing host API over the same entity store. No copied nodes or components.
// Only singleton lifetime and native callback dispatch remain host boundaries.
extern fn compiler_entity_store(): EntityStore*;

extern fn abort(): void;

fn host_entity_require(ok: bool): void {
    if ok {} else {
        abort();
    }
}

export fn tower_node_get_allocated_count(): usize {
    return entity_store_count(compiler_entity_store());
}

export fn tower_component_get_allocated_count(): usize {
