}

export fn lr_items_create(): LRItems* {
    var result = alloc(LRItems, 1);
    var ok = result != null;
    if ok {
        fill(result, 0, sizeof(LRItems));
    }
    return result;
}

export fn lr_items_destroy(value: LRItems*): void {
    var missing = value == null;
    if missing {
        return;
    }
    vector_dispose(LRItem, &value.values);
    vector_dispose(LRItem, &value.pending);
    free(value);
}

fn lr_item_less(a: LRItem*, b: LRItem*): bool {
    var different = a.rule != b.rule;
    if different {
        var less = a.rule < b.rule;
        return less;
    }
    different = a.position != b.position;
    if different {
        var less = a.position < b.position;
        return less;
    }
    different = a.first != b.first;
    if different {
        var less = a.first < b.first;
        return less;
    }
    var less = a.last < b.last;
    return less;
}

export fn lr_items_insert(value: LRItems*, item: LRItem*): bool {
    if value.failed {
        return false;
    }
    // The caller may supply an item from this vector, which growth invalidates.
    var saved: LRItem;
    copy(&saved, item, sizeof(LRItem));
    var low: usize = 0;
    var high = value.values.length;
    loop {
        var done = low == high;
        if done {
            break;
        }
        var middle = high - low;
        middle = middle / 2;
        middle = middle + low;
        var less = lr_item_less(&value.values.data[middle], &saved);
        if less {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    var present = low < value.values.length;
    if present {
        var different = lr_item_less(&saved, &value.values.data[low]);
        if different {} else {
            return true;
        }
    }
    var count = value.values.length + 1;
    var ok = vector_reserve(LRItem, &value.values, count);
    if ok {
        ok = lr_append(LRItem, &value.pending, &saved);
    }
    if ok {} else {
        value.failed = true;
        return false;
    }
    var moved = value.values.length - low;
    var bytes = moved * sizeof(LRItem);
    var next = low + 1;
    copy(&value.values.data[next], &value.values.data[low], bytes);
    copy(&value.values.data[low], &saved, sizeof(LRItem));
    value.values.length = count;
    return true;
}

export fn lr_items_count(value: LRItems*): usize {
    return value.values.length;
}

export fn lr_items_data(value: LRItems*): LRItem* {
    return value.values.data;
}

fn lr_suffix(value: LRAnalysis*, rule: LRProduction*, position: usize, item: LRItem*, ranges: vector(SymbolRange)*): bool {
    var changed: bool = false;
    loop {
        var done = position >= rule.count;
        if done {
            return lr_range_insert(ranges, item.first, item.last, &changed);
        }
        var index = rule.begin + position;
        var symbol = &value.symbols[index];
        var terminal = symbol.nonterminal == lr_none();
        if terminal {
            return lr_range_insert(ranges, symbol.first, symbol.last, &changed);
        }
        var next = &value.nonterminals[symbol.nonterminal];
        var ok = lr_range_merge(ranges, &next.first, &changed);
        if ok {} else {
            return false;
        }
        if next.nullable {} else {
            return true;
        }
        position = position + 1;
    }
}

export fn lr_items_close(value: LRAnalysis*, items: LRItems*, lookahead: bool): bool {
    var ranges: vector(SymbolRange);
    vector_init(SymbolRange, &ranges);
    var ok: bool = true;
    loop {
        var done = items.pending.length == 0;
        if items.failed {
            done = true;
        }
        if value.failed {
            done = true;
        }
        if done {
            break;
        }
        items.pending.length = items.pending.length - 1;
        var item: LRItem;
        copy(&item, &items.pending.data[items.pending.length], sizeof(LRItem));
        var rule = &value.rules[item.rule];
        done = item.position >= rule.count;
        if done {
            continue;
        }
        var index = rule.begin + item.position;
        var symbol = &value.symbols[index];
        var terminal = symbol.nonterminal == lr_none();
        if terminal {
            continue;
        }
        ranges.length = 0;
        if lookahead {
            var position = item.position + 1;
            ok = lr_suffix(value, rule, position, &item, &ranges);
        } else {
            var changed: bool = false;
            ok = lr_range_insert(&ranges, 0, 0, &changed);
        }
        if ok {} else {
            value.failed = true;
            break;
        }
        var productions = &value.nonterminals[symbol.nonterminal].productions;
        var production: usize = 0;
        loop {
            done = production == productions.length;
            if items.failed {
                done = true;
            }
            if done {
                break;
            }
            var next: LRItem;
            next.rule = productions.data[production];
            next.position = 0;
            var range: usize = 0;
            loop {
                done = range == ranges.length;
                if done {
                    break;
                }
                next.first = ranges.data[range].first;
                next.last = ranges.data[range].last;
                ok = lr_items_insert(items, &next);
                if ok {} else {
                    break;
                }
                range = range + 1;
            }
            production = production + 1;
        }
    }
    vector_dispose(SymbolRange, &ranges);
    if items.failed {
        value.failed = true;
    }
    ok = value.failed == false;
    return ok;
}

export fn lr_items_goto(value: LRAnalysis*, input: LRItems*, symbol: LRSymbol*, output: LRItems*, lookahead: bool): bool {
    var index: usize = 0;
    loop {
        var done = index == input.values.length;
        if done {
            break;
        }
        var item: LRItem;
        copy(&item, &input.values.data[index], sizeof(LRItem));
        var rule = &value.rules[item.rule];
        var present = item.position < rule.count;
        if present {
            var at = rule.begin + item.position;
            var next = &value.symbols[at];
            var matches = next.nonterminal == symbol.nonterminal;
            var terminal = next.nonterminal == lr_none();
            if terminal {
                var contained = symbol.first >= next.first;
                if contained {} else {
                    matches = false;
                }
                contained = symbol.last <= next.last;
                if contained {} else {
                    matches = false;
                }
            }
            if matches {
                item.position = item.position + 1;
                var ok = lr_items_insert(output, &item);
                if ok {} else {
                    value.failed = true;
                    return false;
                }
            }
        }
        index = index + 1;
    }
    return lr_items_close(value, output, lookahead);
}

// LALR lookahead dependencies refer to kernel items by temporary dense indices.
// Propagate only changed sets; cyclic grammars converge without recursive calls.
struct LRPropagationNode {
    ranges: vector(SymbolRange);
    edges: vector(usize);
    queued: bool;
}

struct LRPropagation {
    nodes: LRPropagationNode*;
    count: usize;
    pending: vector(usize);
}

export fn lr_propagation_destroy(value: LRPropagation*): void {
    var missing = value == null;
    if missing {
        return;
    }
    var index: usize = 0;
    loop {
        var done = index == value.count;
        if done {
            break;
        }
        var node = &value.nodes[index];
        vector_dispose(SymbolRange, &node.ranges);
        vector_dispose(usize, &node.edges);
        index = index + 1;
    }
    free(value.nodes);
    vector_dispose(usize, &value.pending);
    free(value);
}

export fn lr_propagation_create(count: usize): LRPropagation* {
    var value = alloc(LRPropagation, 1);
    var missing = value == null;
    if missing {
        return null;
    }
    fill(value, 0, sizeof(LRPropagation));
    value.nodes = alloc(LRPropagationNode, count);
    missing = value.nodes == null;
    if missing {
        lr_propagation_destroy(value);
        return null;
    }
    value.count = count;
    var bytes = sizeof(LRPropagationNode) * count;
    fill(value.nodes, 0, bytes);
    var ok = vector_reserve(usize, &value.pending, count);
    if ok {} else {
        lr_propagation_destroy(value);
        return null;
    }
    return value;
}

fn lr_propagation_queue(value: LRPropagation*, index: usize): void {
    var node = &value.nodes[index];
    if node.queued {
        return;
    }
    // At most count distinct nodes can be queued. Capacity was reserved once.
    value.pending.data[value.pending.length] = index;
    value.pending.length = value.pending.length + 1;
    node.queued = true;
}

export fn lr_propagation_seed(value: LRPropagation*, index: usize, first: u32, last: u32): bool {
    var changed: bool = false;
    var ok = lr_range_insert(&value.nodes[index].ranges, first, last, &changed);
    if changed {
        lr_propagation_queue(value, index);
    }
    return ok;
}

export fn lr_propagation_edge(value: LRPropagation*, source: usize, destination: usize): bool {
    // Duplicate dependencies do not change the fixed point or queued work.
    var ok = vector_push(usize, &value.nodes[source].edges, destination);
    if ok {
        lr_propagation_queue(value, source);
    }
    return ok;
}

export fn lr_propagation_solve(value: LRPropagation*): bool {
    loop {
        var done = value.pending.length == 0;
        if done {
            return true;
        }
        value.pending.length = value.pending.length - 1;
        var index = value.pending.data[value.pending.length];
        var source = &value.nodes[index];
        source.queued = false;
        var edge: usize = 0;
        loop {
            done = edge == source.edges.length;
            if done {
                break;
            }
            var destination = source.edges.data[edge];
            var target = &value.nodes[destination];
            var changed: bool = false;
            var ok = lr_range_merge(&target.ranges, &source.ranges, &changed);
            if ok {} else {
                return false;
            }
            if changed {
                lr_propagation_queue(value, destination);
            }
            edge = edge + 1;
        }
    }
}

export fn lr_propagation_count(value: LRPropagation*, index: usize): usize {
    return value.nodes[index].ranges.length;
}

export fn lr_propagation_data(value: LRPropagation*, index: usize): SymbolRange* {
    return value.nodes[index].ranges.data;
}

import tower;

// Derived indexes over ordinary grammar entities. Names/captures are snapshots
// for this table revision; source entities and declaration order remain intact.
struct LRGrammarName {
    text: vector(u8);
    hash: usize;
    next: usize;
    order: usize;
}

struct LRGrammarRule {
    node: void*;
    generated: bool;
}

struct LRGrammarSymbol {
    node: void*;
    capture: vector(u8);
}

struct LRUnresolved {
    name: u8*;
    symbol: usize;
}

struct LRGrammar {
    names: vector(LRGrammarName*);
    buckets: vector(usize);
    rules: vector(LRProduction);
    rule_metadata: vector(LRGrammarRule);
    symbols: vector(LRSymbol);
    symbol_metadata: vector(LRGrammarSymbol);
    unresolved: vector(LRUnresolved);
}

fn lr_name_hash(text: u8*): usize {
    var hash: usize = 2166136261;
    var index: usize = 0;
    loop {
        var end = text[index] == 0;
        if end {
            return hash;
        }
        var byte = convert(usize, text[index]);
        hash = hash ^ byte;
        hash = hash * 16777619;
        index = index + 1;
    }
}

fn lr_name_equal(left: u8*, right: u8*): bool {
    var index: usize = 0;
    loop {
        var different = left[index] != right[index];
        if different {
            return false;
        }
        var end = left[index] == 0;
        if end {
            return true;
        }
        index = index + 1;
    }
}

fn lr_grammar_lookup(value: LRGrammar*, name: u8*, hash: usize): usize {
    var size = value.buckets.length;
    var empty = size == 0;
    if empty {
        return lr_none();
    }
    var bucket = hash % size;
    var index = value.buckets.data[bucket];
    loop {
        var end = index == lr_none();
        if end {
            return index;
        }
        var entry = value.names.data[index];
        var same = entry.hash == hash;
        if same {
            same = lr_name_equal(name, node_text_get(&entry.text));
            if same {
                return index;
            }
        }
        index = entry.next;
    }
}

fn lr_grammar_name_add(value: LRGrammar*, name: u8*, index: usize*): bool {
    var hash = lr_name_hash(name);
    *index = lr_grammar_lookup(value, name, hash);
    var found = *index != lr_none();
    if found {
        return true;
    }
    var entry = alloc(LRGrammarName, 1);
    var missing = entry == null;
    if missing {
        return false;
    }
    fill(entry, 0, sizeof(LRGrammarName));
    var ok = node_text_set(&entry.text, name);
    if ok {
        ok = vector_push(LRGrammarName*, &value.names, entry);
    }
    if ok {} else {
        vector_dispose(u8, &entry.text);
        free(entry);
        return false;
    }
    *index = value.names.length - 1;
    entry.hash = hash;
    // The augmented start name is diagnostic text, not a source-name binding.
    var initial = *index == 0;
    if initial {
        return true;
    }
    var size = value.buckets.length;
    var empty = size == 0;
    if empty {
        return false;
    }
    var bucket = hash % size;
    entry.next = value.buckets.data[bucket];
    value.buckets.data[bucket] = *index;
    return true;
}

fn lr_grammar_name_less(value: LRGrammar*, a: usize, b: usize): bool {
    var left = node_text_get(&value.names.data[a].text);
    var right = node_text_get(&value.names.data[b].text);
    var index: usize = 0;
    loop {
        var different = left[index] != right[index];
        if different {
            var less = left[index] < right[index];
            return less;
        }
        var end = left[index] == 0;
        if end {
            var less = a < b;
            return less;
        }
        index = index + 1;
    }
}

fn lr_grammar_name_sift(value: LRGrammar*, order: usize*, count: usize, start: usize): void {
    var root = start;
    loop {
        var child = root * 2;
        child = child + 1;
        var end = child >= count;
        if end {
            return;
        }
        var next = child + 1;
        var present = next < count;
        if present {
            var less = lr_grammar_name_less(value, order[child], order[next]);
            if less {
                child = next;
            }
        }
        var less = lr_grammar_name_less(value, order[root], order[child]);
        if less {} else {
            return;
        }
        var swap = order[root];
        order[root] = order[child];
        order[child] = swap;
        root = child;
    }
}

fn lr_grammar_order(value: LRGrammar*): bool {
    var count = value.names.length;
    var order = alloc(usize, count);
    var missing = order == null;
    if missing {
        return false;
    }
    var index: usize = 0;
    loop {
        var end = index == count;
        if end {
            break;
        }
        order[index] = index;
        index = index + 1;
    }
    var start = count / 2;
    loop {
        var end = start == 0;
        if end {
            break;
        }
        start = start - 1;
        lr_grammar_name_sift(value, order, count, start);
    }
    var remaining = count;
    loop {
        var end = remaining <= 1;
        if end {
            break;
        }
        remaining = remaining - 1;
        var swap = order[0];
        order[0] = order[remaining];
        order[remaining] = swap;
        lr_grammar_name_sift(value, order, remaining, 0);
    }
    index = 0;
    loop {
        var end = index == count;
        if end {
            break;
        }
        var original = order[index];
        value.names.data[original].order = index;
        index = index + 1;
    }
    free(order);
    return true;
}

export fn lr_grammar_destroy(value: LRGrammar*): void {
    var missing = value == null;
    if missing {
        return;
    }
    var index: usize = 0;
    loop {
        var done = index == value.names.length;
        if done {
            break;
        }
        var name = value.names.data[index];
        vector_dispose(u8, &name.text);
        free(name);
        index = index + 1;
    }
    index = 0;
    loop {
        var done = index == value.symbol_metadata.length;
        if done {
            break;
        }
        vector_dispose(u8, &value.symbol_metadata.data[index].capture);
        index = index + 1;
    }
    vector_dispose(LRGrammarName*, &value.names);
    vector_dispose(usize, &value.buckets);
    vector_dispose(LRProduction, &value.rules);
    vector_dispose(LRGrammarRule, &value.rule_metadata);
    vector_dispose(LRSymbol, &value.symbols);
    vector_dispose(LRGrammarSymbol, &value.symbol_metadata);
    vector_dispose(LRUnresolved, &value.unresolved);
    free(value);
}

fn lr_grammar_payload(node: void*, kind: void*): void* {
    var component = entity_component_get(node, kind);
    return entity_component_data(component);
}

fn lr_grammar_add_symbol(value: LRGrammar*, symbol: LRSymbol*, node: void*, capture: u8*): bool {
    var metadata: LRGrammarSymbol;
    fill(&metadata, 0, sizeof(LRGrammarSymbol));
    metadata.node = node;
    var ok = true;
    var named = *capture != 0;
    if named {
        ok = node_text_set(&metadata.capture, capture);
    }
    if ok {
        ok = lr_append(LRGrammarSymbol, &value.symbol_metadata, &metadata);
    }
    if ok {} else {
        vector_dispose(u8, &metadata.capture);
        return false;
    }
    return lr_append(LRSymbol, &value.symbols, symbol);
}

fn lr_grammar_rules(value: LRGrammar*, root: void*, kind: void*): bool {
    var count = entity_child_count(root);
    var size = count * 2;
    size = size + 1;
    var ok = vector_reserve(usize, &value.buckets, size);
    if ok {} else {
        return false;
    }
    value.buckets.length = size;
    var bytes = size * sizeof(usize);
    fill(value.buckets.data, 255, bytes);
    var index: usize;
    ok = lr_grammar_name_add(value, "S'", &index);
    if ok {} else {
        return false;
    }
    var rule: LRProduction;
    fill(&rule, 0, sizeof(LRProduction));
    var metadata: LRGrammarRule;
    fill(&metadata, 0, sizeof(LRGrammarRule));
    ok = lr_append(LRProduction, &value.rules, &rule);
    if ok {
        ok = lr_append(LRGrammarRule, &value.rule_metadata, &metadata);
    }
    if ok {} else {
        return false;
    }
    index = 0;
    loop {
        var done = index == count;
        if done {
            return lr_grammar_order(value);
        }
        metadata.node = entity_child_at(root, index);
        var data = lr_grammar_payload(metadata.node, kind);
        var source = bits(ParserRuleData*, data);
        var missing = source == null;
        if missing {
            return false;
        }
        metadata.generated = source.generated;
        ok = lr_grammar_name_add(value, node_rule_name(source), &rule.owner);
        if ok {
            ok = lr_append(LRProduction, &value.rules, &rule);
        }
        if ok {
            ok = lr_append(LRGrammarRule, &value.rule_metadata, &metadata);
        }
        if ok {} else {
            return false;
        }
        index = index + 1;
    }
}

fn lr_grammar_symbols(value: LRGrammar*, reference_kind: void*, string_kind: void*, range_kind: void*): bool {
    var symbol: LRSymbol;
    symbol.first = 4294967294;
    symbol.last = 4294967294;
    symbol.nonterminal = 1;
    var present = value.names.length > 1;
    if present {
        var ok = lr_grammar_add_symbol(value, &symbol, null, "");
        if ok {} else {
            return false;
        }
        value.rules.data[0].count = 1;
    }
    var rule_index: usize = 1;
    loop {
        var done = rule_index == value.rules.length;
        if done {
            return true;
        }
        var rule = &value.rules.data[rule_index];
        var source = value.rule_metadata.data[rule_index].node;
        rule.begin = value.symbols.length;
        var count = entity_child_count(source);
        var index: usize = 0;
        loop {
            done = index == count;
            if done {
                break;
            }
            var node = entity_child_at(source, index);
            var data = lr_grammar_payload(node, reference_kind);
            var reference = bits(ParserReferenceData*, data);
            present = reference != null;
            if present {
                var name = node_reference_name(reference);
                var hash = lr_name_hash(name);
                symbol.nonterminal = lr_grammar_lookup(value, name, hash);
                symbol.first = 4294967294;
                symbol.last = 4294967294;
                var unresolved = symbol.nonterminal == lr_none();
                if unresolved {
                    var pending: LRUnresolved;
                    pending.name = name;
                    pending.symbol = value.symbols.length;
                    var ok = lr_append(LRUnresolved, &value.unresolved, &pending);
                    if ok {} else {
                        return false;
                    }
                }
                var capture = node_reference_capture(reference);
                var ok = lr_grammar_add_symbol(value, &symbol, node, capture);
                if ok {} else {
                    return false;
                }
            }
            data = lr_grammar_payload(node, string_kind);
            var string = bits(ParserStringData*, data);
            present = string != null;
            if present {
                var position: usize = 0;
                loop {
                    done = position == string.ids.length;
                    if done {
                        break;
                    }
                    symbol.nonterminal = lr_none();
                    symbol.first = string.ids.data[position];
                    symbol.last = symbol.first;
                    var ok = lr_grammar_add_symbol(value, &symbol, node, "");
                    if ok {} else {
                        return false;
                    }
                    position = position + 1;
                }
            }
            data = lr_grammar_payload(node, range_kind);
            var range = bits(ParserRangeData*, data);
            present = range != null;
            if present {
                symbol.nonterminal = lr_none();
                symbol.first = range.start;
