import '../library/vector';
import tower;

// Components stored on the same compiler entities. The native adapter borrows
// these payloads; all field layout, text and token-array ownership is Tower code.
// Built with library/vector.tower; public construction still uses entity APIs.
struct ParserRuleData {
    name: vector(u8);
    generated: bool;
}

struct ParserReferenceData {
    name: vector(u8);
    capture: vector(u8);
}

struct ParserStringData {
    ids: vector(u32);
}

struct ParserRangeData {
    start: u32;
    end: u32;
}

struct ParserMatchData {
    id: u32;
    start: usize;
    length: usize;
    rule: usize;
    label: vector(u8);
}

import tower;

// Regex notation is parsed by the ordinary LR engine over Unicode scalar IDs.
// These are the same Rule/Reference/String/Range components as other grammars.
// Construction calls are temporary native ABI adapters, not a regex parser.
extern fn compiler_grammar_root(): void*;

extern fn compiler_grammar_rule(root: void*, name: u8*, generated: bool): void*;

extern fn compiler_grammar_reference(rule: void*, name: u8*, capture: u8*): void;

extern fn compiler_grammar_literal(rule: void*, text: u8*): void;

extern fn compiler_grammar_range(rule: void*, first: u32, last: u32): void;

fn regex_reference(root: void*, name: u8*, child: u8*): void {
    var rule = compiler_grammar_rule(root, name, false);
    compiler_grammar_reference(rule, child, "value");
}

fn regex_symbols(root: void*, name: u8*, symbols: u8*): void {
    var i: usize = 0;
    loop {
        var value = symbols[i];
        var done = value == 0;
        if done {
            return;
        }
        var rule = compiler_grammar_rule(root, name, false);
        var scalar = convert(u32, value);
        compiler_grammar_range(rule, scalar, scalar);
        i = i + 1;
    }
}

fn regex_characters(root: void*, name: u8*, excluded: u8*): void {
    var blocked: u8[128];
    fill(&blocked, 0, 128);
    var i: usize = 0;
    loop {
        var value = excluded[i];
        var done = value == 0;
        if done {
            break;
        }
        blocked[value] = 1;
        i = i + 1;
    }
    var first: u32 = 0;
    var scalar: u32 = 0;
    loop {
        var done = scalar == 128;
        if done {
            break;
        }
        var omit = blocked[scalar] != 0;
        if omit {
            var nonempty = first < scalar;
            if nonempty {
                var last = scalar - 1;
                var rule = compiler_grammar_rule(root, name, false);
                compiler_grammar_range(rule, first, last);
            }
            first = scalar + 1;
        }
        scalar = scalar + 1;
    }
    var rule = compiler_grammar_rule(root, name, false);
    compiler_grammar_range(rule, first, 1114111);
}

export fn regex_grammar_create(): void* {
    var root = compiler_grammar_root();
    regex_reference(root, "Regex", "RegexChoice");

    var rule = compiler_grammar_rule(root, "RegexChoice", false);
    compiler_grammar_reference(rule, "RegexChoice", "left");
    compiler_grammar_literal(rule, "|");
    compiler_grammar_reference(rule, "RegexSequence", "right");
    regex_reference(root, "RegexChoice", "RegexSequence");

    rule = compiler_grammar_rule(root, "RegexSequence", false);
    compiler_grammar_reference(rule, "RegexSequence", "left");
    compiler_grammar_reference(rule, "RegexRepeat", "right");
    compiler_grammar_rule(root, "RegexSequence", false);

    rule = compiler_grammar_rule(root, "RegexRepeat", false);
    compiler_grammar_reference(rule, "RegexAtom", "atom");
    compiler_grammar_reference(rule, "RegexSuffix", "suffix");
    regex_symbols(root, "RegexSuffix", "*+?");
    compiler_grammar_rule(root, "RegexSuffix", false);

    rule = compiler_grammar_rule(root, "RegexAtom", false);
    compiler_grammar_literal(rule, "(");
    compiler_grammar_reference(rule, "RegexChoice", "group");
    compiler_grammar_literal(rule, ")");
    regex_reference(root, "RegexAtom", "RegexClass");
    regex_reference(root, "RegexAtom", "RegexCharacter");
    rule = compiler_grammar_rule(root, "RegexAtom", false);
    compiler_grammar_literal(rule, ".");

    // Class dashes remain character entries. Range grouping is a semantic step;
    // escaped dashes and leading/trailing dashes keep their literal meanings.
    rule = compiler_grammar_rule(root, "RegexClass", false);
    compiler_grammar_literal(rule, "[");
    compiler_grammar_literal(rule, "^");
    compiler_grammar_reference(rule, "RegexClassCharacters", "negated");
    compiler_grammar_literal(rule, "]");
    rule = compiler_grammar_rule(root, "RegexClass", false);
    compiler_grammar_literal(rule, "[");
    compiler_grammar_reference(rule, "RegexClassBody", "body");
    compiler_grammar_literal(rule, "]");
    rule = compiler_grammar_rule(root, "RegexClassBody", false);
    compiler_grammar_reference(rule, "RegexClassFirst", "first");
    compiler_grammar_reference(rule, "RegexClassCharacters", "rest");
    compiler_grammar_rule(root, "RegexClassBody", false);
    rule = compiler_grammar_rule(root, "RegexClassCharacters", false);
    compiler_grammar_reference(rule, "RegexClassCharacters", "left");
    compiler_grammar_reference(rule, "RegexClassCharacter", "right");
    compiler_grammar_rule(root, "RegexClassCharacters", false);
    regex_reference(root, "RegexClassFirst", "RegexClassInitial");
    regex_reference(root, "RegexClassFirst", "RegexEscape");
    regex_reference(root, "RegexClassCharacter", "RegexClassPlain");
    regex_reference(root, "RegexClassCharacter", "RegexEscape");
    regex_characters(root, "RegexClassInitial", "^]\\");
    regex_characters(root, "RegexClassPlain", "]\\");

    regex_reference(root, "RegexCharacter", "RegexPlain");
    regex_reference(root, "RegexCharacter", "RegexEscape");
    regex_characters(root, "RegexPlain", "\\[()|.*+?^${}");
    rule = compiler_grammar_rule(root, "RegexEscape", false);
    compiler_grammar_literal(rule, "\\");
    compiler_grammar_reference(rule, "RegexEscapedSymbol", "symbol");
    regex_symbols(root, "RegexEscapedSymbol", "nrt\\/[]()|*+?.^-{}$\"'");
    rule = compiler_grammar_rule(root, "RegexEscape", false);
    compiler_grammar_literal(rule, "\\x");
    compiler_grammar_reference(rule, "RegexHexDigit", "first");
    compiler_grammar_reference(rule, "RegexHexDigit", "second");
    rule = compiler_grammar_rule(root, "RegexEscape", false);
    compiler_grammar_literal(rule, "\\u{");
    compiler_grammar_reference(rule, "RegexHexDigits", "digits");
    compiler_grammar_literal(rule, "}");
    regex_reference(root, "RegexHexDigits", "RegexHexDigit");
    rule = compiler_grammar_rule(root, "RegexHexDigits", false);
    compiler_grammar_reference(rule, "RegexHexDigits", "left");
    compiler_grammar_reference(rule, "RegexHexDigit", "right");
    rule = compiler_grammar_rule(root, "RegexHexDigit", false);
    compiler_grammar_range(rule, 48, 57);
    rule = compiler_grammar_rule(root, "RegexHexDigit", false);
    compiler_grammar_range(rule, 65, 70);
    rule = compiler_grammar_rule(root, "RegexHexDigit", false);
    compiler_grammar_range(rule, 97, 102);
    return root;
}

import tower;

// Read the ordinary parser entities and lower their regex semantics into a
// disposable automaton. Work stacks hold borrowed entities, never another AST.
extern fn entity_component_get(node: void*, kind: void*): void*;

extern fn entity_component_data(component: void*): void*;

extern fn entity_member_index(node: void*, name: u8*): usize;

extern fn entity_child_at(node: void*, index: usize): void*;

extern fn entity_child_count(node: void*): usize;

struct RegexPatch {
    state: i32;
    other: bool;
    next: usize;
}

struct RegexFragment {
    start: i32;
    first: usize;
    last: usize;
}

struct RegexVisit {
    node: void*;
    depth: usize;
    finish: bool;
}

struct RegexLowering {
    source: u8*;
    match_type: void*;
    automaton: Automaton*;
    error: u8*;
    cursor: usize;
    visits: vector(RegexVisit);
    values: vector(RegexFragment);
    patches: vector(RegexPatch);
    pending: vector(void*);
    characters: vector(void*);
}

fn regex_none(): usize {
    var value: usize = 0;
    value = value - 1;
    return value;
}

fn regex_match(context: RegexLowering*, node: void*): ParserMatchData* {
    var component = entity_component_get(node, context.match_type);
    var data = entity_component_data(component);
    return bits(ParserMatchData*, data);
}

fn regex_member(node: void*, name: u8*): void* {
    var index = entity_member_index(node, name);
    return entity_child_at(node, index);
}

fn regex_named(context: RegexLowering*, node: void*, name: u8*): bool {
    var missing = node == null;
    if missing {
        return false;
    }
    var `match` = regex_match(context, node);
    var label = node_text_get(&`match`.label);
    var i: usize = 0;
    loop {
        var different = label[i] != name[i];
        if different {
            return false;
        }
        var end = label[i] == 0;
        if end {
            return true;
        }
        i = i + 1;
    }
}

fn regex_fail(context: RegexLowering*, message: u8*): void {
    var first = context.error == null;
    if first {
        context.error = message;
    }
}

fn regex_allocation(context: RegexLowering*, ok: bool): void {
    if ok {} else {
        regex_fail(context, "Unable to allocate regex lowering work");
    }
}

fn regex_empty(fragment: RegexFragment*): void {
    fragment.start = -1;
    fragment.first = regex_none();
    fragment.last = regex_none();
}

fn regex_visit(context: RegexLowering*, node: void*, depth: usize, finish: bool): void {
    var count = context.visits.length + 1;
    var ok = vector_reserve(RegexVisit, &context.visits, count);
    regex_allocation(context, ok);
    if ok {
        var visit = &context.visits.data[context.visits.length];
        visit.node = node;
        visit.depth = depth;
        visit.finish = finish;
        context.visits.length = count;
    }
}

fn regex_push(context: RegexLowering*, fragment: RegexFragment*): void {
    var count = context.values.length + 1;
    var ok = vector_reserve(RegexFragment, &context.values, count);
    regex_allocation(context, ok);
    if ok {
        copy(&context.values.data[context.values.length], fragment, sizeof(RegexFragment));
        context.values.length = count;
    }
}

fn regex_pop(context: RegexLowering*, fragment: RegexFragment*): void {
    context.values.length = context.values.length - 1;
    copy(fragment, &context.values.data[context.values.length], sizeof(RegexFragment));
}

fn regex_end(context: RegexLowering*, fragment: RegexFragment*, state: i32, other: bool): void {
    var index = context.patches.length;
    var count = index + 1;
    var ok = vector_reserve(RegexPatch, &context.patches, count);
    regex_allocation(context, ok);
    if ok {
        var end = &context.patches.data[index];
        end.state = state;
        end.other = other;
        end.next = regex_none();
        var empty = fragment.first == regex_none();
        if empty {
            fragment.first = index;
        }
        else {
            context.patches.data[fragment.last].next = index;
        }
        fragment.last = index;
        context.patches.length = count;
    }
}

fn regex_join(context: RegexLowering*, left: RegexFragment*, right: RegexFragment*): void {
    var empty = right.first == regex_none();
    if empty {
        return;
    }
    empty = left.first == regex_none();
    if empty {
        left.first = right.first;
    }
    else {
        context.patches.data[left.last].next = right.first;
    }
    left.last = right.last;
}

fn regex_patch(context: RegexLowering*, fragment: RegexFragment*, target: i32): void {
    var index = fragment.first;
    loop {
        var done = index == regex_none();
        if done {
            return;
        }
        var patch = &context.patches.data[index];
        automaton_patch(context.automaton, patch.state, patch.other, target);
        index = patch.next;
