            }
        }
    }
    *error_offset = context.cursor;
    var error = context.error;
    vector_dispose(RegexVisit, &context.visits);
    vector_dispose(RegexFragment, &context.values);
    vector_dispose(RegexPatch, &context.patches);
    vector_dispose(void*, &context.pending);
    vector_dispose(void*, &context.characters);
    automaton_destroy(context.automaton);
    free(context);
    return error;
}

