fn sem_editor_contains(c: SemanticContext*, n: void*): bool {
    var editor_condition1 = c.editor == null;
    if editor_condition1 {
        return false;
    }
    var editor_condition2 = n == null;
    if editor_condition2 {
        return false;
    }
    var editor_condition3 = sem_source_base(c, n) != 0;
    if editor_condition3 {
        return false;
    }
    var span = sem_match(n);
    var editor_condition4 = span == null;
    if editor_condition4 {
        return false;
    }
    var editor_condition5 = span.start > c.editor.offset;
    if editor_condition5 {
        return false;
