    if editor_condition6 {
        return false;
    }
    var editor_condition7 = span.length != c.editor.length;
    if editor_condition7 {
        return false;
    }
    if c.editor.found {
        return true;
    }
    c.editor.found = true;
    c.editor.kind = kind;
    c.editor.scope = c.scope;
    c.editor.current = c.current;
    c.editor.loops = c.loops;
