                }
                if term.literal {
                    value.names.data[name].declaration = true;
                } else {
                    emission_visit(value, name);
                }
                position = position + 1;
            }
            alternative = alternative + 1;
        }
        index = index + 1;
    }
}

fn emission_first(value: SyntaxEmission*): void {
    loop {
        var changed: bool = false;
        var index: usize = 0;
        loop {
            var done = index == value.input.count;
            if done {
                break;
            }
            var rule = &value.input.rules[index];
            var state = &value.states.data[index];
            var alternative: usize = 0;
            loop {
                var done = alternative == rule.count;
                if done {
                    break;
                }
                var sequence = emission_node(value, rule.alternatives[alternative]);
                var position: usize = 0;
                var empty: bool = true;
                loop {
                    var done = position == sequence.items.length;
                    if done {
                        break;
                    }
                    var term = emission_node(value, sequence.items.data[position]);
                    var name = emission_name(value, term.text.data, term.text.length);
                    if value.failed {
                        return;
                    }
                    var target = value.names.data[name].rule;
                    var missing = target == lr_none();
                    var nullable: bool = false;
                    var ok: bool = true;
                    if term.literal {
                        ok = emission_insert(&state.first, name, &changed);
                    } else {
                        if missing {
                            var marker: u8 = 1;
                            value.scratch.length = 0;
                            ok = bytes_append(&value.scratch, &marker, 1);
                            if ok {
                                ok = bytes_append(&value.scratch, term.text.data, term.text.length);
                            }
                            if ok {
                                name = emission_name(value, value.scratch.data, value.scratch.length);
                                if value.failed {
                                    return;
                                }
                                ok = emission_insert(&state.first, name, &changed);
                            }
                        } else {
                            var dependency = &value.states.data[target];
                            nullable = dependency.nullable;
                            var item: usize = 0;
                            loop {
                                var done = item == dependency.first.length;
                                if done {
                                    break;
                                }
                                ok = emission_insert(&state.first, dependency.first.data[item], &changed);
                                if ok {} else {
                                    break;
                                }
                                item = item + 1;
                            }
                        }
                    }
                    if ok {} else {
                        value.failed = true;
                        return;
                    }
                    var optional = term.repetition == 42;
                    var question = term.repetition == 63;
                    if question {
                        optional = true;
                    }
                    if optional {} else {
                        if nullable {} else {
                            empty = false;
                            break;
                        }
                    }
                    position = position + 1;
                }
                if empty {
                    if state.nullable {} else {
                        state.nullable = true;
                        changed = true;
                    }
                }
                alternative = alternative + 1;
            }
            index = index + 1;
        }
        if changed {} else {
            return;
        }
    }
}

fn emission_starts(value: SyntaxEmission*, text: u8*): void {
    var name = emission_cname(value, text);
    if value.failed {
        return;
    }
    var rule = value.names.data[name].rule;
    var missing = rule == lr_none();
    if missing {
        return;
    }
    var first = &value.states.data[rule].first;
    var index: usize = 0;
    loop {
        var done = index == first.length;
        if done {
            return;
        }
        value.names.data[first.data[index]].start = true;
        index = index + 1;
    }
}

fn emission_declarations(value: SyntaxEmission*): void {
    var count = value.input.count;
    var ok = vector_reserve(SyntaxEmissionState, &value.states, count);
    if ok {} else {
        value.failed = true;
        return;
    }
    value.states.length = count;
    var bytes = count * sizeof(SyntaxEmissionState);
    fill(value.states.data, 0, bytes);
    emission_reachable(value);
    if value.failed {
        return;
    }
    emission_first(value);
    emission_starts(value, "GrammarDeclaration");
    emission_starts(value, "GrammarTokenDeclaration");
    emission_starts(value, "GrammarSkipDeclaration");
    emission_starts(value, "ImportDeclaration");
}

export fn syntax_emission_destroy(value: SyntaxEmission*): void {
    var missing = value == null;
    if missing {
        return;
    }
    var index: usize = 0;
    loop {
        var done = index == value.names.length;
        if done {
            break;
        }
        var entry = value.names.data[index];
        vector_dispose(u8, &entry.text);
        free(entry);
        index = index + 1;
    }
    index = 0;
    loop {
        var done = index == value.states.length;
        if done {
            break;
        }
        vector_dispose(usize, &value.states.data[index].first);
        index = index + 1;
    }
    vector_dispose(SyntaxEmissionEntry*, &value.names);
    vector_dispose(usize, &value.buckets);
    vector_dispose(SyntaxEmissionProduction, &value.productions);
    vector_dispose(SyntaxEmissionHelper, &value.helpers);
    vector_dispose(SyntaxEmissionState, &value.states);
    vector_dispose(usize, &value.queue);
    vector_dispose(usize, &value.terminals);
    vector_dispose(u8, &value.scratch);
    free(value);
}

export fn syntax_emit(input: SyntaxEmissionInput*): SyntaxEmission* {
    var value = alloc(SyntaxEmission, 1);
    var missing = value == null;
    if missing {
        return null;
    }
    fill(value, 0, sizeof(SyntaxEmission));
    value.input = input;
    emission_build(value);
    var ordinary = input.category == null;
    if value.failed {} else {
        if ordinary {
            emission_declarations(value);
        }
    }
    if value.failed {
        syntax_emission_destroy(value);
        return null;
    }
    value.input = null;
    return value;
}

export fn syntax_emission_name_count(value: SyntaxEmission*): usize {
    return value.names.length;
}

export fn syntax_emission_name(value: SyntaxEmission*, index: usize, out: SyntaxEmissionName*): void {
    var entry = value.names.data[index];
    out.text = node_text_get(&entry.text);
    out.length = entry.text.length;
    out.wrapper = null;
    var wrapper = entry.wrapper != lr_none();
    if wrapper {
        out.wrapper = emission_text(value, entry.wrapper);
    }
    out.literal = entry.literal;
    out.used = entry.used;
    out.declaration = entry.declaration;
    out.start = entry.start;
}

export fn syntax_emission_production_count(value: SyntaxEmission*): usize {
    return value.productions.length;
}

export fn syntax_emission_production(value: SyntaxEmission*, index: usize, out: SyntaxEmissionProduction*): void {
    copy(out, &value.productions.data[index], sizeof(SyntaxEmissionProduction));
}

export fn syntax_emission_helper_count(value: SyntaxEmission*): usize {
    return value.helpers.length;
}

export fn syntax_emission_helper(value: SyntaxEmission*, index: usize, out: SyntaxEmissionHelper*): void {
    copy(out, &value.helpers.data[index], sizeof(SyntaxEmissionHelper));
}

import tower;

// Replacement execution over shared parse entities. Rule slots and visitation
// sets are disposable indexes; capture holes refer to the compiled template tree.
extern fn entity_id(node: void*): usize;

extern fn entity_replace_child(parent: void*, index: usize, replacement: void*): bool;

extern fn entity_take_last_child(parent: void*): void*;

extern fn entity_child_name(parent: void*, index: usize): u8*;

struct SyntaxExpansionCapture {
    name: u8*;
    uses: usize;
    repeated: bool;
}

struct SyntaxExpansionRule {
    tree: void*;
    rule: u8*;
    category: u8*;
    start: usize;
    end: usize;
    captures: SyntaxExpansionCapture*;
    count: usize;
}

struct SyntaxExpansionInput {
    rules: SyntaxExpansionRule**;
    count: usize;
    match_kind: void*;
    host: void*;
}

struct SyntaxExpansionResult {
    root: void*;
    replacements: usize;
    generated_nodes: usize;
    copied_nodes: usize;
    error_offset: usize;
    error: vector(u8);
}

// Only provenance storage still crosses the native facade. Selection, traversal,
// recursion/output limits and copying decisions all live in this module.
extern fn syntax_expansion_history(node: void*): void*;

extern fn syntax_expansion_previous(trace: void*): void*;

extern fn syntax_expansion_trace(host: void*, rule: SyntaxExpansionRule*, invocation: void*): usize;

extern fn syntax_expansion_origin(host: void*, trace: usize, node: void*, template: void*, generated: bool): bool;

extern fn syntax_expansion_copy_origin(source: void*, destination: void*): bool;

struct ExpansionFrame {
    node: void*;
    next: usize;
    index: usize;
}

struct ExpansionWork {
    source: void*;
    parent: void*;
    role: u8*;
}

struct ExpansionCapture {
    node: void*;
    remaining: usize;
}

struct ExpansionState {
    input: SyntaxExpansionInput*;
    result: SyntaxExpansionResult*;
    normal: vector(usize);
    normal_count: usize;
    frames: vector(ExpansionFrame);
    work: vector(ExpansionWork);
    clones: vector(ExpansionWork);
    captures: vector(ExpansionCapture);
    items: vector(void*);
}

fn expansion_match(state: ExpansionState*, node: void*): ParserMatchData* {
    return lr_tree_match(node, state.input.match_kind);
}

fn expansion_error(state: ExpansionState*, text: u8*): bool {
    node_text_set(&state.result.error, text);
    return false;
}

fn expansion_append(state: ExpansionState*, text: u8*): void {
    var length = syntax_text_length(text);
    bytes_append(&state.result.error, text, length);
}

fn expansion_memory(state: ExpansionState*): bool {
    return expansion_error(state, "Unable to allocate replacement expansion storage");
}

fn expansion_same(left: u8*, right: u8*): bool {
    var left_length = syntax_text_length(left);
    var right_length = syntax_text_length(right);
    var order = syntax_bytes_compare(left, left_length, right, right_length);
    var same = order == 0;
    return same;
}

fn expansion_slot(key: usize, capacity: usize): usize {
    var hash = key * 2654435761;
    var upper = hash / 65536;
    hash = hash ^ upper;
    var mask = capacity - 1;
    hash = hash & mask;
    return hash;
}

fn expansion_normal(state: ExpansionState*, node: void*): bool {
    var empty = state.normal.length == 0;
    if empty {
        return false;
    }
    var key = entity_id(node) + 1;
    var slot = expansion_slot(key, state.normal.length);
    var mask = state.normal.length - 1;
    loop {
        var current = state.normal.data[slot];
        var found = current == key;
        if found {
            return true;
        }
        empty = current == 0;
        if empty {
            return false;
        }
        slot = slot + 1;
        slot = slot & mask;
    }
}

fn expansion_mark(state: ExpansionState*, node: void*): bool {
    var present = expansion_normal(state, node);
    if present {
        return true;
    }
    var needed = state.normal_count + 1;
    needed = needed * 2;
    var grow = needed >= state.normal.length;
    if grow {
        var capacity = state.normal.length * 2;
        var small = capacity < 32;
        if small {
            capacity = 32;
        }
        var next = alloc(usize, capacity);
        var failed = next == null;
        if failed {
            return expansion_memory(state);
        }
        var size = capacity * sizeof(usize);
        fill(next, 0, size);
        var index: usize = 0;
        var mask = capacity - 1;
        loop {
            var done = index == state.normal.length;
            if done {
                break;
            }
            var key = state.normal.data[index];
            var occupied = key != 0;
            if occupied {
                var slot = expansion_slot(key, capacity);
                loop {
                    var empty = next[slot] == 0;
                    if empty {
                        break;
                    }
                    slot = slot + 1;
                    slot = slot & mask;
                }
                next[slot] = key;
            }
            index = index + 1;
        }
        free(state.normal.data);
        state.normal.data = next;
        state.normal.length = capacity;
        state.normal.capacity = capacity;
    }
    var key = entity_id(node) + 1;
    var slot = expansion_slot(key, state.normal.length);
    var mask = state.normal.length - 1;
    loop {
        var empty = state.normal.data[slot] == 0;
        if empty {
            state.normal.data[slot] = key;
            state.normal_count = state.normal_count + 1;
            return true;
        }
        slot = slot + 1;
        slot = slot & mask;
    }
}

fn expansion_push_frame(state: ExpansionState*, node: void*, index: usize): bool {
    var count = state.frames.length;
    var needed = count + 1;
    var ok = vector_reserve(ExpansionFrame, &state.frames, needed);
    if ok {
        state.frames.data[count].node = node;
        state.frames.data[count].next = 0;
        state.frames.data[count].index = index;
        state.frames.length = needed;
        return true;
    }
    return expansion_memory(state);
}

fn expansion_push_work(state: ExpansionState*, work: vector(ExpansionWork)*, source: void*, parent: void*, role: u8*): bool {
    var count = work.length;
    var needed = count + 1;
    var ok = vector_reserve(ExpansionWork, work, needed);
    if ok {
        work.data[count].source = source;
        work.data[count].parent = parent;
        work.data[count].role = role;
        work.length = needed;
        return true;
    }
    return expansion_memory(state);
}

fn expansion_children(state: ExpansionState*, work: vector(ExpansionWork)*, source: void*, parent: void*): bool {
    var index = entity_child_count(source);
    loop {
        var done = index == 0;
        if done {
            return true;
        }
        index = index - 1;
        var child = entity_child_at(source, index);
        var role = entity_child_name(source, index);
        var ok = expansion_push_work(state, work, child, parent, role);
        if ok {} else {
            return false;
        }
    }
}

fn expansion_copy_node(state: ExpansionState*, source: void*, copied: bool): void* {
    var count = state.result.generated_nodes + state.result.copied_nodes;
    var limit = count >= 65536;
    if limit {
        expansion_error(state, "Replacement output limit exceeded (65536 nodes)");
        return null;
    }
    var node = entity_create_related(source);
    var ok = node != null;
    if ok {
        var component = entity_component_add(node, state.input.match_kind);
        var data = bits(ParserMatchData*, entity_component_data(component));
        ok = data != null;
        if ok {
            node_payload_init(4, bits(void*, data));
            var from = expansion_match(state, source);
            data.id = from.id;
            data.rule = from.rule;
            data.start = from.start;
            data.length = from.length;
            ok = node_match_set_label(data, node_text_get(&from.label));
            if ok {
                ok = syntax_expansion_copy_origin(source, node);
            }
        }
        if ok {
            if copied {
                state.result.copied_nodes = state.result.copied_nodes + 1;
            } else {
                state.result.generated_nodes = state.result.generated_nodes + 1;
            }
            return node;
        }
        entity_release(node);
    }
    expansion_memory(state);
    return null;
}

// Cloning and marking are one traversal, replacing the former clone plus a
// second walk to register every cloned descendant as already expanded.
fn expansion_copy_tree(state: ExpansionState*, source: void*): void* {
    var root = expansion_copy_node(state, source, true);
    var missing = root == null;
    if missing {
        return null;
    }
    state.clones.length = 0;
    var ok = expansion_mark(state, root);
    if ok {
        ok = expansion_children(state, &state.clones, source, root);
    }
    loop {
        if ok {} else {
            entity_release(root);
            return null;
        }
        var empty = state.clones.length == 0;
        if empty {
            return root;
        }
        state.clones.length = state.clones.length - 1;
        var work: ExpansionWork;
        copy(&work, &state.clones.data[state.clones.length], sizeof(ExpansionWork));
        var node = expansion_copy_node(state, work.source, true);
        ok = node != null;
        if ok {
            ok = expansion_mark(state, node);
            if ok {
                ok = entity_attach(node, work.parent, work.role);
                if ok {} else {
                    expansion_memory(state);
                }
            }
            if ok {
                ok = expansion_children(state, &state.clones, work.source, node);
            }
            entity_release(node);
        }
    }
}

fn expansion_splice(state: ExpansionState*, trace: usize, node: void*, work: ExpansionWork*): bool {
    var ok = syntax_expansion_origin(state.input.host, trace, node, work.source, false);
    if ok {
        ok = entity_attach(node, work.parent, work.role);
    }
    if ok {
        return true;
    }
    return expansion_memory(state);
}

fn expansion_hole(state: ExpansionState*, rule: SyntaxExpansionRule*, trace: usize, work: ExpansionWork*): bool {
    var data = expansion_match(state, work.source);
    var index = data.id - 3145728;
    var invalid = convert(usize, index) >= rule.count;
    if invalid {
        return expansion_error(state, "Invalid replacement capture index");
    }
    var capture = &state.captures.data[index];
    var unused = capture.remaining == 0;
    if unused {
        return expansion_error(state, "Invalid replacement capture use count");
    }
    capture.remaining = capture.remaining - 1;
    var repeated = capture.remaining != 0;
    var value: void*;
    if repeated {
        value = expansion_copy_tree(state, capture.node);
    } else {
        value = capture.node;
        entity_retain(value);
        entity_attach(value, null, null);
    }
    var missing = value == null;
    if missing {
        return false;
    }
    var ok = true;
    if rule.captures[index].repeated {
        var count = entity_child_count(value);
        var named = work.role != null;
        if named {
            named = *work.role != 0;
        }
        var many = count > 1;
        if named {
            if many {
                entity_release(value);
                return expansion_error(state, "List capture requires a repeated destination");
            }
        }
        state.items.length = 0;
        ok = vector_reserve(void*, &state.items, count);
        if ok {
            loop {
                var empty = count == 0;
                if empty {
                    break;
                }
                var item = entity_take_last_child(value);
                state.items.data[state.items.length] = item;
                state.items.length = state.items.length + 1;
                count = count - 1;
            }
            loop {
                var empty = state.items.length == 0;
                if empty {
                    break;
                }
                state.items.length = state.items.length - 1;
                var item = state.items.data[state.items.length];
                if ok {
                    ok = expansion_splice(state, trace, item, work);
                }
                entity_release(item);
            }
        } else {
            expansion_memory(state);
        }
    } else {
        ok = expansion_splice(state, trace, value, work);
    }
    entity_release(value);
    return ok;
}

fn expansion_instantiate(state: ExpansionState*, rule: SyntaxExpansionRule*, invocation: void*, captured: void*): void* {
    var previous = syntax_expansion_history(invocation);
    var depth: usize = 0;
    loop {
        var done = previous == null;
        if done {
            break;
        }
        depth = depth + 1;
        var limit = depth >= 256;
        if limit {
            expansion_error(state, "Replacement recursion limit exceeded (256 expansions in one chain)");
            return null;
        }
        previous = syntax_expansion_previous(previous);
    }
    var ok = vector_reserve(ExpansionCapture, &state.captures, rule.count);
    if ok {} else {
        expansion_memory(state);
        return null;
    }
    var index: usize = 0;
    loop {
        var done = index == rule.count;
        if done {
            break;
        }
        var member = entity_member_index(captured, rule.captures[index].name);
        var node = entity_child_at(captured, member);
        var missing = node == null;
        if missing {
            expansion_error(state, "Missing replacement capture: $");
            expansion_append(state, rule.captures[index].name);
            return null;
        }
        state.captures.data[index].node = node;
        state.captures.data[index].remaining = rule.captures[index].uses;
        index = index + 1;
    }
    var trace = syntax_expansion_trace(state.input.host, rule, invocation);
    var container = entity_create_related(invocation);
    var missing = container == null;
    if missing {
        expansion_memory(state);
        return null;
    }
    state.work.length = 0;
    ok = expansion_push_work(state, &state.work, rule.tree, container, null);
    var span = expansion_match(state, invocation);
    loop {
        if ok {} else {
            entity_release(container);
            return null;
        }
        var empty = state.work.length == 0;
        if empty {
            break;
        }
        state.work.length = state.work.length - 1;
        var work: ExpansionWork;
        copy(&work, &state.work.data[state.work.length], sizeof(ExpansionWork));
        var data = expansion_match(state, work.source);
        var hole = data.id >= 3145728;
        if hole {
            hole = data.label.length != 0;
            if hole {
                hole = data.label.data[0] == 36;
            }
        }
        if hole {
            ok = expansion_hole(state, rule, trace, &work);
            continue;
        }
        var node = expansion_copy_node(state, work.source, false);
        ok = node != null;
        if ok {
            var made = expansion_match(state, node);
            made.start = span.start;
            made.length = span.length;
            ok = syntax_expansion_origin(state.input.host, trace, node, work.source, true);
            if ok {
                ok = entity_attach(node, work.parent, work.role);
            }
            if ok {
                ok = expansion_children(state, &state.work, work.source, node);
            } else {
                expansion_memory(state);
            }
            entity_release(node);
        }
    }
    var count = entity_child_count(container);
    var single = count == 1;
    var result: void* = null;
    if single {
        result = entity_take_last_child(container);
    } else {
        expansion_error(state, "Replacement must produce one root");
    }
    entity_release(container);
    return result;
}

fn expansion_rule(state: ExpansionState*, node: void*): SyntaxExpansionRule* {
    var data = expansion_match(state, node);
    var valid = data.rule < state.input.count;
    if valid {
        return state.input.rules[data.rule];
    }
    return null;
}

fn expansion_run(state: ExpansionState*): bool {
    var ok = expansion_push_frame(state, state.result.root, 0);
    loop {
        if ok {} else {
            return false;
        }
        var empty = state.frames.length == 0;
        if empty {
            return true;
        }
        var top = state.frames.length - 1;
        var frame = &state.frames.data[top];
        var done = expansion_normal(state, frame.node);
        if done {
            state.frames.length = top;
            continue;
        }
        var count = entity_child_count(frame.node);
        var children = frame.next < count;
        if children {
            var index = frame.next;
            frame.next = index + 1;
            var node = entity_child_at(frame.node, index);
            ok = expansion_push_frame(state, node, index);
            continue;
        }
        var root = expansion_match(state, frame.node);
        var category = node_text_get(&root.label);
        var candidate = frame.node;
        var rule: SyntaxExpansionRule*;
        loop {
            rule = expansion_rule(state, candidate);
            var found = rule != null;
            if found {
                found = expansion_same(rule.category, category);
                if found {
                    break;
                }
            }
            rule = null;
            var count = entity_child_count(candidate);
            var single = count == 1;
            if single {} else {
                break;
            }
            var next = entity_child_at(candidate, 0);
            var data = expansion_match(state, next);
            var leaf = data.rule == lr_none();
            if leaf {
                break;
            }
            candidate = next;
        }
        var missing = rule == null;
        if missing {
            var deferred = expansion_rule(state, frame.node);
            var found = deferred != null;
            if found {
                var destination = false;
                var index = top;
                loop {
                    var end = index == 0;
                    if end {
                        break;
                    }
                    index = index - 1;
                    var parent = state.frames.data[index].node;
                    var count = entity_child_count(parent);
                    var single = count == 1;
                    if single {} else {
                        break;
                    }
                    var data = expansion_match(state, parent);
                    destination = expansion_same(deferred.category, node_text_get(&data.label));
                    if destination {
                        break;
                    }
                }
                if destination {} else {
                    state.result.error_offset = root.start;
                    expansion_error(state, "Replacement for ");
                    expansion_append(state, deferred.rule);
                    expansion_append(state, " requires a ");
                    expansion_append(state, deferred.category);
                    expansion_append(state, " destination");
                    return false;
                }
            }
            ok = expansion_mark(state, frame.node);
            state.frames.length = top;
            continue;
        }
        state.result.error_offset = root.start;
        var limit = state.result.replacements >= 4096;
        state.result.replacements = state.result.replacements + 1;
        if limit {
            return expansion_error(state, "Replacement step limit exceeded (4096)");
        }
        var expanded = expansion_instantiate(state, rule, frame.node, candidate);
        var failed = expanded == null;
        if failed {
            expansion_append(state, " while replacing ");
            expansion_append(state, rule.rule);
            return false;
        }
        var first = top == 0;
        if first {
            entity_release(state.result.root);
            state.result.root = expanded;
        } else {
            var previous = top - 1;
            var parent = state.frames.data[previous].node;
            ok = entity_replace_child(parent, frame.index, expanded);
            entity_release(expanded);
            if ok {} else {
                return expansion_error(state, "Unable to replace syntax child");
            }
        }
        frame.node = expanded;
        frame.next = 0;
    }
}

export fn syntax_expand(input: SyntaxExpansionInput*, result: SyntaxExpansionResult*): bool {
    var state: ExpansionState;
    fill(&state, 0, sizeof(ExpansionState));
    state.input = input;
    state.result = result;
    var ok = expansion_run(&state);
    vector_dispose(usize, &state.normal);
    vector_dispose(ExpansionFrame, &state.frames);
    vector_dispose(ExpansionWork, &state.work);
    vector_dispose(ExpansionWork, &state.clones);
    vector_dispose(ExpansionCapture, &state.captures);
    vector_dispose(void*, &state.items);
    return ok;
}

export fn syntax_expansion_result_dispose(result: SyntaxExpansionResult*): void {
    vector_dispose(u8, &result.error);
}

import tower;

// A revision's disposable lexical index. Patterns and text borrow its immutable
// declaration entities; declarations remain the authoritative grammar nodes.
struct LexiconToken {
    table: LexerTable*;
    id: u32;
    style: u8*;
    skipped: bool;
    contextual: bool;
    identifier: bool;
}

struct LexiconLiteral {
    text: u8*;
    length: usize;
    id: u32;
    word: bool;
    declaration: bool;
}

struct SyntaxLexicon {
    tokens: vector(LexiconToken);
    literals: vector(LexiconLiteral);
    starts: vector(LexiconLiteral);
}

struct LexiconChoice {
    length: usize;
    id: u32;
    style: u8*;
    skipped: bool;
    checks: usize;
}

fn lexicon_letter(byte: u8): bool {
    var valid = byte >= 97;
    if valid {
        valid = byte <= 122;
    }
    if valid {
        return true;
    }
    valid = byte >= 65;
    if valid {
        valid = byte <= 90;
    }
    if valid {
        return true;
    }
    valid = byte == 95;
    return valid;
}

fn lexicon_word(text: u8*, length: usize): bool {
    var empty = length == 0;
    if empty {
        return false;
    }
    var valid = lexicon_letter(text[0]);
    if valid {} else {
        return false;
    }
    var index: usize = 1;
    loop {
        var done = index == length;
        if done {
            return true;
        }
        var byte = text[index];
        valid = lexicon_letter(byte);
        if valid {} else {
            valid = byte >= 48;
            if valid {
                valid = byte <= 57;
            }
            if valid {} else {
                return false;
            }
        }
        index = index + 1;
    }
}

fn lexicon_prefix(source: u8*, length: usize, start: usize, text: u8*, count: usize): bool {
    var invalid = start > length;
    if invalid {
        return false;
    }
    var remaining = length - start;
    invalid = count > remaining;
    if invalid {
        return false;
    }
    var index: usize = 0;
    loop {
        var done = index == count;
        if done {
            return true;
        }
        var at = start + index;
        var different = source[at] != text[index];
        if different {
            return false;
        }
        index = index + 1;
    }
}

export fn lexicon_create(): SyntaxLexicon* {
    var value = alloc(SyntaxLexicon, 1);
    var present = value != null;
    if present {
        fill(value, 0, sizeof(SyntaxLexicon));
    }
    return value;
}

export fn lexicon_destroy(value: SyntaxLexicon*): void {
    var missing = value == null;
    if missing {
        return;
    }
    vector_dispose(LexiconToken, &value.tokens);
    vector_dispose(LexiconLiteral, &value.literals);
    vector_dispose(LexiconLiteral, &value.starts);
    free(value);
}

export fn lexicon_token(value: SyntaxLexicon*, table: LexerTable*, id: u32, style: u8*, skipped: bool, contextual: bool, identifier: bool): bool {
    var entry: LexiconToken;
    entry.table = table;
    entry.id = id;
    entry.style = style;
    entry.skipped = skipped;
    entry.contextual = contextual;
    entry.identifier = identifier;
    return lr_append(LexiconToken, &value.tokens, &entry);
}

export fn lexicon_literal(value: SyntaxLexicon*, text: u8*, length: usize, id: u32, declaration: bool): bool {
    var literal: LexiconLiteral;
    literal.text = text;
    literal.length = length;
    literal.id = id;
    literal.word = lexicon_word(text, length);
    literal.declaration = declaration;
    return lr_append(LexiconLiteral, &value.literals, &literal);
}

export fn lexicon_start(value: SyntaxLexicon*, text: u8*, length: usize): bool {
    var literal: LexiconLiteral;
    fill(&literal, 0, sizeof(LexiconLiteral));
    literal.text = text;
    literal.length = length;
    return lr_append(LexiconLiteral, &value.starts, &literal);
}

fn lexicon_choice_init(choice: LexiconChoice*): void {
    fill(choice, 0, sizeof(LexiconChoice));
    choice.id = 4294967294;
    choice.style = "";
}

fn lexicon_accepts(runtime: LRRuntime*, state: usize, id: u32, choice: LexiconChoice*): bool {
    var missing = runtime == null;
    if missing {
        return false;
    }
    var invalid = state >= runtime.states.length;
    if invalid {
        return false;
    }
    choice.checks = choice.checks + 1;
    var action: LRAction;
    return lr_runtime_action(runtime, state, id, &action);
}

// Longest match, then declaration order. Contextual ties prefer an accepted
// token; equal-length literals win. The exact same path serves diagnostic peeks.
export fn lexicon_choose(value: SyntaxLexicon*, source: u8*, length: usize, start: usize, declaration: bool, runtime: LRRuntime*, state: usize, choice: LexiconChoice*): void {
    lexicon_choice_init(choice);
    var index: usize = 0;
    loop {
        var done = index == value.tokens.length;
        if done {
            break;
        }
        var entry = &value.tokens.data[index];
        var eligible = true;
        if entry.contextual {
            eligible = lexicon_accepts(runtime, state, entry.id, choice);
        }
        if eligible {
            var count = lex_table_match(entry.table, source, length, start);
            var selected = count > choice.length;
            if selected {} else {
                var tie = count != 0;
                if tie {
                    tie = count == choice.length;
                }
                if tie {
                    if entry.contextual {
                        selected = lexicon_accepts(runtime, state, choice.id, choice);
                        selected = selected == false;
                    }
                }
            }
            if selected {
                choice.length = count;
                choice.id = entry.id;
                choice.style = entry.style;
                choice.skipped = entry.skipped;
            }
        }
        index = index + 1;
    }
    index = 0;
    loop {
        var done = index == value.literals.length;
        if done {
            break;
        }
        var literal = &value.literals.data[index];
        var eligible = declaration == false;
        if literal.declaration {
            eligible = true;
        }
        if eligible {} else {
            eligible = lexicon_accepts(runtime, state, literal.id, choice);
        }
        if eligible {
            eligible = literal.length >= choice.length;
            if eligible {
                eligible = lexicon_prefix(source, length, start, literal.text, literal.length);
            }
            if eligible {
                choice.length = literal.length;
                choice.id = literal.id;
                choice.style = "operator";
                if literal.word {
                    choice.style = "keyword";
                }
                choice.skipped = false;
            }
        }
        index = index + 1;
    }
}

export fn lexicon_skip(value: SyntaxLexicon*, source: u8*, length: usize, start: usize, choice: LexiconChoice*): void {
    lexicon_choice_init(choice);
    var index: usize = 0;
    loop {
        var done = index == value.tokens.length;
        if done {
            return;
        }
        var entry = &value.tokens.data[index];
        if entry.skipped {
            var count = lex_table_match(entry.table, source, length, start);
            var selected = count > choice.length;
            if selected {
                choice.length = count;
                choice.id = entry.id;
                choice.style = entry.style;
                choice.skipped = true;
            }
        }
        index = index + 1;
    }
}

export fn lexicon_identifier(value: SyntaxLexicon*, source: u8*, length: usize, start: usize): usize {
    var index: usize = 0;
    loop {
        var done = index == value.tokens.length;
        if done {
            return 0;
        }
        var entry = &value.tokens.data[index];
        if entry.identifier {
            return lex_table_match(entry.table, source, length, start);
        }
        index = index + 1;
    }
}

export fn lexicon_declaration(value: SyntaxLexicon*, source: u8*, length: usize, start: usize): bool {
    var index: usize = 0;
    loop {
        var done = index == value.starts.length;
        if done {
            return false;
        }
        var keyword = &value.starts.data[index];
        var selected = lexicon_prefix(source, length, start, keyword.text, keyword.length);
        if selected {
            var position: usize = 0;
            loop {
                done = position == value.tokens.length;
                if done {
                    return true;
                }
                var entry = &value.tokens.data[position];
                var eligible = entry.skipped == false;
                if entry.contextual {
                    eligible = false;
                }
                if eligible {
                    var count = lex_table_match(entry.table, source, length, start);
                    var longer = count > keyword.length;
                    if longer {
                        break;
                    }
                }
                position = position + 1;
            }
        }
        index = index + 1;
    }
}

import tower;

// Grammar declarations augment the same entities used by syntax and foundation.
// Source entities are authoritative; lexer tables and comparison work lists are derived.
extern fn entity_retain(node: void*): usize;

struct SyntaxPattern {
    references: usize;
    table: LexerTable*;
    grammar: void*;
}

struct SyntaxNode {
    kind: u32;
    name: vector(u8);
    text: vector(u8);
    capture: vector(u8);
    style: vector(u8);
    source: SyntaxSource*;
    literal: bool;
    append: bool;
    contextual: bool;
    terminal_set: bool;
    repetition: u8;
    items: vector(void*);
    replacement: void*;
    comments: vector(vector(u8));
    start: usize;
    end: usize;
    compiled: SyntaxPattern*;
}

export fn syntax_pattern_size(): usize {
    return sizeof(SyntaxPattern);
}

export fn syntax_pattern_retain(value: SyntaxPattern*): void {
    var present = value != null;
    if present {
        value.references = value.references + 1;
    }
}

export fn syntax_pattern_release(value: SyntaxPattern*): void {
    var missing = value == null;
    if missing {
        return;
    }
    value.references = value.references - 1;
    var unused = value.references == 0;
    if unused {
        lex_table_destroy(value.table);
        var tree = value.grammar != null;
        if tree {
            entity_release(value.grammar);
        }
        free(value);
    }
}

export fn syntax_pattern_create(grammar: void*): SyntaxPattern* {
    var value = alloc(SyntaxPattern, 1);
    var failed = value == null;
    if failed {
        return null;
    }
    fill(value, 0, sizeof(SyntaxPattern));
    value.references = 1;
    value.table = lex_table_create();
    failed = value.table == null;
    if failed {
        syntax_pattern_release(value);
        return null;
    }
    var tree = grammar != null;
    if tree {
        entity_retain(grammar);
    }
    value.grammar = grammar;
    return value;
}

export fn syntax_node_size(): usize {
    return sizeof(SyntaxNode);
}

export fn syntax_node_init(value: SyntaxNode*): void {
    fill(value, 0, sizeof(SyntaxNode));
    value.start = 0;
    value.start = value.start - 1;
    value.end = value.start;
}

export fn syntax_node_source(value: SyntaxNode*, source: SyntaxSource*): void {
    syntax_source_retain(source);
    syntax_source_release(value.source);
    value.source = source;
}

export fn syntax_node_pattern(value: SyntaxNode*, pattern: SyntaxPattern*): void {
    syntax_pattern_retain(pattern);
    syntax_pattern_release(value.compiled);
    value.compiled = pattern;
}

export fn syntax_node_replacement(value: SyntaxNode*, replacement: void*): void {
    var present = replacement != null;
    if present {
        entity_retain(replacement);
    }
    present = value.replacement != null;
    if present {
        entity_release(value.replacement);
    }
    value.replacement = replacement;
}

// Copy before growing the list: text may refer to an existing comment.
// On failure retain all existing entries and dispose the temporary copy.
export fn syntax_comments_push(comments: vector(vector(u8))*, text: u8*, length: usize): bool {
    var needed = length + 1;
    var overflow = needed == 0;
    if overflow {
        return false;
    }
    var count = comments.length + 1;
    overflow = count == 0;
    if overflow {
        return false;
    }
    var snapshot: vector(u8);
    vector_init(u8, &snapshot);
    var ok = vector_reserve(u8, &snapshot, needed);
    if ok {
        var nonempty = length != 0;
        if nonempty {
            copy(snapshot.data, text, length);
        }
        snapshot.data[length] = 0;
        snapshot.length = length;
        ok = vector_reserve(vector(u8), comments, count);
    }
    if ok {
        var target = &comments.data[comments.length];
        target.data = snapshot.data;
        target.length = snapshot.length;
        target.capacity = snapshot.capacity;
        comments.length = count;
    } else {
        vector_dispose(u8, &snapshot);
    }
    return ok;
}

export fn syntax_node_dispose(value: SyntaxNode*): void {
    vector_dispose(u8, &value.name);
    vector_dispose(u8, &value.text);
    vector_dispose(u8, &value.capture);
    vector_dispose(u8, &value.style);
    vector_dispose(void*, &value.items);
    var index: usize = 0;
    loop {
        var done = index == value.comments.length;
        if done {
            break;
        }
        vector_dispose(u8, &value.comments.data[index]);
        index = index + 1;
    }
    vector_dispose(vector(u8), &value.comments);
    syntax_node_source(value, null);
    syntax_node_pattern(value, null);
    syntax_node_replacement(value, null);
}

fn syntax_text_equal(left: vector(u8)*, right: vector(u8)*): bool {
    var different = left.length != right.length;
    if different {
        return false;
    }
    var index: usize = 0;
    loop {
        var done = index == left.length;
        if done {
            return true;
        }
        different = left.data[index] != right.data[index];
        if different {
            return false;
        }
        index = index + 1;
    }
}

struct SyntaxComparison {
    left: void*;
    right: void*;
}

fn syntax_comparison_push(pending: vector(SyntaxComparison)*, left: void*, right: void*): bool {
    var count = pending.length + 1;
    var overflow = count == 0;
    if overflow {
        return false;
    }
    var ok = vector_reserve(SyntaxComparison, pending, count);
    if ok {
        pending.data[pending.length].left = left;
        pending.data[pending.length].right = right;
        pending.length = count;
    }
    return ok;
}

// 1 equal, 0 different, -1 allocation failure. Metadata and cache addresses do
// not affect parser identity. Template coordinates matter only when requested.
export fn syntax_nodes_equal(left: void*, right: void*, kind: void*, locations: bool): i32 {
    var identical = left == right;
    if identical {
        return 1;
    }
    var pending: vector(SyntaxComparison);
    vector_init(SyntaxComparison, &pending);
    var ok = syntax_comparison_push(&pending, left, right);
    var result: i32 = 1;
    loop {
        var failed = ok == false;
        if failed {
            result = -1;
            break;
        }
        var done = pending.length == 0;
        if done {
            break;
        }
        pending.length = pending.length - 1;
        left = pending.data[pending.length].left;
        right = pending.data[pending.length].right;
        var same = left == right;
        if same {
            continue;
        }
        var missing = left == null;
        if missing {
            result = 0;
            break;
        }
        missing = right == null;
        if missing {
            result = 0;
            break;
        }
        var component = entity_component_get(left, kind);
        var x = bits(SyntaxNode*, entity_component_data(component));
        component = entity_component_get(right, kind);
        var y = bits(SyntaxNode*, entity_component_data(component));
        missing = x == null;
        if missing {
            result = 0;
            break;
        }
        missing = y == null;
        if missing {
            result = 0;
            break;
        }
        same = x.kind == y.kind;
        if same {
            same = syntax_text_equal(&x.name, &y.name);
        }
        if same {
            same = syntax_text_equal(&x.text, &y.text);
        }
        if same {
            same = syntax_text_equal(&x.capture, &y.capture);
        }
        if same {
            same = syntax_text_equal(&x.style, &y.style);
        }
        if same {
            same = x.literal == y.literal;
        }
        if same {
            same = x.append == y.append;
        }
        if same {
            same = x.contextual == y.contextual;
        }
        if same {
            same = x.terminal_set == y.terminal_set;
        }
        if same {
            same = x.repetition == y.repetition;
        }
        if same {
            same = x.items.length == y.items.length;
        }
        if locations {
            var template_node = x.kind == 6;
            if template_node {
                if same {
                    same = x.start == y.start;
                }
                if same {
                    same = x.end == y.end;
                }
            }
        }
        var different = same == false;
        if different {
            result = 0;
            break;
        }
        var index: usize = 0;
        loop {
            var done_items = index == x.items.length;
            if done_items {
                break;
            }
            ok = syntax_comparison_push(&pending, x.items.data[index], y.items.data[index]);
            var failed_item = ok == false;
            if failed_item {
                break;
            }
            index = index + 1;
        }
        if ok {
            ok = syntax_comparison_push(&pending, x.replacement, y.replacement);
        }
    }
    vector_dispose(SyntaxComparison, &pending);
    return result;
}

// Temporary native ABI verification under each explicit target layout.
export fn syntax_node_offset(field: usize): usize {
    var value: SyntaxNode;
    var base = bits(usize, &value);
    var address = base;
    var selected: bool;
    selected = field == 0;
    if selected {
        address = bits(usize, &value.kind);
    }
    selected = field == 1;
    if selected {
        address = bits(usize, &value.name);
    }
    selected = field == 2;
    if selected {
        address = bits(usize, &value.text);
    }
    selected = field == 3;
    if selected {
        address = bits(usize, &value.capture);
    }
    selected = field == 4;
    if selected {
        address = bits(usize, &value.style);
    }
    selected = field == 5;
    if selected {
        address = bits(usize, &value.source);
    }
    selected = field == 6;
    if selected {
        address = bits(usize, &value.literal);
    }
    selected = field == 7;
    if selected {
        address = bits(usize, &value.append);
    }
    selected = field == 8;
    if selected {
        address = bits(usize, &value.contextual);
    }
    selected = field == 9;
    if selected {
        address = bits(usize, &value.terminal_set);
    }
    selected = field == 10;
    if selected {
        address = bits(usize, &value.repetition);
    }
    selected = field == 11;
    if selected {
        address = bits(usize, &value.items);
    }
    selected = field == 12;
    if selected {
        address = bits(usize, &value.replacement);
    }
    selected = field == 13;
    if selected {
        address = bits(usize, &value.comments);
    }
    selected = field == 14;
    if selected {
        address = bits(usize, &value.start);
    }
    selected = field == 15;
    if selected {
        address = bits(usize, &value.end);
    }
    selected = field == 16;
    if selected {
        address = bits(usize, &value.compiled);
    }
    var offset = address - base;
    return offset;
}

import tower;

// Interpret declaration parse trees on their existing shared entities.
// Temporary native registration supplies component kinds; all reading is Tower.
extern fn entity_component_add(node: void*, kind: void*): void*;

extern fn bytes_assign_text(value: vector(u8)*, source: u8*, length: usize): bool;

extern fn bytes_append(value: vector(u8)*, source: u8*, length: usize): bool;

struct SyntaxReader {
    source: SyntaxSource*;
    match_kind: void*;
    syntax_kind: void*;
    error: u8*;
    detail: u8*;
    detail_length: usize;
    suffix: u8*;
}

fn syntax_reader_fail(reader: SyntaxReader*, message: u8*): bool {
    var first = reader.error == null;
    if first {
        reader.error = message;
    }
    return false;
}

fn syntax_reader_detail(reader: SyntaxReader*, message: u8*, detail: u8*, length: usize, suffix: u8*): bool {
    var first = reader.error == null;
    if first {
        reader.detail = detail;
        reader.detail_length = length;
        reader.suffix = suffix;
    }
    return syntax_reader_fail(reader, message);
}

fn syntax_reader_ok(reader: SyntaxReader*, ok: bool): bool {
    if ok {
        return true;
    }
    return syntax_reader_fail(reader, "Unable to allocate grammar declaration");
}

fn syntax_text_length(text: u8*): usize {
    var length: usize = 0;
    loop {
        var done = text[length] == 0;
        if done {
            return length;
        }
        length = length + 1;
    }
}

fn syntax_reader_finish(reader: SyntaxReader*, error: vector(u8)*): bool {
    var success = reader.error == null;
    if success {
        return true;
    }
    var ok = node_text_set(error, reader.error);
    if ok {
        ok = bytes_append(error, reader.detail, reader.detail_length);
    }
    var suffix = reader.suffix != null;
    if suffix {
        if ok {
            var length = syntax_text_length(reader.suffix);
            ok = bytes_append(error, reader.suffix, length);
        }
    }
    if ok {
        ok = foundation_name_append(error, 0);
        if ok {
            error.length = error.length - 1;
        }
    }
    if ok {} else {
        vector_dispose(u8, error);
    }
    return false;
}

fn syntax_reader_member(node: void*, name: u8*): void* {
    var missing = node == null;
    if missing {
        return null;
    }
    var index = entity_member_index(node, name);
    return entity_child_at(node, index);
}

fn syntax_reader_required(reader: SyntaxReader*, node: void*, name: u8*): void* {
    var result = syntax_reader_member(node, name);
    var missing = result == null;
    if missing {
        var length = syntax_text_length(name);
        syntax_reader_detail(reader, "Malformed bedrock tree: missing capture '", name, length, "'");
    }
    return result;
}

