            } else {
                selected = character == 9;
                if selected {
                    replacement_text(state, "\\t");
                } else {
                    selected = character == 92;
                    if selected {
                        replacement_text(state, "\\\\");
                    } else {
                        selected = character == 34;
                        if selected {
                            replacement_text(state, "\\\"");
                        } else {
                            replacement_append(state, &character, 1);
                        }
                    }
                }
            }
        }
        index = index + 1;
    }
    var truncated = end < last;
    if truncated {
        replacement_text(state, "...");
    }
    replacement_text(state, "\"");
}

fn replacement_invalid(state: ReplacementPlanState*, name: u8*, body: SyntaxNode*, grammar_failed: bool): void {
    replacement_text(state, "Replacement for ");
    replacement_text(state, name);
    replacement_text(state, " must produce ");
    var single = state.tried.length == 1;
    if single {
        replacement_text(state, "a valid ");
        var first = state.tried.data[0];
        replacement_text(state, state.plan.rules[first].name);
    } else {
        replacement_text(state, "one of these syntax categories: ");
        var index: usize = 0;
        loop {
            var done = index == state.tried.length;
            if done {
                break;
            }
            var separator = index != 0;
            if separator {
                replacement_text(state, ", ");
            }
            var target = state.tried.data[index];
            replacement_text(state, state.plan.rules[target].name);
            index = index + 1;
        }
    }
    replacement_text(state, ". ");
    if grammar_failed {
        replacement_text(state, "Could not validate ");
    }
    replacement_excerpt(state, &body.text);
    if grammar_failed {
        replacement_text(state, ".");
    } else {
        if single {
            replacement_text(state, " is not a valid ");
            var first = state.tried.data[0];
            replacement_text(state, state.plan.rules[first].name);
            replacement_text(state, ".");
        } else {
            replacement_text(state, " is not valid in any of these categories.");
        }
    }
    replacement_text(state, "\n");
    replacement_append(state, state.original.data, state.original.length);
}

fn replacement_prepare_one(state: ReplacementPlanState*, index: usize, alternative: usize): bool {
    var rule = &state.plan.rules[index];
    var source = rule.alternatives[alternative];
    var sequence = replacement_node(state, source);
    var body = replacement_node(state, sequence.replacement);
    syntax_replacement_begin(state.plan.host, rule.name, source, body.start, body.end);
    var item: usize = 0;
    loop {
        var done = item == sequence.items.length;
        if done {
            break;
        }
        var entity = sequence.items.data[item];
        var term = replacement_node(state, entity);
        var captured = term.capture.length != 0;
        if captured {
            syntax_replacement_capture(state.plan.host, node_text_get(&term.capture), entity);
        }
        item = item + 1;
    }
    state.pending.length = 0;
    state.tried.length = 0;
    state.original.length = 0;
    state.plan.offset = body.start;
    state.epoch = state.epoch + 1;
    var grammar_failed = false;
    var ok = replacement_queue(state, index);
    var cursor: usize = 0;
    loop {
        if ok {} else {
            return false;
        }
        var done = cursor == state.pending.length;
        if done {
            replacement_invalid(state, rule.name, body, grammar_failed);
            return false;
        }
        var end = state.pending.length;
        var selected = false;
        loop {
            done = cursor == end;
            if done {
                break;
            }
            var category = state.pending.data[cursor];
            cursor = cursor + 1;
            var visited = state.rules.data[category].visited == state.epoch;
            if visited {
                continue;
            }
            state.rules.data[category].visited = state.epoch;
            state.allocated = vector_push(usize, &state.tried, category);
            if state.allocated {} else {
                return false;
            }
            var status = syntax_replacement_attempt(state.plan.host, state.plan.rules[category].name);
            var success = status == 1;
            if success {
                if selected {
                    replacement_text(state, "Ambiguous replacement destination for ");
                    replacement_text(state, rule.name);
                    replacement_text(state, "; attach the handler to its destination rule");
                    state.plan.offset = body.start;
                    return false;
                }
                syntax_replacement_select(state.plan.host);
                selected = true;
            } else {
                var first_error = state.original.length == 0;
                if first_error {
                    state.allocated = node_text_set(&state.original, syntax_replacement_diagnostic(state.plan.host));
                    if state.allocated {} else {
                        return false;
                    }
                    state.plan.offset = syntax_replacement_offset(state.plan.host);
                }
            }
            var conflict = status == 2;
            if conflict {
                grammar_failed = true;
            }
            var parents = &state.rules.data[category].parents;
            var parent: usize = 0;
            loop {
                done = parent == parents.length;
                if done {
                    break;
                }
                ok = replacement_queue(state, parents.data[parent]);
                if ok {} else {
                    return false;
                }
                parent = parent + 1;
            }
        }
        if selected {
            syntax_replacement_commit(state.plan.host, alternative);
            return true;
        }
    }
}

fn replacement_prepare_all(state: ReplacementPlanState*): bool {
    var any = false;
    var scan: usize = 0;
    loop {
        var done = scan == state.plan.count;
        if done {
            break;
        }
        var rule = &state.plan.rules[scan];
        var alternative: usize = 0;
        loop {
            done = alternative == rule.count;
            if done {
                break;
            }
            var sequence = replacement_node(state, rule.alternatives[alternative]);
            any = sequence.replacement != null;
            if any {
                break;
            }
            alternative = alternative + 1;
        }
        if any {
            break;
        }
        scan = scan + 1;
    }
    if any {} else {
        return true;
    }
    state.allocated = vector_reserve(ReplacementRuleState, &state.rules, state.plan.count);
    if state.allocated {} else {
        return false;
    }
    var bytes = state.plan.count * sizeof(ReplacementRuleState);
    fill(state.rules.data, 0, bytes);
    state.rules.length = state.plan.count;
    var ok = replacement_reachable(state);
    if ok {
        ok = replacement_parents(state);
    }
    if ok {} else {
        return false;
    }
    var index: usize = 0;
    loop {
        var done = index == state.plan.count;
        if done {
            return true;
        }
        if state.rules.data[index].reachable {
            var rule = &state.plan.rules[index];
            var alternative: usize = 0;
            loop {
                done = alternative == rule.count;
                if done {
                    break;
                }
                var sequence = replacement_node(state, rule.alternatives[alternative]);
                var replacement = sequence.replacement != null;
                if replacement {
                    ok = replacement_prepare_one(state, index, alternative);
                    if ok {} else {
                        return false;
                    }
                }
                alternative = alternative + 1;
            }
        }
        index = index + 1;
    }
}

export fn syntax_replacements_prepare(plan: SyntaxReplacementPlan*): bool {
    var state: ReplacementPlanState;
    fill(&state, 0, sizeof(ReplacementPlanState));
    state.plan = plan;
    state.allocated = true;
    var ok = replacement_prepare_all(&state);
    var index: usize = 0;
    loop {
        var done = index == state.rules.length;
        if done {
            break;
        }
        vector_dispose(usize, &state.rules.data[index].parents);
        index = index + 1;
    }
    vector_dispose(ReplacementRuleState, &state.rules);
    vector_dispose(usize, &state.pending);
    vector_dispose(usize, &state.tried);
    vector_dispose(u8, &state.original);
    if state.allocated {} else {
        vector_dispose(u8, &plan.error);
    }
    return ok;
}

export fn syntax_replacements_dispose(plan: SyntaxReplacementPlan*): void {
    vector_dispose(u8, &plan.error);
}

import tower;

// Session token traversal uses the same data-driven lexer for declarations,
// ordinary code, diagnostic lookahead and typed replacement captures.
struct SyntaxScanInput {
    lexicon: SyntaxLexicon*;
    source: u8*;
    size: usize;
    cursor: usize;
    revision: usize;
    declaration: bool;
    bootstrapping: bool;
    runtime: LRRuntime*;
    state: usize;
    highlights: void*;
    context: void*;
    match_kind: void*;
    replacement: bool;
    captures: SyntaxTemplateCapture*;
    count: usize;
    base: usize;
}

struct SyntaxScanResult {
    id: u32;
    start: usize;
    length: usize;
    checks: usize;
    error: u8*;
    message: vector(u8);
}

extern fn syntax_scan_highlight(host: void*, start: usize, end: usize, revision: usize, style: u8*, id: u32, skipped: bool): void;

fn scan_choice(input: SyntaxScanInput*, choice: LexiconChoice*): void {
    lexicon_choose(input.lexicon, input.source, input.size, input.cursor, input.declaration, input.runtime, input.state, choice);
}

fn scan_highlight(input: SyntaxScanInput*, start: usize, choice: LexiconChoice*): void {
    var styled = input.highlights != null;
    if styled {
        syntax_scan_highlight(input.highlights, start, input.cursor, input.revision, choice.style, choice.id, choice.skipped);
    }
}

export fn syntax_scan_skip(input: SyntaxScanInput*, result: SyntaxScanResult*): void {
    var meta = input.bootstrapping;
    if meta {} else {
        meta = input.declaration;
    }
    loop {
        var done = input.cursor == input.size;
        if done {
            break;
        }
        var choice: LexiconChoice;
        if meta {
            lexicon_skip(input.lexicon, input.source, input.size, input.cursor, &choice);
        } else {
            var declaration = lexicon_declaration(input.lexicon, input.source, input.size, input.cursor);
            if declaration {
                break;
            }
            scan_choice(input, &choice);
            result.checks = result.checks + choice.checks;
            if choice.skipped {} else {
                break;
            }
        }
        done = choice.length == 0;
        if done {
            break;
        }
        var start = input.cursor;
        input.cursor = input.cursor + choice.length;
        scan_highlight(input, start, &choice);
    }
}

fn scan_after_skip(input: SyntaxScanInput*, result: SyntaxScanResult*): void {
    result.id = 4294967294;
    result.start = input.cursor;
    result.length = 0;
    var done = input.cursor == input.size;
    if done {
        return;
    }
    var choice: LexiconChoice;
    scan_choice(input, &choice);
    result.checks = result.checks + choice.checks;
    var invalid = choice.length == 0;
    if invalid {
        var codepoint: u32;
        var remaining = input.size - input.cursor;
        choice.length = tower_utf8_decode(&input.source[input.cursor], remaining, &codepoint);
        var empty = choice.length == 0;
        if empty {
            choice.length = 1;
        }
        choice.style = "invalid";
        result.error = "No token rule matches source";
    }
    input.cursor = input.cursor + choice.length;
    result.length = choice.length;
    result.id = choice.id;
    scan_highlight(input, result.start, &choice);
}

export fn syntax_scan_token(input: SyntaxScanInput*, result: SyntaxScanResult*): void {
    syntax_scan_skip(input, result);
    scan_after_skip(input, result);
}

export fn syntax_scan_peek(input: SyntaxScanInput*, id: u32*): bool {
    var count: usize = 0;
    loop {
        var exhausted = count == 32;
        if exhausted {
            return false;
        }
        var done = input.cursor == input.size;
        if done {
            *id = 4294967294;
            return true;
        }
        var choice: LexiconChoice;
        scan_choice(input, &choice);
        var invalid = choice.length == 0;
        if invalid {
            return false;
        }
        input.cursor = input.cursor + choice.length;
        if choice.skipped {} else {
            *id = choice.id;
            return true;
        }
        count = count + 1;
    }
}

fn scan_capture(input: SyntaxScanInput*, name: u8*): usize {
    var low: usize = 0;
    var high = input.count;
    loop {
        var done = low == high;
        if done {
            return lr_none();
        }
        var middle = high - low;
        middle = middle / 2;
        middle = middle + low;
        var order = template_text_order(input.captures[middle].name, name);
        var same = order == 0;
        if same {
            return middle;
        }
        var less = order < 0;
        if less {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
}

fn scan_unknown(result: SyntaxScanResult*, name: vector(u8)*): void {
    var ok = node_text_set(&result.message, "Unknown replacement capture: $");
    if ok {
        // Include the NUL in the append; keep text length separate as usual.
        var bytes = name.length + 1;
        ok = bytes_append(&result.message, name.data, bytes);
        if ok {
            result.message.length = result.message.length - 1;
            result.error = result.message.data;
        }
    }
    if ok {} else {
        result.error = "Unable to allocate replacement capture diagnostic";
    }
}

export fn syntax_scan_read(input: SyntaxScanInput*, result: SyntaxScanResult*): void* {
    syntax_scan_skip(input, result);
    result.start = input.cursor;
    result.id = 4294967294;
    var hole = input.replacement;
    if hole {
        hole = input.cursor < input.size;
    }
    if hole {
        hole = input.source[input.cursor] == 36;
    }
    var name: vector(u8);
    vector_init(u8, &name);
    var ok: bool = true;
    if hole {
        input.cursor = input.cursor + 1;
        var start = input.cursor;
        var length = lexicon_identifier(input.lexicon, input.source, input.size, start);
        input.cursor = input.cursor + length;
        ok = syntax_identifier_decode(&input.source[start], length, &name);
        if ok {
            var ordinal = scan_capture(input, name.data);
            var missing = ordinal == lr_none();
            if missing {
                scan_unknown(result, &name);
            } else {
                ordinal = ordinal & 4294967295;
                result.id = convert(u32, ordinal);
                result.id = result.id + 3145728;
                result.length = input.cursor - result.start;
            }
        }
    } else {
        scan_after_skip(input, result);
    }
    var node: void* = null;
    var present = result.id != 4294967294;
    if present {
        present = result.error == null;
    }
    if present {
        node = entity_create_related(input.context);
        ok = node != null;
        if ok {
            var component = entity_component_add(node, input.match_kind);
            ok = component != null;
            if ok {
                var data = bits(ParserMatchData*, entity_component_data(component));
                node_payload_init(4, bits(void*, data));
                data.id = result.id;
                data.start = result.start + input.base;
                data.length = result.length;
                if hole {
                    ok = node_text_set(&data.label, "$");
                    if ok {
                        var bytes = name.length + 1;
                        ok = bytes_append(&data.label, name.data, bytes);
                        if ok {
                            data.label.length = data.label.length - 1;
                        }
                    }
                } else {
                    ok = bytes_assign_text(&data.label, &input.source[result.start], result.length);
                }
            }
        }
    }
    vector_dispose(u8, &name);
    if ok {} else {
        var allocated = node != null;
        if allocated {
            entity_release(node);
        }
        node = null;
        result.error = "Unable to allocate source token";
    }
    return node;
}

export fn syntax_scan_dispose(result: SyntaxScanResult*): void {
    vector_dispose(u8, &result.message);
}

