// Typed capture holes add ordinary generated productions to the template table.
// Remapping restores active production identities on the same parse entities.
struct SyntaxTemplateCapture {
    name: u8*;
    source: void*;
    wrapper: u8*;
}

struct SyntaxTemplateGrammar {
    emission: SyntaxEmissionInput;
    captures: SyntaxTemplateCapture*;
    count: usize;
    repetitions: SyntaxEmissionHelper*;
    repetition_count: usize;
}

struct SyntaxTemplateAlias {
    name: u8*;
    target: u8*;
}

struct SyntaxTemplateName {
    name: u8*;
    index: usize;
}

struct SyntaxTemplateRemap {
    root: void*;
    match_kind: void*;
    source: SyntaxEmissionProduction*;
    source_count: usize;
    destination: SyntaxEmissionProduction*;
    destination_count: usize;
    aliases: SyntaxTemplateAlias*;
    alias_count: usize;
    names: SyntaxTemplateName*;
    name_count: usize;
    grammar: LRGrammar*;
    uses: usize*;
    count: usize;
}

fn template_hole(value: SyntaxEmission*, category: u8*, id: u32, append: bool): void {
    var name = emission_cname(value, category);
    if value.failed {
        return;
    }
    var rule = emission_production(value, name, true);
    if value.failed {
        return;
    }
    if append {
        emission_reference(value, rule, name, "");
    }
    if value.failed {} else {
        emission_string(value, rule, id);
    }
}

export fn syntax_template_holes(input: SyntaxTemplateGrammar*): bool {
    var value = alloc(SyntaxEmission, 1);
    var missing = value == null;
    if missing {
        return false;
    }
    fill(value, 0, sizeof(SyntaxEmission));
    value.input = &input.emission;
    var index: usize = 0;
    loop {
        var done = index == input.count;
        if done {
            break;
        }
        if value.failed {
            break;
        }
        var capture = &input.captures[index];
        var term = emission_node(value, capture.source);
        var ordinal = index & 4294967295;
        var id = convert(u32, ordinal);
        id = id + 3145728;
        var scalar = term.repetition == 0;
        if scalar {
            var category = capture.wrapper;
            missing = category == null;
            if missing {
                category = node_text_get(&term.text);
            }
            template_hole(value, category, id, false);
        } else {
            var helper: usize = 0;
            loop {
                done = helper == input.repetition_count;
                if done {
                    break;
                }
                var entry = &input.repetitions[helper];
                var target = emission_node(value, entry.source);
                var compatible = target.repetition == 42;
                if compatible {} else {
                    compatible = target.repetition == term.repetition;
                }
                if target.literal {
                    compatible = false;
                }
                if compatible {
                    var order = syntax_bytes_compare(target.text.data, target.text.length, term.text.data, term.text.length);
                    compatible = order == 0;
                }
                if compatible {
                    var base = target.repetition != 42;
                    if base {
                        template_hole(value, entry.name, id, false);
                    }
                    var repeated = target.repetition != 63;
                    if repeated {
                        template_hole(value, entry.name, id, true);
                    }
                }
                if value.failed {
                    break;
                }
                helper = helper + 1;
            }
        }
        index = index + 1;
    }
    var ok = value.failed == false;
    syntax_emission_destroy(value);
    return ok;
}

fn template_text_order(left: u8*, right: u8*): i32 {
    var left_length = syntax_text_length(left);
    var right_length = syntax_text_length(right);
    return syntax_bytes_compare(left, left_length, right, right_length);
}

fn template_source(input: SyntaxTemplateRemap*, index: usize): SyntaxEmissionProduction* {
    var low: usize = 0;
    var high = input.source_count;
    loop {
        var done = low == high;
        if done {
            return null;
        }
        var middle = high - low;
        middle = middle / 2;
        middle = middle + low;
        var value = &input.source[middle];
        var same = value.index == index;
        if same {
            return value;
        }
        var less = value.index < index;
        if less {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
}

fn template_destination(input: SyntaxTemplateRemap*, source: SyntaxEmissionProduction*): usize {
    var low: usize = 0;
    var high = input.destination_count;
    loop {
        var done = low == high;
        if done {
            return lr_none();
        }
        var middle = high - low;
        middle = middle / 2;
        middle = middle + low;
        var value = &input.destination[middle];
        var order = template_text_order(value.name, source.name);
        var equal_name = order == 0;
        if equal_name {
            var equal_alternative = value.alternative == source.alternative;
            if equal_alternative {
                return value.index;
            }
        }
        var less = order < 0;
        if equal_name {
            less = value.alternative < source.alternative;
        }
        if less {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
}

fn template_alias(input: SyntaxTemplateRemap*, name: u8*): u8* {
    var low: usize = 0;
    var high = input.alias_count;
    loop {
        var done = low == high;
        if done {
            return name;
        }
        var middle = high - low;
        middle = middle / 2;
        middle = middle + low;
        var value = &input.aliases[middle];
        var order = template_text_order(value.name, name);
        var same = order == 0;
        if same {
            return value.target;
        }
        var less = order < 0;
        if less {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
}

fn template_named(input: SyntaxTemplateRemap*, name: u8*): usize {
    var low: usize = 0;
    var high = input.name_count;
    loop {
        var done = low == high;
        if done {
            return lr_none();
        }
        var middle = high - low;
        middle = middle / 2;
        middle = middle + low;
        var value = &input.names[middle];
        var order = template_text_order(value.name, name);
        var same = order == 0;
        if same {
            return value.index;
        }
        var less = order < 0;
        if less {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
}

fn template_remap_node(input: SyntaxTemplateRemap*, node: void*): bool {
    var data = lr_tree_match(node, input.match_kind);
    var ordinal = data.id - 3145728;
    var hole = data.id >= 3145728;
    if hole {
        hole = convert(usize, ordinal) < input.count;
    }
    if hole {
        input.uses[ordinal] = input.uses[ordinal] + 1;
        return true;
    }
    var terminal = data.rule == lr_none();
    if terminal {
        return true;
    }
    var source = template_source(input, data.rule);
    var label = template_alias(input, node_text_get(&data.label));
    var supplied = source != null;
    if supplied {
        data.rule = template_destination(input, source);
    } else {
        data.rule = template_named(input, label);
    }
    var id = lr_grammar_lookup(input.grammar, label, lr_name_hash(label));
    var missing = id == lr_none();
    if missing {
        data.id = 4294967294;
    } else {
        id = id & 4294967295;
        data.id = convert(u32, id);
    }
    return node_match_set_label(data, label);
}

export fn syntax_template_remap(input: SyntaxTemplateRemap*): bool {
    var pending: vector(void*);
    vector_init(void*, &pending);
    var bytes = input.count * sizeof(usize);
    fill(input.uses, 0, bytes);
    var ok = vector_push(void*, &pending, input.root);
    loop {
        if ok {} else {
            break;
        }
        var empty = pending.length == 0;
        if empty {
            break;
        }
        pending.length = pending.length - 1;
        var node = pending.data[pending.length];
        ok = template_remap_node(input, node);
        if ok {} else {
            break;
        }
        var index: usize = 0;
        var count = entity_child_count(node);
        loop {
            var done = index == count;
            if done {
                break;
            }
            ok = vector_push(void*, &pending, entity_child_at(node, index));
            if ok {} else {
                break;
            }
            index = index + 1;
        }
    }
    vector_dispose(void*, &pending);
    return ok;
}

import tower;

// Disposable revision analysis over shared grammar entities. Only lookup and
// dependency indexes live here; declarations remain the authoritative nodes.
struct SyntaxRuleView {
    name: u8*;
    name_length: usize;
    alternatives: void**;
    count: usize;
}

struct SyntaxDependent {
    owner: usize;
    term: void*;
}

struct SyntaxRuleState {
    dependents: vector(SyntaxDependent);
    nullable: bool;
    productive: bool;
}

struct SyntaxValidation {
    rules: SyntaxRuleView*;
    count: usize;
    tokens: void**;
    token_count: usize;
    kind: void*;
    states: vector(SyntaxRuleState);
    pending: void**;
    queue: vector(usize);
    captures: vector(SyntaxNode*);
    error: vector(u8)*;
    offset: usize*;
    allocated: bool;
}

fn syntax_validation_node(value: SyntaxValidation*, node: void*): SyntaxNode* {
    var component = entity_component_get(node, value.kind);
    return bits(SyntaxNode*, entity_component_data(component));
}

fn syntax_bytes_compare(left: u8*, left_length: usize, right: u8*, right_length: usize): i32 {
    var index: usize = 0;
    loop {
        var end = index == left_length;
        if end {
            var same = index == right_length;
            if same {
                return 0;
            }
            return -1;
        }
        end = index == right_length;
        if end {
            return 1;
        }
        var less = left[index] < right[index];
        if less {
            return -1;
        }
        var greater = left[index] > right[index];
        if greater {
            return 1;
        }
        index = index + 1;
    }
}

fn syntax_rule_find(rules: SyntaxRuleView*, count: usize, name: u8*, length: usize): usize {
    var low: usize = 0;
    var high = count;
    loop {
        var done = low == high;
        if done {
            return lr_none();
        }
        var middle = high - low;
        middle = middle / 2;
        middle = middle + low;
        var rule = &rules[middle];
        var order = syntax_bytes_compare(name, length, rule.name, rule.name_length);
        var same = order == 0;
        if same {
            return middle;
        }
        var less = order < 0;
        if less {
            high = middle;
        } else {
            low = middle + 1;
        }
    }
}

fn syntax_validation_find(value: SyntaxValidation*, name: u8*, length: usize): usize {
    return syntax_rule_find(value.rules, value.count, name, length);
}

fn syntax_validation_token(value: SyntaxValidation*, text: u8*, length: usize, skipped: bool): bool {
    var index: usize = 0;
    loop {
        var done = index == value.token_count;
        if done {
            return false;
        }
        var node = syntax_validation_node(value, value.tokens[index]);
        var eligible = node.kind != 3;
        if skipped {
            eligible = true;
        }
        if eligible {
            var order = syntax_bytes_compare(text, length, node.name.data, node.name.length);
            var same = order == 0;
            if same {
                return true;
            }
        }
        index = index + 1;
    }
}

fn syntax_validation_append(value: SyntaxValidation*, text: u8*, length: usize): void {
    if value.allocated {
        value.allocated = bytes_append(value.error, text, length);
    }
}

fn syntax_validation_text(value: SyntaxValidation*, text: u8*): void {
    var length = syntax_text_length(text);
    syntax_validation_append(value, text, length);
}

fn syntax_validation_error(value: SyntaxValidation*, prefix: u8*, text: u8*, length: usize): bool {
    syntax_validation_text(value, prefix);
    syntax_validation_append(value, text, length);
    return false;
}

fn syntax_validation_location(value: SyntaxValidation*, node: SyntaxNode*): void {
    var located = node.start != lr_none();
    if located {
        *value.offset = node.start;
    }
}

// Reuse a borrowed-name hash set for each alternative. Its capacity is bounded
// by the largest sequence, without copying capture names or rescanning prefixes.
fn syntax_validation_captures(value: SyntaxValidation*, count: usize): bool {
    var size = count * 2;
    var overflow = size < count;
    if overflow {
        value.allocated = false;
        return false;
    }
    size = size + 1;
    value.allocated = vector_reserve(SyntaxNode*, &value.captures, size);
    if value.allocated {
        value.captures.length = size;
        var bytes = size * sizeof(SyntaxNode*);
        fill(value.captures.data, 0, bytes);
    }
    return value.allocated;
}

fn syntax_validation_capture(value: SyntaxValidation*, term: SyntaxNode*): bool {
    var empty = term.capture.length == 0;
    if empty {
        return true;
    }
    var hash: usize = 2166136261;
    var index: usize = 0;
    loop {
        var done = index == term.capture.length;
        if done {
            break;
        }
        var byte = convert(usize, term.capture.data[index]);
        hash = hash ^ byte;
        hash = hash * 16777619;
        index = index + 1;
    }
    var size = value.captures.length;
    var unavailable = size == 0;
    if unavailable {
        value.allocated = false;
        return false;
    }
    var slot = hash % size;
    loop {
        var previous = value.captures.data[slot];
        empty = previous == null;
        if empty {
            value.captures.data[slot] = term;
            return true;
        }
        var same = syntax_text_equal(&previous.capture, &term.capture);
        if same {
            return syntax_validation_error(value, "Duplicate capture: ", term.capture.data, term.capture.length);
        }
        slot = slot + 1;
        var wrap = slot == value.captures.length;
        if wrap {
            slot = 0;
        }
    }
}

fn syntax_validation_terms(value: SyntaxValidation*): bool {
    var index: usize = 0;
    loop {
        var done = index == value.count;
        if done {
            return true;
        }
        var rule = &value.rules[index];
        var collision = syntax_validation_token(value, rule.name, rule.name_length, true);
        if collision {
            return syntax_validation_error(value, "Name already defines a token or skip rule: ", rule.name, rule.name_length);
        }
        var alternative: usize = 0;
        loop {
            done = alternative == rule.count;
            if done {
                break;
            }
            var sequence = syntax_validation_node(value, rule.alternatives[alternative]);
            var ok = syntax_validation_captures(value, sequence.items.length);
            if ok {} else {
                return false;
            }
            var item: usize = 0;
            loop {
                done = item == sequence.items.length;
                if done {
                    break;
                }
                var term = syntax_validation_node(value, sequence.items.data[item]);
                if term.literal {
                    var status = syntax_literal_check(term.text.data, term.text.length);
                    var invalid = status != 0;
                    if invalid {
                        syntax_validation_location(value, term);
                        var empty = status == 1;
                        if empty {
                            syntax_validation_text(value, "Token literal is empty. Expected at least one character between the quotes.");
                            return false;
                        }
                        return syntax_validation_error(value, "Unsupported token literal: ", term.text.data, term.text.length);
                    }
                }
                ok = syntax_validation_capture(value, term);
                if ok {} else {
                    return false;
                }
                item = item + 1;
            }
            alternative = alternative + 1;
        }
        index = index + 1;
    }
}

fn syntax_validation_has_capture(value: SyntaxValidation*, sequence: SyntaxNode*, capture: u8*): bool {
    var length = syntax_text_length(capture);
    var index: usize = 0;
    loop {
        var done = index == sequence.items.length;
        if done {
            return false;
        }
        var term = syntax_validation_node(value, sequence.items.data[index]);
        var order = syntax_bytes_compare(term.capture.data, term.capture.length, capture, length);
        var found = order == 0;
        if found {
            return true;
        }
        index = index + 1;
    }
}

fn syntax_validation_required(value: SyntaxValidation*, sequence: SyntaxNode*, name: u8*, capture: u8*): bool {
    var present = syntax_validation_has_capture(value, sequence, capture);
    if present {
        return true;
    }
    syntax_validation_location(value, sequence);
    syntax_validation_text(value, "Declaration rule ");
    syntax_validation_text(value, name);
    syntax_validation_text(value, " must preserve capture '");
    syntax_validation_text(value, capture);
    syntax_validation_text(value, "'");
    return false;
}

// The declaration reader consumes these named roles. Checking them here keeps
// grammar edits transactional; changing the reader syntax cannot drop its data.
fn syntax_validation_declaration(value: SyntaxValidation*, name: u8*, empty: bool, first: u8*, second: u8*, third: u8*, fourth: u8*, atom: bool): bool {
    var length = syntax_text_length(name);
    var index = syntax_validation_find(value, name, length);
    var missing = index == lr_none();
    if missing {
        return syntax_validation_error(value, "Missing declaration rule: ", name, length);
    }
    var rule = &value.rules[index];
    var alternative: usize = 0;
    loop {
        var done = alternative == rule.count;
        if done {
            return true;
        }
        var sequence = syntax_validation_node(value, rule.alternatives[alternative]);
        alternative = alternative + 1;
        if empty {
            var vacant = sequence.items.length == 0;
            if vacant {
                continue;
            }
        }
        var present = first != null;
        var ok = true;
        if present {
            ok = syntax_validation_required(value, sequence, name, first);
        }
        present = second != null;
        if present {
            if ok {
                ok = syntax_validation_required(value, sequence, name, second);
            }
        }
        present = third != null;
        if present {
            if ok {
                ok = syntax_validation_required(value, sequence, name, third);
            }
        }
        present = fourth != null;
        if present {
            if ok {
                ok = syntax_validation_required(value, sequence, name, fourth);
            }
        }
        if ok {} else {
            return false;
        }
        if atom {
            ok = syntax_validation_has_capture(value, sequence, "literal");
            if ok {} else {
                ok = syntax_validation_has_capture(value, sequence, "reference");
            }
            if ok {} else {
                ok = syntax_validation_has_capture(value, sequence, "capture");
            }
            if ok {} else {
                ok = syntax_validation_has_capture(value, sequence, "set");
            }
            if ok {} else {
                syntax_validation_text(value, "GrammarAtom must capture a literal, reference or capture name");
                return false;
            }
        }
    }
}

fn syntax_validation_imports(value: SyntaxValidation*): bool {
    // Older editable declaration grammars may still capture Identifier directly.
    var index = syntax_validation_find(value, "ImportDeclaration", 17);
    var present = index != lr_none();
    if present {
        var ok = syntax_validation_declaration(value, "ImportDeclaration", false, "name", null, null, null, false);
        if ok {} else {
            return false;
        }
    }
    index = syntax_validation_find(value, "ImportPath", 10);
    var missing = index == lr_none();
    if missing {
        return true;
    }
    var ok = syntax_validation_declaration(value, "ImportPath", false, "segment", null, null, null, false);
    if ok {} else {
        return false;
    }
    var rule = &value.rules[index];
    var alternative: usize = 0;
    loop {
        var done = alternative == rule.count;
        if done {
            return true;
        }
        var sequence = syntax_validation_node(value, rule.alternatives[alternative]);
        var item: usize = 0;
        loop {
            done = item == sequence.items.length;
            if done {
                break;
            }
            var term = syntax_validation_node(value, sequence.items.data[item]);
            var recursive = term.literal == false;
            if recursive {
                recursive = syntax_bytes_compare(term.text.data, term.text.length, "ImportPath", 10) == 0;
            }
            if recursive {
                ok = syntax_bytes_compare(term.capture.data, term.capture.length, "previous", 8) == 0;
                if ok {} else {
                    syntax_validation_location(value, term);
                    syntax_validation_text(value, "Recursive ImportPath must preserve capture 'previous'");
                    return false;
                }
            }
            item = item + 1;
        }
        alternative = alternative + 1;
    }
}

fn syntax_validation_declarations(value: SyntaxValidation*): bool {
    var ok = syntax_validation_declaration(value, "GrammarAlternatives", false, "sequence", null, null, null, false);
    if ok {
        ok = syntax_validation_declaration(value, "GrammarAssignment", false, null, null, null, null, false);
    }
    if ok {
        ok = syntax_validation_declaration(value, "GrammarAtom", false, null, null, null, null, true);
    }
    if ok {
        ok = syntax_validation_declaration(value, "GrammarDeclaration", false, "name", "op", "alternatives", "replacement", false);
    }
    if ok {
        ok = syntax_validation_declaration(value, "GrammarReplacement", true, "body", null, null, null, false);
    }
    if ok {
        ok = syntax_validation_declaration(value, "GrammarSequence", true, "previous", "term", null, null, false);
    }
    if ok {
        ok = syntax_validation_declaration(value, "GrammarSkipDeclaration", false, "name", "pattern", "style", null, false);
    }
    if ok {
        ok = syntax_validation_declaration(value, "GrammarStyle", true, "kind", null, null, null, false);
    }
    if ok {
        ok = syntax_validation_declaration(value, "GrammarSuffix", false, null, null, null, null, false);
    }
    if ok {
        ok = syntax_validation_declaration(value, "GrammarTerm", false, "atom", "suffix", null, null, false);
    }
    if ok {
        ok = syntax_validation_declaration(value, "GrammarTokenDeclaration", false, "name", "pattern", "style", null, false);
    }
    if ok {
        ok = syntax_validation_imports(value);
    }
    return ok;
}

fn syntax_validation_wait(value: SyntaxValidation*, owner: usize, term: void*): bool {
    var fresh = value.pending[owner] == null;
    if fresh {
        value.allocated = vector_push(usize, &value.queue, owner);
        if value.allocated {
            value.pending[owner] = term;
        }
    }
    return value.allocated;
}

fn syntax_validation_dependencies(value: SyntaxValidation*): bool {
    var index: usize = 0;
    loop {
        var done = index == value.count;
        if done {
            break;
        }
        var rule = &value.rules[index];
        var alternative: usize = 0;
        loop {
            done = alternative == rule.count;
            if done {
                break;
            }
            var sequence = syntax_validation_node(value, rule.alternatives[alternative]);
            var item: usize = 0;
            loop {
                done = item == sequence.items.length;
                if done {
                    break;
                }
                var entity = sequence.items.data[item];
                var term = syntax_validation_node(value, entity);
                item = item + 1;
                if term.literal {
                    continue;
                }
                if term.terminal_set {
                    continue;
                }
                var terminal = syntax_validation_token(value, term.text.data, term.text.length, false);
                if terminal {
                    continue;
                }
                var target = syntax_validation_find(value, term.text.data, term.text.length);
                var missing = target == lr_none();
                if missing {
                    syntax_validation_wait(value, index, entity);
                } else {
                    var edge: SyntaxDependent;
                    edge.owner = index;
                    edge.term = entity;
                    value.allocated = lr_append(SyntaxDependent, &value.states.data[target].dependents, &edge);
                }
                if value.allocated {} else {
                    return false;
                }
            }
            alternative = alternative + 1;
        }
        index = index + 1;
    }
    index = 0;
    loop {
        var done = index == value.queue.length;
        if done {
            return true;
        }
        var owner = value.queue.data[index];
        var edges = &value.states.data[owner].dependents;
        var edge: usize = 0;
        loop {
            done = edge == edges.length;
            if done {
                break;
            }
            var ok = syntax_validation_wait(value, edges.data[edge].owner, edges.data[edge].term);
            if ok {} else {
                return false;
            }
            edge = edge + 1;
        }
        index = index + 1;
    }
}

fn syntax_validation_root(value: SyntaxValidation*, name: u8*): bool {
    var length = syntax_text_length(name);
    var index = syntax_validation_find(value, name, length);
    var missing = index == lr_none();
    if missing {
        return true;
    }
    var ready = value.pending[index] == null;
    if ready {
        return true;
    }
    syntax_validation_text(value, "Cannot activate incomplete grammar: ");
    syntax_validation_append(value, name, length);
    loop {
        var term = syntax_validation_node(value, value.pending[index]);
        syntax_validation_location(value, term);
        name = term.text.data;
        length = term.text.length;
        syntax_validation_text(value, " -> ");
        syntax_validation_append(value, name, length);
        index = syntax_validation_find(value, name, length);
        missing = index == lr_none();
        if missing {
            break;
        }
    }
    syntax_validation_text(value, " (undefined rule '");
    syntax_validation_append(value, name, length);
    syntax_validation_text(value, "')");
    return false;
}

fn syntax_validation_optional(term: SyntaxNode*): bool {
    var optional = term.repetition == 42;
    if optional {
        return true;
    }
    optional = term.repetition == 63;
    return optional;
}

fn syntax_validation_properties(value: SyntaxValidation*): void {
    loop {
        var changed = false;
        var index: usize = 0;
        loop {
            var done = index == value.count;
            if done {
                break;
            }
            var owner = index;
            index = index + 1;
            var waiting = value.pending[owner] != null;
            if waiting {
                continue;
            }
            var rule = &value.rules[owner];
            var state = &value.states.data[owner];
            var alternative: usize = 0;
            loop {
                done = alternative == rule.count;
                if done {
                    break;
                }
                var sequence = syntax_validation_node(value, rule.alternatives[alternative]);
                var nullable = true;
                var productive = true;
                var item: usize = 0;
                loop {
                    done = item == sequence.items.length;
                    if done {
                        break;
                    }
                    var term = syntax_validation_node(value, sequence.items.data[item]);
                    item = item + 1;
                    var optional = syntax_validation_optional(term);
                    if optional {
                        continue;
                    }
                    var terminal = term.literal;
                    if term.terminal_set {
                        terminal = true;
                    }
                    if terminal {
                        nullable = false;
                        continue;
                    }
                    var target = syntax_validation_find(value, term.text.data, term.text.length);
                    var found = target != lr_none();
                    var empty = false;
                    var produces = false;
                    if found {
                        empty = value.states.data[target].nullable;
                        produces = value.states.data[target].productive;
                    } else {
                        produces = syntax_validation_token(value, term.text.data, term.text.length, false);
                    }
                    if empty {} else {
                        nullable = false;
                    }
                    if produces {} else {
                        productive = false;
                    }
                }
                if nullable {
                    var fresh = state.nullable == false;
                    if fresh {
                        state.nullable = true;
                        changed = true;
                    }
                }
                if productive {
                    var fresh = state.productive == false;
                    if fresh {
                        state.productive = true;
                        changed = true;
                    }
                }
                alternative = alternative + 1;
            }
        }
        if changed {} else {
            return;
        }
    }
}

fn syntax_validation_productive(value: SyntaxValidation*): bool {
    var statement = syntax_validation_find(value, "Statement", 9);
    var present = statement != lr_none();
    if present {
        if value.states.data[statement].nullable {
            syntax_validation_text(value, "Statement must consume input");
            return false;
        }
    }
    var index: usize = 0;
    loop {
        var done = index == value.count;
        if done {
            return true;
        }
        var owner = index;
        index = index + 1;
        var waiting = value.pending[owner] != null;
        if waiting {
            continue;
        }
        var rule = &value.rules[owner];
        var productive = value.states.data[owner].productive;
        if productive {} else {
            return syntax_validation_error(value, "Unproductive grammar rule: ", rule.name, rule.name_length);
        }
        var alternative: usize = 0;
        loop {
            done = alternative == rule.count;
            if done {
                break;
            }
            var sequence = syntax_validation_node(value, rule.alternatives[alternative]);
            var item: usize = 0;
            loop {
                done = item == sequence.items.length;
                if done {
                    break;
                }
                var term = syntax_validation_node(value, sequence.items.data[item]);
                item = item + 1;
                if term.literal {
                    continue;
                }
                var repeated = term.repetition == 42;
                var plus = term.repetition == 43;
                if plus {
                    repeated = true;
                }
                if repeated {
                    var target = syntax_validation_find(value, term.text.data, term.text.length);
                    var found = target != lr_none();
                    if found {
                        if value.states.data[target].nullable {
                            return syntax_validation_error(value, "Cannot repeat nullable rule: ", term.text.data, term.text.length);
                        }
                    }
                }
            }
            alternative = alternative + 1;
        }
    }
}

export fn syntax_validate(rules: SyntaxRuleView*, count: usize, tokens: void**, token_count: usize, kind: void*, error: vector(u8)*, offset: usize*, pending: void**): bool {
    var value: SyntaxValidation;
    fill(&value, 0, sizeof(SyntaxValidation));
    value.rules = rules;
    value.count = count;
    value.tokens = tokens;
    value.token_count = token_count;
    value.kind = kind;
    value.error = error;
    value.offset = offset;
    value.pending = pending;
    value.allocated = true;
    var index: usize = 0;
    loop {
        var done = index == count;
        if done {
            break;
        }
        pending[index] = null;
        index = index + 1;
    }
    value.allocated = vector_reserve(SyntaxRuleState, &value.states, count);
    var ok = value.allocated;
    if ok {
        var bytes = count * sizeof(SyntaxRuleState);
        fill(value.states.data, 0, bytes);
        value.states.length = count;
        ok = syntax_validation_terms(&value);
    }
    if ok {
        ok = syntax_validation_declarations(&value);
    }
    if ok {
        ok = syntax_validation_dependencies(&value);
    }
    if ok {
        ok = syntax_validation_root(&value, "GrammarDeclaration");
    }
    if ok {
        ok = syntax_validation_root(&value, "GrammarTokenDeclaration");
    }
    if ok {
        ok = syntax_validation_root(&value, "GrammarSkipDeclaration");
    }
    if ok {
        ok = syntax_validation_root(&value, "ImportDeclaration");
    }
    if ok {
        ok = syntax_validation_root(&value, "Statement");
    }
    if ok {
        syntax_validation_properties(&value);
        ok = syntax_validation_productive(&value);
    }
    index = 0;
    loop {
        var done = index == value.states.length;
        if done {
            break;
        }
        vector_dispose(SyntaxDependent, &value.states.data[index].dependents);
        index = index + 1;
    }
    vector_dispose(SyntaxRuleState, &value.states);
    vector_dispose(usize, &value.queue);
    vector_dispose(SyntaxNode*, &value.captures);
    if value.allocated {} else {
        vector_dispose(u8, error);
        index = 0;
        loop {
            var done = index == count;
            if done {
                break;
            }
            pending[index] = null;
            index = index + 1;
        }
        return false;
    }
    return ok;
}

import tower;

// Compiler UTF-8 utilities. Counts and capacities are bytes, never characters.
// Decode one Unicode scalar; invalid/truncated input returns 0 and clears value.
export fn tower_utf8_decode(data: u8*, size: usize, value: u32*): usize {
    *value = 0;
    var empty = size == 0;
    if empty {
        return 0;
    }
    var first = convert(u32, data[0]);
    var ascii = first < 128;
    if ascii {
        *value = first;
        return 1;
    }
    var count: usize = 0;
    var minimum: u32 = 0;
    var scalar: u32 = 0;
    var invalid_lead = first < 194;
    if invalid_lead {
        return 0;
    }
    invalid_lead = first > 244;
    if invalid_lead {
        return 0;
    }
    var two = first <= 223;
    if two {
        count = 2;
        minimum = 128;
        scalar = first & 31;
    } else {
        var three = first <= 239;
        if three {
            count = 3;
            minimum = 2048;
            scalar = first & 15;
        } else {
            count = 4;
            minimum = 65536;
            scalar = first & 7;
        }
    }
    var truncated = size < count;
    if truncated {
        return 0;
    }
    var index: usize = 1;
    loop {
        var done = index == count;
        if done {
            break;
        }
        var byte = convert(u32, data[index]);
        var prefix = byte & 192;
        var invalid = prefix != 128;
        if invalid {
            return 0;
        }
        var payload = byte & 63;
        scalar = scalar * 64;
        scalar = scalar | payload;
        index = index + 1;
    }
    var overlong = scalar < minimum;
    if overlong {
        return 0;
    }
    var too_large = scalar > 1114111;
    if too_large {
        return 0;
    }
    var low = scalar >= 55296;
    if low {
        var high = scalar <= 57343;
        if high {
            return 0;
        }
    }
    *value = scalar;
    return count;
}

// A null output queries size. Insufficient capacity or invalid scalars write nothing.
export fn tower_utf8_encode(scalar: u32, output: u8*, capacity: usize): usize {
    var low = scalar >= 55296;
    if low {
        var high = scalar <= 57343;
        if high {
            return 0;
        }
    }
    var too_large = scalar > 1114111;
    if too_large {
        return 0;
    }
    var count: usize = 1;
    var prefix: u32 = 0;
    var multiple = scalar > 127;
    if multiple {
        count = 2;
        prefix = 192;
        var three = scalar > 2047;
        if three {
            count = 3;
            prefix = 224;
            var four = scalar > 65535;
            if four {
                count = 4;
                prefix = 240;
            }
        }
    }
    var query = output == null;
    if query {
        return count;
    }
    var short_buffer = capacity < count;
    if short_buffer {
        return 0;
    }
    var index = count - 1;
    var remaining = scalar;
    loop {
        var done = index == 0;
        if done {
            break;
        }
        var byte = remaining & 63;
        byte = byte | 128;
        output[index] = convert(u8, byte);
        remaining = remaining / 64;
        index = index - 1;
    }
    var first = prefix | remaining;
    first = first & 255;
    output[0] = convert(u8, first);
    return count;
}

// Source text accepts every Unicode scalar except NUL; arbitrary buffers may contain NUL.
export fn tower_utf8_validate(data: u8*, size: usize, reject_nul: u32): u32 {
    var index: usize = 0;
    var scalar: u32 = 0;
    loop {
        var done = index == size;
        if done {
            return 1;
        }
        var byte = data[index];
        var nul = byte == 0;
        if nul {
            var reject = reject_nul != 0;
            if reject {
                return 0;
            }
        }
        var ascii = byte < 128;
        if ascii {
            index = index + 1;
        } else {
            var start = data + index;
            var remaining = size - index;
            var count = tower_utf8_decode(start, remaining, &scalar);
            var invalid = count == 0;
            if invalid {
                return 0;
            }
            index = index + count;
        }
    }
}

import bedrock;

// Shares Whitespace, LineComment, BlockComment, Identifier and String from bedrock.tower.
// The import applies Bedrock declarations before Foundation adds executable syntax.
token Number = /[0-9]+/ as number;

// Bootstrap semantic ABI: these Core* tree labels and captures name typed ops.
// No precedence hierarchy: a binary value has two operands and one operator.
parse CoreType = $name:Identifier | $base:CoreType '*' | $base:CoreType '[' $count:CoreArrayCount ']'
                | $name:Identifier '(' $args:CoreTypeArguments? ')';
parse CoreArrayCount = Number | Identifier | '-' Number;
parse CoreTypeArgument = CoreType | Number | '-' Number;
parse CoreTypeArguments = CoreTypeArgument | CoreTypeArguments ',' CoreTypeArgument;
parse CoreLocation = $name:Identifier | $base:CoreLocation '.' $field:Identifier;
parse CoreOperand = CoreLocation | Number | '-' Number | 'true' | 'false' | 'null' | String;
parse CoreLocation |= $base:CoreLocation '[' $index:CoreOperand ']';
parse CoreOperator = '+' | '-' | '*' | '/' | '%' | '&' | '|' | '^' | '==' | '!=' | '<' | '<=' | '>' | '>=';
parse CoreBinary = $left:CoreOperand $op:CoreOperator $right:CoreOperand;
parse CoreAddress = '&' $name:CoreLocation;
parse CoreLoad = '*' $name:CoreLocation;
parse CoreValue = CoreOperand | CoreBinary;
parse CoreTarget = $name:CoreLocation | '*' $name:CoreLocation;
parse CoreDeclare = 'var' $name:Identifier ':' $type:CoreType ';'
                   | 'var' $name:Identifier ':' $type:CoreType '=' $value:CoreValue ';'
                   | 'var' $name:Identifier '=' $value:CoreValue ';';
parse CoreAssign = $target:CoreTarget '=' $value:CoreValue ';';
parse Statement = CoreDeclare | CoreAssign;
parse CoreBlock = '{' Statement* '}';
parse CoreIf = 'if' $condition:CoreOperand $body:CoreBlock
              | 'if' $condition:CoreOperand $body:CoreBlock 'else' $otherwise:CoreBlock;
parse CoreLoop = 'loop' $body:CoreBlock;
parse CoreBreak = 'break' ';';
parse CoreContinue = 'continue' ';';
parse Statement |= CoreBlock | CoreIf | CoreLoop | CoreBreak | CoreContinue;

parse CoreParameter = $name:Identifier ':' $type:CoreType;
parse CoreParameters = CoreParameter | CoreParameters ',' CoreParameter;
// Calls share one argument grammar. Type arguments are resolved semantically.
parse CoreCallArgument = CoreOperand | CorePointerArgument;
parse CorePointerArgument = $base:CoreCallArgument '*' | $base:CorePointerArgument '[' $index:CoreOperand ']';
parse CoreArguments = CoreCallArgument | CoreArguments ',' CoreCallArgument;
parse CoreCall = $name:Identifier '(' $args:CoreArguments? ')';
parse CoreOperand |= CoreCall | CoreAddress | CoreLoad;
parse CoreFunction = 'fn' $name:Identifier '(' $params:CoreParameters? ')' ':' $type:CoreType $body:CoreBlock;
parse CoreReturn = 'return' $value:CoreOperand? ';';
parse CoreCallStatement = $call:CoreCall ';';
parse Statement |= CoreFunction | CoreReturn | CoreCallStatement;

parse CoreField = $name:Identifier ':' $type:CoreType ';';
parse CoreStruct = 'struct' $name:Identifier '{' $fields:CoreField* '}';
parse Statement |= CoreStruct;

// Nominal integer representations and members survive Foundation round trips.
// Tower may add automatic discriminants; canonical Foundation makes each explicit.
parse CoreEnumInteger = Number | '-' Number;
parse CoreEnumMember = $name:Identifier '=' $value:CoreEnumInteger;
parse CoreEnumMembers = CoreEnumMember | CoreEnumMembers ',' CoreEnumMember;
parse CoreEnum = 'enum' $name:Identifier ':' $type:CoreType '{' $fields:CoreEnumMembers ','? '}';
parse Statement |= CoreEnum;

// Raw memory and external symbols; safety policies can be layered above these.
parse CoreExternal = 'extern' 'fn' $name:Identifier '(' $params:CoreParameters? ')' ':' $type:CoreType ';';
parse CoreExport = 'export' 'fn' $name:Identifier '(' $params:CoreParameters? ')' ':' $type:CoreType $body:CoreBlock;
parse Statement |= CoreExternal | CoreExport;

import tower;

// Browser transport policies. These consume borrowed values from the compiler;
// JSON is not a second semantic model or a Tower interchange format.
extern fn tower_utf8_validate(source: u8*, count: usize, reject_nul: u32): u32;

export fn tw_abi_version(): u32 {
    return 3;
}

export fn tw_alloc(count: usize): u8* {
    return alloc(u8, count);
}

export fn tw_free(pointer: u8*): void {
    free(pointer);
}

export fn host_source_error(source: u8*, count: usize): u8* {
    var large = count > 8388608;
    if large {
        return "Compilation source limit is 8 MiB";
    }
    var missing = source == null;
    if missing {
        return "Source must be valid UTF-8 without NUL bytes";
    }
    var valid = tower_utf8_validate(source, count, 1) != 0;
    if valid {
        return "";
    }
    return "Source must be valid UTF-8 without NUL bytes";
}

fn host_protocol_text(out: ByteBuffer*, text: u8*): bool {
    var count: usize = 0;
    loop {
        var done = text[count] == 0;
        if done {
            break;
        }
        count = count + 1;
    }
    return bytes_append(out, text, count);
}

// On allocation failure callers must discard the partial response. The native
// adapter retains its existing abort-on-transport-allocation-failure policy.
export fn host_execution_json(out: ByteBuffer*, error: u8*, error_count: usize, offset: usize, done: bool, output: u8*, output_count: usize, steps: u64, truncated: bool): bool {
    out.length = 0;
    var status: u8* = "executing";
    if done {
        status = "done";
    }
    var failed = error_count != 0;
    if failed {
        status = "error";
    }
    var ok = host_protocol_text(out, "{\"status\":\"");
    if ok {
        ok = host_protocol_text(out, status);
    }
    if ok {
        ok = host_protocol_text(out, "\",\"error\":");
    }
    if ok {
        ok = host_json_quote(out, error, error_count);
    }
    if ok {
        ok = host_protocol_text(out, ",\"errorOffset\":");
    }
    if ok {
        var wide = convert(u64, offset);
        ok = host_json_unsigned(out, wide);
    }
    if ok {
        ok = host_protocol_text(out, ",\"outputBytes\":[");
    }
    var i: usize = 0;
    loop {
        var end = i == output_count;
        if end {
            break;
        }
        if ok {} else {
            break;
        }
        var comma = i != 0;
        if comma {
            ok = bytes_push(out, 44);
        }
        if ok {
            var byte = convert(u64, output[i]);
            ok = host_json_unsigned(out, byte);
        }
        i = i + 1;
    }
    if ok {
        ok = host_protocol_text(out, "],\"steps\":");
    }
    if ok {
        ok = host_json_unsigned(out, steps);
    }
    if ok {
        if truncated {
            ok = host_protocol_text(out, ",\"outputTruncated\":true}");
        } else {
            ok = host_protocol_text(out, ",\"outputTruncated\":false}");
        }
    }
    return ok;
}

import tower;

// Opaque libc file handles are temporary platform services, not Tower values or
// program storage. Paths and bytes are explicit inputs; no host file is read
// during constant evaluation. The CLI calls these at its execution stage.
extern fn fopen(path: u8*, mode: u8*): void*;

extern fn fread(data: u8*, size: usize, count: usize, file: void*): usize;

extern fn fwrite(data: u8*, size: usize, count: usize, file: void*): usize;

extern fn ferror(file: void*): i32;

extern fn feof(file: void*): i32;

extern fn fclose(file: void*): i32;

// Success replaces out atomically, including the terminating NUL view. Failure
// leaves its old contents intact and closes the file on every path.
export fn driver_read_file(path: u8*, out: ByteBuffer*): bool {
    var file = fopen(path, "rb");
    var missing = file == null;
    if missing {
        return false;
    }
    var next: ByteBuffer;
    fill(&next, 0, sizeof(ByteBuffer));
    var chunk: u8[16384];
    var ok = true;
    loop {
        var count = fread(&chunk[0], 1, 16384, file);
        ok = bytes_append(&next, &chunk[0], count);
        if ok {} else {
            break;
        }
        var failed = ferror(file) != 0;
        if failed {
            ok = false;
            break;
        }
        var done = feof(file) != 0;
        if done {
            break;
        }
        var stalled = count == 0;
        if stalled {
            ok = false;
            break;
        }
    }
    var closed = fclose(file) == 0;
    if closed {} else {
        ok = false;
    }
    if ok {
        ok = host_text_terminate(&next);
    }
    if ok {
        bytes_dispose(out);
        out.data = next.data;
        out.length = next.length;
        out.capacity = next.capacity;
    } else {
        bytes_dispose(&next);
    }
    return ok;
}

// Output is binary (including NUL). A write/close failure is reported; callers
// must not treat a partial output file as a successful compiler artifact.
export fn driver_write_file(path: u8*, data: u8*, count: usize): bool {
    var file = fopen(path, "wb");
    var missing = file == null;
    if missing {
        return false;
    }
    var written: usize = 0;
    var ok = true;
    loop {
        var done = written == count;
        if done {
            break;
        }
        var next = data + written;
        var remaining = count - written;
        var amount = fwrite(next, 1, remaining, file);
        var stalled = amount == 0;
        if stalled {
            ok = false;
            break;
        }
        written = written + amount;
    }
    var failed = ferror(file) != 0;
    if failed {
        ok = false;
    }
    var closed = fclose(file) == 0;
    if closed {} else {
        ok = false;
    }
    return ok;
}

import tower;

// CLI parsing owns its link array and borrows argv/default-target strings.
// Keep option ordering and early --help behavior of the original native driver.
struct DriverOptions {
    source: u8*;
    output: u8*;
    target: u8*;
    emit: u8*;
    cc: u8*;
    linker: u8*;
    sysroot: u8*;
    raw: u8*;
    optimized: u8*;
    bedrock: u8*;
    foundation: u8*;
    depfile: u8*;
    links: u8**;
    link_count: usize;
    optimize: bool;
    interpret: bool;
    library: bool;
    timings: bool;
    help: bool;
    version: bool;
    fast: bool;
    error: u32;
    argument: u8*;
}

fn driver_equal(a: u8*, b: u8*): bool {
    var index: usize = 0;
    loop {
        var different = a[index] != b[index];
        if different {
            return false;
        }
        var end = a[index] == 0;
        if end {
            return true;
        }
        index = index + 1;
    }
    return false;
}

export fn driver_help(): u8* {
    return "towerc source.tower -o output [--target triple] [--emit object|llvm|llvm-optimized|exe|bytecode|foundation]\n  [--link object-or-library] [--cc clang] [--linker tool] [--sysroot path]\n  [--raw-ir file] [--optimized-ir file] [--no-optimize] [--interpret|--interpret-fast] [--library] [--timings]\n  [--bedrock file] [--foundation file] [--depfile file] [--help] [--version]\n";
}

export fn driver_version(): u8* {
    return "Tower development (hybrid bootstrap; not a portable release)\n";
}

export fn driver_dispose(options: DriverOptions*): void {
    free(options.links);
    options.links = null;
    options.link_count = 0;
}

export fn driver_parse(options: DriverOptions*, argc: usize, argv: u8**, target: u8*): bool {
    options.source = "";
    options.output = "";
    options.target = target;
    options.emit = "exe";
    options.cc = "clang";
    options.linker = "";
    options.sysroot = "";
    options.raw = "";
    options.optimized = "";
    options.bedrock = "";
    options.foundation = "";
    options.depfile = "";
    options.links = null;
    options.link_count = 0;
    options.optimize = true;
    options.interpret = false;
    options.library = false;
    options.timings = false;
    options.help = false;
    options.version = false;
    options.fast = false;
    options.error = 0;
    options.argument = "";
    var index: usize = 1;
    loop {
        var end = index >= argc;
        if end {
            return true;
        }
        var arg = argv[index];
        index = index + 1;
        if driver_equal(arg, "--help") {
            options.help = true;
            return true;
        }
        if driver_equal(arg, "--version") {
            options.version = true;
            return true;
        }
        if driver_equal(arg, "--no-optimize") {
            options.optimize = false;
            continue;
        }
        if driver_equal(arg, "--interpret") {
            options.interpret = true;
            options.fast = false;
            continue;
        }
        if driver_equal(arg, "--interpret-fast") {
            options.interpret = true;
            options.fast = true;
            continue;
        }
        if driver_equal(arg, "--timings") {
            options.timings = true;
            continue;
        }
        if driver_equal(arg, "--library") {
            options.library = true;
            options.emit = "object";
            continue;
        }
        var slot: u8** = null;
        if driver_equal(arg, "-o") {
            slot = &options.output;
        }
        if driver_equal(arg, "--target") {
            slot = &options.target;
        }
        if driver_equal(arg, "--emit") {
            slot = &options.emit;
        }
        if driver_equal(arg, "--cc") {
            slot = &options.cc;
        }
        if driver_equal(arg, "--linker") {
            slot = &options.linker;
        }
        if driver_equal(arg, "--sysroot") {
            slot = &options.sysroot;
        }
        if driver_equal(arg, "--raw-ir") {
            slot = &options.raw;
        }
        if driver_equal(arg, "--optimized-ir") {
            slot = &options.optimized;
        }
        if driver_equal(arg, "--bedrock") {
            slot = &options.bedrock;
        }
        if driver_equal(arg, "--foundation") {
            slot = &options.foundation;
        }
        if driver_equal(arg, "--depfile") {
            slot = &options.depfile;
        }
        var link = driver_equal(arg, "--link");
        var valued = slot != null;
        if link {
            valued = true;
        }
        if valued {
            var missing = index == argc;
            if missing {
                options.error = 1;
                options.argument = arg;
                return false;
            }
            var value = argv[index];
            index = index + 1;
            if link {
                var unallocated = options.links == null;
                if unallocated {
                    // argc bounds the number of link values. One allocation;
                    // failure leaves the options safely disposable.
                    options.links = alloc(u8*, argc);
                    var failed = options.links == null;
                    if failed {
                        options.error = 3;
                        options.argument = arg;
                        return false;
                    }
                }
                options.links[options.link_count] = value;
                options.link_count = options.link_count + 1;
            } else {
                *slot = value;
            }
            continue;
        }
        var option = arg[0] == 45;
        var have_source = options.source[0] != 0;
        var unexpected = option;
        if have_source {
            unexpected = true;
        }
        if unexpected {
            options.error = 2;
            options.argument = arg;
            return false;
        }
        options.source = arg;
    }
    return true;
}

import tower;

// Host policies consume explicit inputs. Locating the running executable is an
// OS service supplied by the caller; argv[0] alone is not a resolved filename.
// Resource text uses the shared buffer and has a borrowed terminating NUL.
export fn driver_resource_root(out: ByteBuffer*, executable: u8*): bool {
    var i: usize = 0;
    var boundary: usize = 0;
    loop {
        var c = executable[i];
        var end = c == 0;
        if end {
            break;
        }
        i = i + 1;
        var separator = c == 47;
        var windows = c == 92;
        if windows {
            separator = true;
        }
        if separator {
            boundary = i;
        }
    }
    var missing = boundary == 0;
    if missing {
        return false;
    }
    out.length = 0;
    var ok = bytes_append(out, executable, boundary);
    if ok {
        ok = bytes_append(out, "share/tower", 11);
    }
    if ok {
        ok = host_text_terminate(out);
    }
    return ok;
}

// Diagnostic columns count UTF-8 scalars, retaining the original driver's
// policy for offsets inside a scalar, CRLF and offsets beyond the input.
export fn driver_source_position(source: u8*, count: usize, offset: usize, line: usize*, column: usize*): void {
    *line = 1;
    *column = 1;
    var past = offset > count;
    if past {
        offset = count;
    }
    var i: usize = 0;
    loop {
        var done = i == offset;
        if done {
            return;
        }
        var c = source[i];
        var newline = c == 10;
        if newline {
            *line = *line + 1;
            *column = 1;
        } else {
            var prefix = c & 192;
            var first = prefix != 128;
            if first {
                *column = *column + 1;
            }
        }
        i = i + 1;
    }
}

export fn driver_output_name(emit: u8*, wasm: bool, windows: bool): u8* {
    if driver_equal(emit, "object") {
        return "tower.o";
    }
    if driver_equal(emit, "llvm") {
        return "tower.ll";
    }
    if driver_equal(emit, "llvm-optimized") {
        return "tower.ll";
    }
    if wasm {
        return "tower.wasm";
    }
    if windows {
        return "tower.exe";
    }
    return "tower.out";
}

export fn driver_output_valid(emit: u8*): bool {
    if driver_equal(emit, "bytecode") {
        return true;
    }
    if driver_equal(emit, "foundation") {
        return true;
    }
    if driver_equal(emit, "object") {
        return true;
    }
    if driver_equal(emit, "llvm") {
        return true;
    }
    if driver_equal(emit, "llvm-optimized") {
        return true;
    }
    return driver_equal(emit, "exe");
}

import tower;

// The highest lifecycle ID belongs to the shared Foundation payload. Native
// callback IDs retain their existing values during the frontend transition.
// Keep this object separate from allocation: utility-only clients need no graph.
extern fn foundation_node_dispose(data: void*): void;

extern fn compiler_native_finalize(kind: usize, component: void*, data: void*): void;

export fn tower_entity_finalize(kind: usize, component: void*, data: void*): void {
    var foundation: usize = 0;
    foundation = foundation - 1;
    var selected = kind == foundation;
    if selected {
        foundation_node_dispose(data);
    } else {
        compiler_native_finalize(kind, component, data);
    }
}

import tower;

// Raw-address arena allocator. Metadata describes free storage, never pointer
// validity, ownership generations or object identity. The caller supplies a
// contiguous committed address range and extends it after platform memory growth.
// Compile for the guest target: usize, pointers and headers use that target.
struct GuestBlock {
    size: usize;
    next: GuestBlock*;
    reserved: usize[2];
}

struct GuestHeap {
    available: GuestBlock*;
    cursor: usize;
    limit: usize;
}

export fn guest_heap_init(heap: GuestHeap*, begin: u8*, end: u8*): bool {
    fill(heap, 0, sizeof(GuestHeap));
    var first = bits(usize, begin);
    var limit = bits(usize, end);
    var invalid = first == 0;
    if invalid {
        return false;
    }
    var aligned = first + 15;
    invalid = aligned < first;
    if invalid {
        return false;
    }
    aligned = aligned / 16;
    aligned = aligned * 16;
    invalid = aligned > limit;
    if invalid {
        return false;
    }
    heap.cursor = aligned;
    heap.limit = limit;
    return true;
}

// The platform must commit the entire extension before publishing its limit.
// This call never moves existing allocations or frees a failed realloc's input.
export fn guest_heap_extend(heap: GuestHeap*, end: u8*): bool {
    var limit = bits(usize, end);
    var invalid = limit < heap.limit;
    if invalid {
        return false;
    }
    heap.limit = limit;
    return true;
}

export fn guest_heap_allocate(heap: GuestHeap*, count: usize, size: usize): void* {
    var maximum: usize = 0;
    maximum = maximum - 1;
    var sized = size != 0;
    if sized {
        var limit = maximum / size;
        var overflow = count > limit;
        if overflow {
            return null;
        }
    }
    var bytes = count * size;
    var limit = maximum - 15;
    var overflow = bytes > limit;
    if overflow {
        return null;
    }
    bytes = bytes + 15;
    bytes = bytes / 16;
    bytes = bytes * 16;
    var empty = bytes == 0;
    if empty {
        bytes = 16;
    }
    var header = sizeof(GuestBlock);
    var link: GuestBlock** = &heap.available;
    loop {
        var block = *link;
        var absent = block == null;
        if absent {
            break;
        }
        var enough = block.size >= bytes;
        if enough {
            var spare = block.size - bytes;
            var minimum = header + 16;
            var split = spare >= minimum;
            if split {
                var data = bits(u8*, block);
                data = data + header;
                data = data + bytes;
                var remainder = bits(GuestBlock*, data);
                remainder.size = spare - header;
                remainder.next = block.next;
                *link = remainder;
                block.size = bytes;
            } else {
                *link = block.next;
            }
            var result = block + 1;
            return bits(void*, result);
        }
        link = &block.next;
    }
    var remaining = heap.limit - heap.cursor;
    var short_header = remaining < header;
    if short_header {
        return null;
    }
    remaining = remaining - header;
    var short_data = remaining < bytes;
    if short_data {
        return null;
    }
    var block = bits(GuestBlock*, heap.cursor);
    block.size = bytes;
    heap.cursor = heap.cursor + header;
    heap.cursor = heap.cursor + bytes;
    var result = block + 1;
    return bits(void*, result);
}

fn guest_heap_merge(block: GuestBlock*): void {
    var next = block.next;
    var present = next != null;
    if present {
        var data = block + 1;
        var end = bits(u8*, data);
        end = end + block.size;
        var adjacent = end == bits(u8*, next);
        if adjacent {
            block.size = block.size + sizeof(GuestBlock);
            block.size = block.size + next.size;
            block.next = next.next;
        }
    }
}

export fn guest_heap_free(heap: GuestHeap*, pointer: void*): void {
    var absent = pointer == null;
    if absent {
        return;
    }
    var block = bits(GuestBlock*, pointer);
    block = block - 1;
    var address = bits(usize, block);
    var previous: GuestBlock* = null;
    var link: GuestBlock** = &heap.available;
    var previous_link: GuestBlock** = link;
    loop {
        var next = *link;
        absent = next == null;
        if absent {
            break;
        }
        var follows = bits(usize, next) >= address;
        if follows {
            break;
        }
        previous = next;
        previous_link = link;
        link = &next.next;
    }
    block.next = *link;
    *link = block;
    guest_heap_merge(block);
    var present = previous != null;
    if present {
        var data = previous + 1;
        var previous_end = bits(u8*, data);
        previous_end = previous_end + previous.size;
        var adjacent = previous_end == bits(u8*, block);
        guest_heap_merge(previous);
        if adjacent {
            block = previous;
            link = previous_link;
        }
    }
    // Reclaim a free tail into the unused arena. Otherwise a large allocation
    // can fail despite one contiguous free span straddling the cursor.
    var data = block + 1;
    var end = bits(usize, data) + block.size;
    var tail = end == heap.cursor;
    if tail {
        heap.cursor = bits(usize, block);
        *link = block.next;
    }
}

export fn guest_heap_reallocate(heap: GuestHeap*, pointer: void*, count: usize, size: usize): void* {
    var maximum: usize = 0;
    maximum = maximum - 1;
    var sized = size != 0;
    if sized {
        var limit = maximum / size;
        var overflow = count > limit;
        if overflow {
            return null;
        }
    }
    var absent = pointer == null;
    if absent {
        return guest_heap_allocate(heap, count, size);
    }
    var bytes = count * size;
    var empty = bytes == 0;
    if empty {
        guest_heap_free(heap, pointer);
        return null;
    }
    var block = bits(GuestBlock*, pointer);
    block = block - 1;
    var enough = block.size >= bytes;
    if enough {
        return pointer;
    }
    var result = guest_heap_allocate(heap, count, size);
    var ok = result != null;
    if ok {
        copy(result, pointer, block.size);
        guest_heap_free(heap, pointer);
    }
    return result;
}

import tower;

// Compiler allocation policy, separate from guest raw-address allocation.
// A null state selects production behavior; tests explicitly supply a state.
// The borrowed native allocator is the platform libc (wasi-libc in reactors).
struct CompilerMemoryState {
    live_buffers: usize;
    allocation_calls: usize;
    fail_after: usize;
}

// Optional compiler diagnostics only. Foundation guest pointers remain raw.
// Contexts are single-owner; concurrent compiler sessions use separate contexts.
struct CompilerNodeMemoryState {
    live_allocations: usize;
}

extern fn abort(): void;

fn compiler_memory_guard(): usize {
    var guard: u64 = 16045690984833335023;
    var narrow = sizeof(usize) == 4;
    if narrow {
        guard = 3735928559;
    }
    return convert(usize, guard);
}

export fn compiler_node_allocate(state: CompilerNodeMemoryState*, size: usize, diagnostic: bool): void* {
    var bytes = size;
    var word = sizeof(usize);
    if diagnostic {
        var maximum: usize = 0;
        maximum = maximum - 1;
        var overhead = word * 4;
        overhead = overhead - 1;
        var limit = maximum - overhead;
        var overflow = size > limit;
        if overflow {
            return null;
        }
        var padding = word - 1;
        bytes = size + padding;
        bytes = bytes / word;
        bytes = bytes * word;
        var guards = word * 3;
        bytes = bytes + guards;
    }
    // A successful zero-size request still owns a releasable allocation.
    var empty = bytes == 0;
    if empty {
        bytes = 1;
    }
    var memory = compiler_host_reallocate(null, bytes);
    var failed = memory == null;
    if failed {
        return null;
    }
    state.live_allocations = state.live_allocations + 1;
    if diagnostic {
        var header = bits(usize*, memory);
        var overhead = word * 3;
        var payload = bytes - overhead;
        header[0] = payload;
        header[1] = compiler_memory_guard();
        var end = payload / word;
        end = end + 2;
        header[end] = compiler_memory_guard();
        var data = &header[2];
        fill(data, 219, payload);
        return bits(void*, data);
    }
    return memory;
}

export fn compiler_node_free(state: CompilerNodeMemoryState*, pointer: void*, diagnostic: bool): void {
    var absent = pointer == null;
    if absent {
        return;
    }
    var empty = state.live_allocations == 0;
    if empty {
        abort();
        return;
    }
    var allocation = pointer;
    if diagnostic {
        var header = bits(usize*, pointer);
        header = header - 2;
        var guard = compiler_memory_guard();
        var corrupted = header[1] != guard;
        if corrupted {
            abort();
            return;
        }
        var bytes = header[0];
        var end = bytes / sizeof(usize);
        end = end + 2;
        corrupted = header[end] != guard;
        if corrupted {
            abort();
            return;
        }
        var overhead = sizeof(usize) * 3;
        bytes = bytes + overhead;
        fill(header, 254, bytes);
        allocation = bits(void*, header);
    }
    state.live_allocations = state.live_allocations - 1;
    compiler_host_deallocate(allocation);
}

extern fn compiler_host_reallocate(pointer: void*, bytes: usize): void*;

extern fn compiler_host_deallocate(pointer: void*): void;

export fn compiler_memory_reallocate(state: CompilerMemoryState*, pointer: void*, count: usize, size: usize): void* {
    var maximum: usize = 0;
    maximum = maximum - 1;
    var sized = size != 0;
    if sized {
        var limit = maximum / size;
        var overflow = count > limit;
        if overflow {
            return null;
        }
    }
    var instrumented = state != null;
    if instrumented {
        state.allocation_calls = state.allocation_calls + 1;
        var armed = state.fail_after != maximum;
        if armed {
            var fail = state.fail_after == 0;
            if fail {
                state.fail_after = maximum;
                return null;
            }
            state.fail_after = state.fail_after - 1;
        }
    }
    var bytes = count * size;
    var empty = bytes == 0;
    if empty {
        compiler_memory_deallocate(state, pointer);
        return null;
    }
    var fresh = pointer == null;
    var result = compiler_host_reallocate(pointer, bytes);
    if instrumented {
        if fresh {
            var allocated = result != null;
            if allocated {
                state.live_buffers = state.live_buffers + 1;
            }
        }
    }
    return result;
}

export fn compiler_memory_deallocate(state: CompilerMemoryState*, pointer: void*): void {
    var instrumented = state != null;
    if instrumented {
        var live = pointer != null;
        if live {
            state.live_buffers = state.live_buffers - 1;
        }
    }
    compiler_host_deallocate(pointer);
}

import tower;

// Formatting shared by platform print and trap paths. No host locale, sprintf,
// allocation or implicit host pointer width enters the result.
export fn runtime_format_value(output: u8*, capacity: usize, kind: u32, value: u64, pointer_bytes: u32): usize {
    var buffer: u8[80];
    var length: usize = 0;
    var boolean = kind == 2;
    if boolean {
        var truth = value != 0;
        if truth {
            copy(&buffer[0], "true\n", 5);
            length = 5;
        } else {
            copy(&buffer[0], "false\n", 6);
            length = 6;
        }
    } else {
        var pointer = kind == 3;
        if pointer {
            var valid = pointer_bytes == 4;
            if valid {} else {
                valid = pointer_bytes == 8;
            }
            if valid {} else {
                return 0;
            }
            buffer[0] = 48;
            buffer[1] = 120;
            var digits = convert(usize, pointer_bytes) * 2;
            length = digits + 2;
            var at = length;
            var hex = "0123456789abcdef";
            loop {
                var done = at == 2;
                if done {
                    break;
                }
                at = at - 1;
                var index = value % 16;
                buffer[at] = hex[index];
                value = value / 16;
            }
        } else {
            var narrow = kind == 0;
            var negative = false;
            if narrow {
                value = value & 4294967295;
                negative = value >= 2147483648;
            } else {
                var signed = kind == 6;
                if signed {
                    negative = value >= 9223372036854775808;
                }
            }
            if negative {
                buffer[0] = 45;
                length = 1;
                var zero: u64 = 0;
                value = zero - value;
                if narrow {
                    value = value & 4294967295;
                }
            }
            var digits: u8[24];
            var count: usize = 0;
            loop {
                var digit = value % 10;
                digit = digit + 48;
                digits[count] = convert(u8, digit);
                count = count + 1;
                value = value / 10;
                var done = value == 0;
                if done {
                    break;
                }
            }
            loop {
                var done = count == 0;
                if done {
                    break;
                }
                count = count - 1;
                buffer[length] = digits[count];
                length = length + 1;
            }
        }
        buffer[length] = 10;
        length = length + 1;
    }
    var enough = capacity >= length;
    if enough {
        copy(output, &buffer[0], length);
        return length;
    }
    return 0;
}

extern fn platform_write(stream: u32, data: u8*, length: usize): i64;

// Preserve short-write progress; an error/zero write cannot spin forever.
export fn runtime_write_all(stream: u32, data: u8*, length: usize): bool {
    var valid = stream == 1;
    if valid {} else {
        valid = stream == 2;
    }
    if valid {} else {
        return false;
    }
    var at: usize = 0;
    loop {
        var done = at == length;
        if done {
            return true;
        }
        var remaining = length - at;
        var written = platform_write(stream, &data[at], remaining);
        var failed = written <= 0;
        if failed {
            return false;
        }
        var count = convert(u64, written);
        var invalid = count > convert(u64, remaining);
        if invalid {
            return false;
        }
        at = at + convert(usize, count);
    }
}

export fn runtime_print_value(kind: u32, value: u64, pointer_bytes: u32): bool {
    var buffer: u8[80];
    var length = runtime_format_value(&buffer[0], 80, kind, value, pointer_bytes);
    var invalid = length == 0;
    if invalid {
        return false;
    }
    return runtime_write_all(1, &buffer[0], length);
}

